INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C1','kor',6,1,'u6',1,'비판적 읽기의 뜻 — 비판적으로 읽는다는 것은 글을 그대로 받아들이지 않고 내용과 표현이 알맞은지 판단하며 읽는 것으로, 게시판에 붙어 있거나 책에 적혀 있다고 해서 모두 옳은 것은 아니다',ARRAY['6국02-03 읽기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C2','kor',6,1,'u6',1,'「이상하다」는 물음 — 읽다가 의문이 드는 곳 · 받아들이기 어려운 곳 · 오해하기 쉬운 곳을 「이상한데?」 하고 멈추어 짚는 것이 비판적 읽기의 첫걸음이며, 그 물음을 그냥 넘기지 않고 어디가 왜 이상한지 따져 본다',ARRAY['6국02-03 읽기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C3','kor',6,1,'u6',1,'판단하며 읽기의 두 갈래 — 글은 「무엇을 말하는가」와 「어떻게 말하는가」로 이루어져 있어, 내용의 타당성(주장 · 이유 · 근거가 이치에 맞는가)과 표현의 적절성(거짓 · 과장 · 감춤이 없는가)을 함께 살핀다',ARRAY['6국02-03 읽기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C4','kor',6,1,'u6',1,'글의 목적에 따라 살필 것 — 주장하는 글에서는 그 주장이 나에게 도움이 되는지, 물건을 알리는 광고에서는 특징을 제대로 나타냈는지, 무엇을 알려 주는 글에서는 그 정보를 믿을 만한지를 먼저 살핀다',ARRAY['6국02-03 읽기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C5','kor',6,1,'u6',1,'비판은 흠 잡기가 아니다 — 틀린 데를 많이 찾을수록 잘 읽은 것이 아니라, 맞는 곳은 받아들이고 이상한 곳은 까닭을 대며 짚는 것이 비판적 읽기이며, 그 목적은 글을 깎아내리는 것이 아니라 나에게 필요한 정보를 골라내는 것이다',ARRAY['6국02-03 읽기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C6','kor',6,1,'u6',1,'판단에는 언제나 까닭 — 「이상해」 · 「별로야」처럼 까닭 없는 판단은 판단이 아니라 기분이며, 그렇게 판단한 까닭을 함께 대야 다른 사람이 따져 보고 고칠 곳을 알 수 있다',ARRAY['6국02-03 읽기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C7','kor',6,1,'u6',2,'주장하는 글의 짜임과 주장 찾기 — 서론은 관심을 끌고 글의 방향을 알리고, 본론은 이유와 그 이유를 받치는 근거를 내놓고, 결론은 글을 마무리하며 주장을 다시 정리하므로, 서론과 결론이 함께 가리키는 말이 주장이다',ARRAY['6국02-03 읽기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C8','kor',6,1,'u6',2,'타당성의 뜻 — 타당성은 이치에 맞는 옳은 성질이고, 내용의 타당성은 글의 내용이 이치에 맞게 옳은지를 말하며, 「주장은 가치 있고 중요한가 · 이유는 주장을 뒷받침하는가 · 근거는 이유를 뒷받침하는가」 세 물음으로 잰다',ARRAY['6국02-03 읽기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C9','kor',6,1,'u6',2,'기준 하나 — 주장의 가치 — 주장이 가치 있고 중요한지는 그 주장이 여러 사람에게 도움이 되는가와 많은 사람이 받아들일 수 있는가로 재며, 하자는 대로 했을 때 다른 문제가 생기는 주장(물을 아끼려면 세수를 하지 말자)은 가치 있다고 보기 어렵다',ARRAY['6국02-03 읽기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C10','kor',6,1,'u6',2,'기준 둘 — 이유의 뒷받침 — 이유는 주장과 관련이 있고 많은 사람이 받아들일 수 있어야 하며, 맞는 말이라도 주장과 이어지지 않으면(도서관 책을 접지 말자 ← 도서관은 조용한 곳이다) 이유가 되지 못한다 — 참인 문장이라고 다 이유는 아니다',ARRAY['6국02-03 읽기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C11','kor',6,1,'u6',2,'주장과 어긋나는 이유 — 이유가 주장과 반대 방향을 가리키면(급식을 남기지 말자 ← 반찬을 골라 먹는 재미가 있다) 글은 오히려 힘을 잃으므로, 이유를 넣기 전에 「이 문장이 내 주장 편에 서 있는가」를 묻는다',ARRAY['6국02-03 읽기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C12','kor',6,1,'u6',2,'기준 셋 — 근거의 뒷받침 — 근거는 이유와 관련이 있고 객관적인 사실이나 정보를 활용해야 하며, 담당하시는 분께 여쭈어 확인한 사실은 근거가 되지만 「늘어난 것 같다」는 한 사람의 짐작은 근거가 되지 못한다',ARRAY['6국02-03 읽기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C13','kor',6,1,'u6',2,'타당성은 어느 글에서나 — 타당성은 주장하는 글에서만 재는 것이 아니라 알림글 · 소식 · 설명하는 글처럼 내용을 담은 글이면 어디에든 같은 물음으로 물어볼 수 있다',ARRAY['6국02-03 읽기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C14','kor',6,1,'u6',2,'스스로 세우는 판단 기준 — 판단 기준은 세 가지만 있는 것이 아니라 「거짓 정보는 없는가」 · 「한쪽으로 치우치지 않았는가」 · 「쓸데없는 정보가 들어 있지 않은가」처럼 알맞은 기준을 물음의 꼴로 스스로 더 세워 써도 좋다',ARRAY['6국02-03 읽기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C15','kor',6,1,'u6',4,'적혀 있어도 한 번 더 확인 — 글에 적혀 있다고 해서 모두 그대로 일어나지는 않으므로, 큰 글씨만 읽고 넘어가지 말고 작은 글씨와 뒷부분까지 읽으며 읽는 사람이 한 번 더 확인한다',ARRAY['6국02-03 읽기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C16','kor',6,1,'u6',4,'이유와 근거 짝짓기 — 한 편의 글을 판단하려면 먼저 근거가 어느 이유에 붙는지 잡아야 하며, 주장하는 글에서는 대개 이유와 그 근거가 같은 문단 안에 붙어 있다',ARRAY['6국02-03 읽기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C17','kor',6,1,'u6',4,'판단과 까닭은 한 짝 — 「가치 있다 — 다치는 일을 줄여 주고 누구나 받아들일 만하므로」처럼 판단에 까닭이 붙은 답이 좋은 답이며, 「글에 그렇게 적혀 있으므로」는 판단이 같아도 까닭이 되지 못한다',ARRAY['6국02-03 읽기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C18','kor',6,1,'u6',4,'사실이 아닌 이유 — 「안전모를 쓰면 자전거가 더 빨리 달린다」처럼 실제로 일어나지 않는 일을 이유로 들면 이유가 되지 못할 뿐 아니라 읽는 사람을 잘못 알게 하며, 한 문장이 「사실이 아님」과 「주장과 어긋남」 두 곳에 함께 걸리기도 한다',ARRAY['6국02-03 읽기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C19','kor',6,1,'u6',4,'되짚어 확인할 수 있는 근거 — 직접 세어 본 기록 · 물건에 적힌 안내 · 담당하시는 분께 여쭈어본 답처럼 다른 사람도 같은 길로 다시 가 볼 수 있는 것이 좋은 근거이며, 한 사람에게서 전해 들은 말은 누구도 다시 확인할 수 없어 근거가 되기 어렵다',ARRAY['6국02-03 읽기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C20','kor',6,1,'u6',4,'차례대로 재기 — 한 편의 글은 주장 → 이유 → 근거의 차례로 세 기준을 하나씩 대어 재며, 판단할 때마다 왜 그렇게 판단했는지를 함께 말한다',ARRAY['6국02-03 읽기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C21','kor',6,1,'u6',4,'받아들일 것을 골라내기 — 걸린 곳을 찾았다고 글 전체를 버리지 않으며, 한 편의 글은 고르게 타당하지도 고르게 부족하지도 않으므로 걸린 곳만 까닭을 대어 짚고 타당한 부분은 받아들인다 — 받아들일 것을 골라내는 일도 판단이다',ARRAY['6국02-03 읽기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C22','kor',6,1,'u6',4,'둘레의 글에 대어 보기 — 교실 게시판 · 학교 누리집 · 물건 포장에 적힌 글에서도 주장 · 이유 · 근거를 옮겨 적고 세 기준으로 재며, 걸리는 곳은 왜 걸리는지와 어떻게 고치면 좋을지를 함께 적는다',ARRAY['6국02-03 읽기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C23','kor',6,1,'u6',7,'표현의 적절성 — 앞에서 글이 무엇을 말하는가를 재었다면, 표현의 적절성은 그것을 어떻게 말하는가 — 그 내용을 알맞은 말로 나타냈는가를 재는 것이며, 가장 눈에 띄게 말하는 광고에서부터 살펴본다',ARRAY['6국02-03 읽기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C24','kor',6,1,'u6',7,'광고가 뜻을 전하는 방법 — 광고는 글 · 그림 · 색 · 크기 · 배치로 뜻을 전하므로 큰 글씨 · 진한 색 · 느낌표는 「여기를 봐 달라」는 자국이며, 무엇을 크게 했는지만큼 무엇을 작게 했는지도 보아야 한다',ARRAY['6국02-03 읽기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C25','kor',6,1,'u6',7,'거짓된 표현 — 거짓된 표현은 없는 것을 있는 것처럼 말한 표현으로, 물통 광고의 「뚜껑을 열어도 얼음이 녹지 않아요」처럼 실제로 일어날 수 없는 일을 있다고 말한 것이다(뚜껑을 열면 바깥 공기가 바로 들어온다)',ARRAY['6국02-03 읽기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C26','kor',6,1,'u6',7,'과장된 표현 — 과장된 표현은 있는 것을 실제보다 부풀린 표현으로, 「무조건 · 절대 · 최고 · 백 퍼센트」나 「이것 하나면 끝」 같은 말은 보는 사람의 판단을 흐린다',ARRAY['6국02-03 읽기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C27','kor',6,1,'u6',7,'감추는 내용 — 감추는 내용은 알아야 할 것을 밝히지 않은 것으로, 「가장 많이 팔린」처럼 언제 · 어디에서 · 무엇과 견주었는지 빠졌거나 꼭 알려야 할 조건을 눈에 들어오지 않을 만큼 작게 적은 것이다 — 읽고 나서 「그런데 어디에서?」가 남는다',ARRAY['6국02-03 읽기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C28','kor',6,1,'u6',7,'거짓과 과장을 가르는 자 — 거짓과 과장은 「그 기능이 실제로 있는가」로 가르며, 없는 기능을 있다고 하면 거짓, 있는 기능을 부풀리면 과장이다(새지 않게 만든 뚜껑을 「절대 새지 않는다」고 하면 과장)',ARRAY['6국02-03 읽기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C29','kor',6,1,'u6',7,'한 표현이 두 기준에 — 「이보다 좋은 물통은 없습니다」는 실제보다 부풀린 과장이면서 어떤 점에서 좋다는 것인지 밝히지 않은 감춤이기도 하듯, 한 문구가 두 기준에 함께 걸릴 수 있으며 기준은 서로를 밀어내지 않는다',ARRAY['6국02-03 읽기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C30','kor',6,1,'u6',7,'광고만의 일이 아니다 — 부풀리고 감추는 일은 광고만의 특성이 아니라 설득하려는 글이면 어디서든 일어날 수 있고, 부풀리지 않았다고 다 믿을 수 있는 것도 아니라 오래되어 지금과 맞지 않거나 두루뭉술해 오해하게 만드는 정보도 믿기 어려운 표현이다',ARRAY['6국02-03 읽기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C31','kor',6,1,'u6',7,'둘레의 광고 재어 보기 — 둘레의 광고 하나를 골라 눈에 띄는 문구를 옮겨 적고 세 기준으로 ○와 ×를 매기되, 매길 때마다 그렇게 판단한 까닭을 한 줄씩 함께 적는다',ARRAY['6국02-03 읽기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C32','kor',6,1,'u6',9,'설명하는 글에서 더 조심할 까닭 — 광고는 알리려고 쓴 글인 줄 알고 걸러 읽지만 설명하는 글은 알려 주려고 쓴 글이라 여겨 그대로 외우기 쉬우므로, 거짓된 표현은 잘못된 지식이, 과장된 표현은 지나친 믿음이, 감추는 내용은 한쪽만 아는 사람이 된다',ARRAY['6국02-03 읽기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C33','kor',6,1,'u6',9,'기준 하나로 글 전체를 훑기 — 한 문단에서 세 기준을 한꺼번에 재려 하면 놓치기 쉬우므로, 거짓된 표현을 들고 글 전체를 훑고, 다시 과장을, 마지막으로 감춤을 들고 처음부터 훑는다',ARRAY['6국02-03 읽기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C34','kor',6,1,'u6',9,'넓게 말하는 말에 멈추기 — 설명하는 글에서 「대부분 · 모두 · 언제나」 같은 말이 나오면 한 번 멈추어 그렇게 넓게 말할 만한 사실인지 묻고, 확인할 수 있는 만큼만 말했는지 본다',ARRAY['6국02-03 읽기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C35','kor',6,1,'u6',9,'과장은 알아채기 더 어렵다 — 과장된 표현은 거짓말이 아니라 있는 것을 부풀린 말이어서 더 알아채기 어렵고, 읽는 사람이 지나치게 믿게 만든다',ARRAY['6국02-03 읽기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C36','kor',6,1,'u6',9,'감춤은 한쪽만 알게 한다 — 감추는 내용은 틀린 말을 하지 않으면서도 읽는 사람을 한쪽만 알게 하므로(「옹기는 어디에나 놓아도 좋다」 — 무겁고 잘 깨진다는 점을 빼놓음), 읽고 나서 되묻고 싶은 것이 남으면 그 자국을 따라간다',ARRAY['6국02-03 읽기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C37','kor',6,1,'u6',9,'걸린 문장 고쳐 쓰기 — 거짓은 확인할 수 있는 만큼만 말하게, 과장은 부풀린 것을 덜어 내 있는 만큼 말하게, 감춤은 알아야 할 것을 더 밝히게 고쳐 쓰며, 고쳐 쓸 줄 알아야 판단이 끝까지 간 것이다',ARRAY['6국02-03 읽기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C38','kor',6,1,'u6',9,'다른 관점의 글 더 찾아 읽기 — 한 편의 글은 한쪽(좋은 점)만 드러낼 수 있으므로 「불편한 점은 없었을까?」 · 「왜 오늘날에는 덜 쓸까?」처럼 다른 쪽에서 물음을 세우고, 관련 있는 글을 더 찾아 읽어 그 글에 없던 사실을 보태며 한 편만 읽고 판단하지 않는다',ARRAY['6국02-04 읽기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C39','kor',6,1,'u6',9,'까닭이 붙은 판단은 따져 볼 수 있다 — 까닭이 붙은 판단은 친구가 따져 보고 다른 답을 낼 수도 있으며, 까닭이 타당하면 나와 다른 판단도 받아들일 수 있다 — 판단은 하나로 정해진 답을 맞히는 일이 아니다',ARRAY['6국02-03 읽기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C40','kor',6,1,'u6',12,'판단하던 자를 뒤집어 만들기 — 읽을 때 걸렸던 것들(가치 없는 주장 · 어긋난 이유 · 확인할 수 없는 근거 · 거짓 · 과장 · 감춤)이 만들 때 하지 말아야 할 것이 되며, 남의 글에서 찾아낸 흠은 내 글에서도 똑같이 흠이다',ARRAY['6국02-03 읽기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C41','kor',6,1,'u6',12,'공익 광고의 주제 — 공익 광고는 여럿이 함께 겪는 문제 가운데 내가 겪었고 다른 사람도 겪으며 고치면 나아지는 일을 주제로 고르며, 이것은 「주장이 가치 있고 중요한가」를 만드는 쪽에서 묻는 일이다',ARRAY['6국02-03 읽기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C42','kor',6,1,'u6',12,'부풀린 문구 고쳐 쓰기 — 부풀린 문구는 뜻은 그대로 두고 크기만 줄여 고치며(「백 퍼센트 망가집니다」 → 「빌려준 지우개가 반으로 돌아왔습니다」), 덜어 낸 쪽은 힘이 약해지지 않고 보는 사람이 겪은 일에 더 가까워져 오히려 오래 남는다',ARRAY['6국02-03 읽기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C43','kor',6,1,'u6',12,'광고는 눈에 띄면서도 믿을 수 있게 — 광고는 짧은 시간과 좁은 지면에서 인상을 남겨야 하므로 「틀린 말만 없으면 된다」는 아무도 보지 않는 광고가 되고 「눈에 띄기만 하면 된다」는 믿을 수 없는 광고가 되며, 눈에 띄려고 손댄 곳은 발표할 때 그 까닭을 밝힌다',ARRAY['6국02-03 읽기']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C44','kor',6,1,'u6',12,'표현 요소 고르기 — 가장 하고 싶은 한 줄만 크게(다 크게 하면 아무것도 크지 않다) · 문제 장면은 그림이 대신 · 진한 색은 강조할 곳에만 · 꼭 알려야 할 조건은 읽을 수 있는 크기로 적는다',ARRAY['6국02-03 읽기']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C45','kor',6,1,'u6',12,'만든 뜻까지 발표하기 — 광고를 발표할 때에는 어떤 문제를 보고 주제를 골랐는지 · 어떤 표현 요소로 무엇을 강조했는지 · 눈에 띄려고 부풀린 곳이 있다면 그 까닭까지 밝히며, 「여기는 일부러 세게 썼다」고 스스로 밝히는 사람은 보는 사람을 속이지 않는다',ARRAY['6국02-03 읽기']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C46','kor',6,1,'u6',12,'친구의 광고 판단하기 — 친구의 광고는 사람이 아니라 문구를 두고, 어느 문구가 걸리는지 짚고 그렇게 판단한 까닭을 함께 말하며, 잘한 점과 보완할 점을 함께 말한다 — 판단은 결과와 근거가 한 짝이다',ARRAY['6국02-03 읽기']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C47','kor',6,1,'u6',12,'두 자를 한꺼번에 대기 — 내용의 타당성 세 물음과 표현의 적절성 세 물음, 여섯 물음을 주장하는 글 · 광고 · 설명하는 글에 그대로 대어 받아들일 것과 물릴 것을 스스로 가르며, 걸린 곳이 있어도 주장까지 버리지는 않는다',ARRAY['6국02-03 읽기']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C48','kor',6,1,'u6',12,'뜻을 혼동하기 쉬운 낱말 — 늘이다(본디보다 길게 하다) · 늘리다(수나 양을 많아지게 하다), 맞히다(답을 옳게 대다, 겨냥한 곳에 닿게 하다) · 맞추다(서로 대어 보다, 맞게 하다), 좇다(뜻이나 목표를 따르다) · 쫓다(몰아내다, 뒤를 급히 따라가다)는 소리가 비슷해도 쓰이는 곳이 다르다 (기초 다지기)',ARRAY['기초 다지기(우리말)']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u6-C49','kor',6,1,'u6',12,'맞춤법을 혼동하기 쉬운 말 — 「되어요」가 줄어든 「돼요」(안 되요 ✕), 몇 날을 뜻하는 한 낱말 「며칠」(몇일 ✕), 「오래간만에」가 줄어든 「오랜만에」(오랫만에 ✕), 병이 없어졌다는 「낫다」의 「나았다」(낳았다 ✕)처럼, 헷갈릴 때에는 본디 말로 늘여 보면 가려진다 (기초 다지기)',ARRAY['기초 다지기(우리말)']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X01','kor',6,'u6',ARRAY['K6-1-u6-C1']::text[],'게시판에 붙어 있거나 책에 적힌 글은 다 옳다고 여겨 그대로 받아들인다','붙어 있다고 다 맞나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X02','kor',6,'u6',ARRAY['K6-1-u6-C2']::text[],'읽다가 이상하다고 느껴도 그냥 넘어가, 그 물음이 비판적 읽기의 첫걸음인 줄 모른다','「이상한데?」에서 멈춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X03','kor',6,'u6',ARRAY['K6-1-u6-C3','K6-1-u6-C23']::text[],'판단하며 읽기를 내용만 따지는 일로 여겨 표현은 살피지 않거나, 두 갈래(타당성 · 적절성)를 헷갈린다','무엇을 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X04','kor',6,'u6',ARRAY['K6-1-u6-C4']::text[],'글의 목적과 상관없이 살필 것을 고르거나, 광고와 설명하는 글에서 살필 것을 헷갈린다','무엇을 하려고 쓴 글?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X05','kor',6,'u6',ARRAY['K6-1-u6-C5']::text[],'틀린 데를 많이 찾아낼수록 잘 읽은 것이라 여겨 맞는 말까지 트집을 잡는다','목적은 골라내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X06','kor',6,'u6',ARRAY['K6-1-u6-C6','K6-1-u6-C31','K6-1-u6-C39','K6-1-u6-C46']::text[],'「그냥 이상해」 · 「별로야」처럼 까닭 없이 판단한다','판단엔 까닭이 한 짝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X07','kor',6,'u6',ARRAY['K6-1-u6-C7']::text[],'서론 · 본론 · 결론의 몫을 헷갈리거나, 본론의 이유 하나를 글 전체의 주장으로 고른다','서론과 결론이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X08','kor',6,'u6',ARRAY['K6-1-u6-C8']::text[],'타당성을 글의 길이나 어려운 낱말의 수로 여긴다','이치에 맞게 옳은가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X09','kor',6,'u6',ARRAY['K6-1-u6-C9','K6-1-u6-C41']::text[],'하자는 대로 하면 다른 문제가 생기는 주장도 가치 있고 중요하다고 여긴다','여럿에게 도움이 되나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X10','kor',6,'u6',ARRAY['K6-1-u6-C10']::text[],'맞는 말이기만 하면 주장과 관련이 없어도 이유가 된다고 여긴다','주장과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X11','kor',6,'u6',ARRAY['K6-1-u6-C11']::text[],'주장과 반대 방향을 가리키는 이유도 이유가 된다고 여긴다','내 주장 편인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X12','kor',6,'u6',ARRAY['K6-1-u6-C12']::text[],'「∼한 것 같다」는 한 사람의 짐작을 옮긴 말도 근거가 된다고 여긴다','누가 직접 확인했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X13','kor',6,'u6',ARRAY['K6-1-u6-C13']::text[],'타당성은 주장하는 글에서만 잰다고 여겨 알림글 · 설명하는 글은 그대로 믿는다','내용을 담은 글이면 어디든') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X14','kor',6,'u6',ARRAY['K6-1-u6-C14']::text[],'판단 기준은 정해진 세 가지뿐이라 스스로 기준을 더 세우면 안 된다고 여긴다','물음의 꼴로 더 세워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X15','kor',6,'u6',ARRAY['K6-1-u6-C15','K6-1-u6-C24']::text[],'큰 글씨만 읽고 작은 글씨나 뒷부분은 확인하지 않아도 된다고 여긴다','작게 쓴 것도 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X16','kor',6,'u6',ARRAY['K6-1-u6-C16']::text[],'근거를 엉뚱한 이유에 붙여 놓고 판단한다','같은 문단 안에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X17','kor',6,'u6',ARRAY['K6-1-u6-C17']::text[],'「글에 그렇게 적혀 있으니까」를 판단의 까닭으로 든다','적혀 있는 건 까닭이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X18','kor',6,'u6',ARRAY['K6-1-u6-C18']::text[],'글에 이유로 적혀 있으면 사실일 것이라 여겨 실제로 일어나는 일인지 묻지 않는다','정말 그런 일이 일어나나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X19','kor',6,'u6',ARRAY['K6-1-u6-C19']::text[],'한 사람에게서 전해 들은 말도 누가 말했는지만 적혀 있으면 확인할 수 있는 근거라고 여긴다','다시 가 볼 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X20','kor',6,'u6',ARRAY['K6-1-u6-C20']::text[],'한 편의 글을 잴 때 기준을 차례 없이 뒤섞어 대다가 빠뜨린다','주장 → 이유 → 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X21','kor',6,'u6',ARRAY['K6-1-u6-C21','K6-1-u6-C47']::text[],'걸린 곳이 하나라도 있으면 글 전체를 믿을 수 없다며 버린다','받아들일 것도 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X22','kor',6,'u6',ARRAY['K6-1-u6-C22']::text[],'배운 기준은 공부 시간의 글에만 쓰고 둘레의 글에는 대어 보지 않는다','게시판 · 포장 글에도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X23','kor',6,'u6',ARRAY['K6-1-u6-C23']::text[],'표현의 적절성을 글씨가 예쁜지 · 문장이 긴지로 여긴다','어떻게 말했나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X24','kor',6,'u6',ARRAY['K6-1-u6-C24']::text[],'광고에서 크게 쓴 것만 보고, 무엇을 작게 썼는지는 살피지 않는다','작게 쓴 까닭도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X25','kor',6,'u6',ARRAY['K6-1-u6-C25','K6-1-u6-C28']::text[],'없는 기능을 있다고 한 거짓과 있는 기능을 부풀린 과장을 헷갈린다','그 기능이 실제로 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X26','kor',6,'u6',ARRAY['K6-1-u6-C26']::text[],'「절대 · 무조건 · 최고」 같은 말을 광고에 적혀 있으니 그대로 믿는다','어떤 경우에도 그럴까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X27','kor',6,'u6',ARRAY['K6-1-u6-C27','K6-1-u6-C36']::text[],'틀린 말이 없으면 감춘 것도 없다고 여겨, 언제 · 어디에서 · 무엇과 견주었는지 빠진 말을 그냥 믿는다','「그런데 어디에서?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X28','kor',6,'u6',ARRAY['K6-1-u6-C29']::text[],'한 표현은 한 가지 기준에만 걸린다고 여긴다','두 기준에 함께도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X29','kor',6,'u6',ARRAY['K6-1-u6-C30']::text[],'부풀리고 감추는 일은 광고에서만 일어난다고 여겨 주장하는 글 · 안내문은 그대로 믿는다','설득하려는 글이면 어디서든') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X30','kor',6,'u6',ARRAY['K6-1-u6-C30']::text[],'부풀리지 않았으면 오래되었거나 두루뭉술한 정보도 다 믿을 수 있다고 여긴다','오래된 · 흐린 정보') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X31','kor',6,'u6',ARRAY['K6-1-u6-C32']::text[],'설명하는 글은 알려 주려고 쓴 글이라 적힌 대로 외워도 된다고 여긴다','잘못된 지식이 될 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X32','kor',6,'u6',ARRAY['K6-1-u6-C33']::text[],'한 문단에서 세 기준을 한꺼번에 재려다 놓치거나, 글 전체를 훑지 않는다','기준 하나로 전체를') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X33','kor',6,'u6',ARRAY['K6-1-u6-C34']::text[],'「대부분 · 모두 · 언제나」 같은 넓게 말하는 말을 그냥 지나친다','그렇게 넓게 말할 만한가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X34','kor',6,'u6',ARRAY['K6-1-u6-C35']::text[],'과장된 표현은 거짓말이 아니니 그대로 믿어도 괜찮다고 여긴다','지나친 믿음이 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X35','kor',6,'u6',ARRAY['K6-1-u6-C37','K6-1-u6-C42']::text[],'걸린 문장을 찾기만 하고 고쳐 쓰지 못하거나, 고치면서 뜻까지 바꾼다','덜어 내기 · 더 밝히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X36','kor',6,'u6',ARRAY['K6-1-u6-C38']::text[],'한 편의 글만 읽고 판단을 끝내 다른 관점의 글을 찾아 읽지 않는다','다른 쪽에서 물어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X37','kor',6,'u6',ARRAY['K6-1-u6-C39']::text[],'나와 다른 판단은 까닭을 들어 보지도 않고 틀렸다고 여긴다','까닭이 타당한가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X38','kor',6,'u6',ARRAY['K6-1-u6-C40']::text[],'남의 글에서 찾은 흠을 내가 만들 때에는 괜찮다고 여긴다','내 글에서도 흠') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X39','kor',6,'u6',ARRAY['K6-1-u6-C41']::text[],'여럿에게 도움이 되지 않거나 고쳐도 나아지지 않는 일을 공익 광고의 주제로 고른다','고치면 나아지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X40','kor',6,'u6',ARRAY['K6-1-u6-C42']::text[],'부풀린 말을 덜어 내면 광고의 힘이 약해진다고 여긴다','사실에 가까운 말이 오래 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X41','kor',6,'u6',ARRAY['K6-1-u6-C43']::text[],'광고는 틀린 말만 없으면 눈에 띄지 않아도 된다고 여긴다','아무도 보지 않는 광고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X42','kor',6,'u6',ARRAY['K6-1-u6-C43','K6-1-u6-C45']::text[],'광고는 눈에 띄기만 하면 부풀리고 감춰도 된다고 여기거나, 일부러 세게 쓴 곳을 숨긴다','믿을 수 없는 광고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X43','kor',6,'u6',ARRAY['K6-1-u6-C44']::text[],'여러 줄을 다 크게 · 온통 진하게 하거나, 꼭 알릴 조건을 읽을 수 없을 만큼 작게 적는다','한 줄만 크게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X44','kor',6,'u6',ARRAY['K6-1-u6-C45']::text[],'광고를 발표할 때 결과물만 보이고 고른 까닭 · 강조한 것 · 세게 쓴 까닭은 말하지 않는다','만든 뜻까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X45','kor',6,'u6',ARRAY['K6-1-u6-C46']::text[],'친구의 광고를 판단할 때 문구가 아니라 만든 사람을 두고 말하거나, 잘한 점은 말하지 않는다','문구를 · 잘한 점도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X46','kor',6,'u6',ARRAY['K6-1-u6-C47','K6-1-u6-C3']::text[],'두 자 가운데 하나만 대고 판단을 끝낸다(내용만 보거나 표현만 본다)','여섯 물음을 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X47','kor',6,'u6',ARRAY['K6-1-u6-C48']::text[],'늘이다 · 늘리다, 맞히다 · 맞추다, 좇다 · 쫓다의 뜻을 헷갈려 바꾸어 쓴다','문장에 넣어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u6-X48','kor',6,'u6',ARRAY['K6-1-u6-C49']::text[],'「안 되요 · 몇일 · 오랫만에 · 낳았다」처럼 맞춤법을 틀리게 쓴다','본디 말로 늘여 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#1','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C1',1,'mc','auto','「비판적으로 읽는다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X01','K6-1-u6-X05','K6-1-u6-X03']::text[],false,'{"seq":1,"concept":"K6-1-u6-C1","difficulty":1,"kind":"mc","stem":"「비판적으로 읽는다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 그대로 받아들이지 않고 내용과 표현이 알맞은지 판단하며 읽는 것","correct":true},{"t":"적힌 내용을 믿고 그대로 외우며 읽는 것","mis":"K6-1-u6-X01"},{"t":"글에서 흠을 될수록 많이 찾아 깎아내리는 것","mis":"K6-1-u6-X05"},{"t":"소리 내어 또박또박 읽는 것","mis":"K6-1-u6-X03"}],"explanation":["그대로 믿는 것은 판단이 아니에요.","깎아내리는 것이 목적이 아니에요.","내용과 표현을 판단하며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#2','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C1',1,'ox','auto','게시판에 붙어 있는 글은 모두 옳은 내용이에요.',ARRAY['K6-1-u6-X01']::text[],false,'{"seq":2,"concept":"K6-1-u6-C1","difficulty":1,"kind":"ox","stem":"게시판에 붙어 있는 글은 모두 옳은 내용이에요.","answer":"X","reason_options":[{"t":"붙어 있다고 다 맞는 말은 아니어서 따져 보며 읽어야 하기 때문에","correct":true},{"t":"여러 사람이 보는 곳에 붙인 글이기 때문에","mis":"K6-1-u6-X01"}],"mis":"K6-1-u6-X01","explanation":["붙은 곳이 옳음을 보장하지 않아요.","여러 사람이 보는 글도 틀릴 수 있어요.","따져 보며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#3','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C2',1,'mc','auto','하영이가 「우리가 따져 보자」고 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X08','K6-1-u6-X05']::text[],false,'{"seq":3,"concept":"K6-1-u6-C2","difficulty":1,"kind":"mc","stem":"하영이가 「우리가 따져 보자」고 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"게시판에 붙어 있다고 다 맞는 말은 아니기 때문이다","correct":true},{"t":"글씨가 너무 작아 읽기 어렵기 때문이다","mis":"K6-1-u6-X15"},{"t":"글이 너무 길기 때문이다","mis":"K6-1-u6-X08"},{"t":"걸어 다니자는 주장이 틀렸기 때문이다","mis":"K6-1-u6-X05"}],"explanation":["글씨 크기 이야기가 아니에요.","길이 때문이 아니에요.","이상한 줄을 따져 보려는 거예요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"급식실 앞 게시판에 새 글이 붙었어. 걸어 다니자는 내용이야."},{"who":"하영","text":"맞는 말이네. 국을 들고 부딪히면 크게 다칠 수 있으니까."},{"who":"우재","text":"그런데 가운데에 이상한 줄이 하나 있어. 읽고 나서 고개가 갸웃해졌어."},{"who":"하영","text":"어디 보자. 붙어 있다고 다 맞는 말은 아니니까 우리가 따져 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#4','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C3',1,'match','auto','말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u6-C3","difficulty":1,"kind":"match","stem":"말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"내용의 타당성","r":"글에 담긴 내용이 이치에 맞고 옳은가"},{"l":"표현의 적절성","r":"그 내용을 알맞은 말로 나타냈는가"},{"l":"비판적으로 읽기","r":"두 가지를 함께 살피며 읽기"}],"mis":"K6-1-u6-X03","explanation":["타당성은 무엇을 말하는가예요.","적절성은 어떻게 말하는가예요.","둘을 함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#5','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C2',2,'mc','auto','이 글을 읽으며 「이상한데?」 하고 멈출 만한 문장은 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":5,"concept":"K6-1-u6-C2","difficulty":2,"kind":"mc","stem":"이 글을 읽으며 「이상한데?」 하고 멈출 만한 문장은 어느 것인가요?","options":[{"t":"뛰어다니면 키가 자라지 않습니다","correct":true},{"t":"뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다","mis":"K6-1-u6-X05"},{"t":"지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다","mis":"K6-1-u6-X05"},{"t":"급식실은 여러 사람이 함께 쓰는 곳입니다","mis":"K6-1-u6-X05"}],"explanation":["다치는 일과 이어진 맞는 말이에요.","이것도 실제로 일어나는 일이에요.","뛰는 일과 키는 관계가 없어요 — 바르게는 「뛰다가 넘어지면 크게 다칠 수 있습니다」예요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#6','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C4',2,'match','auto','읽는 글과 그 글에서 먼저 살필 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u6-C4","difficulty":2,"kind":"match","stem":"읽는 글과 그 글에서 먼저 살필 것을 알맞게 이으세요.","pairs":[{"l":"주장하는 글","r":"그 주장이 나에게 도움이 되는지"},{"l":"물건을 알리는 광고","r":"물건의 특징을 제대로 나타냈는지"},{"l":"무엇을 알려 주는 글","r":"알려 주는 정보를 믿을 만한지"}],"mis":"K6-1-u6-X04","explanation":["주장하는 글은 주장을 봐요.","광고는 특징을 제대로 나타냈는지 봐요.","글의 목적이 살필 것을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#7','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C5',2,'ox','auto','틀린 데를 많이 찾아낼수록 글을 잘 읽은 거예요.',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":7,"concept":"K6-1-u6-C5","difficulty":2,"kind":"ox","stem":"틀린 데를 많이 찾아낼수록 글을 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"맞는 곳은 받아들이고 이상한 곳만 까닭을 대어 짚는 것이 비판적 읽기이기 때문에","correct":true},{"t":"흠을 많이 찾을수록 글을 꼼꼼히 본 것이기 때문에","mis":"K6-1-u6-X05"}],"mis":"K6-1-u6-X05","explanation":["트집이 목적이 아니에요.","맞는 말까지 트집 잡게 돼요.","필요한 정보를 골라내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#8','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C6',2,'mc','auto','급식실 글을 판단한 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X05','K6-1-u6-X01']::text[],false,'{"seq":8,"concept":"K6-1-u6-C6","difficulty":2,"kind":"mc","stem":"급식실 글을 판단한 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「둘째 이유는 걸려. 뛰는 일과 키가 자라는 일은 관계가 없으니까.」","correct":true},{"t":"「둘째 이유는 그냥 이상해.」","mis":"K6-1-u6-X06"},{"t":"「이 글은 전부 엉터리야.」","mis":"K6-1-u6-X05"},{"t":"「게시판에 붙었으니 다 맞아.」","mis":"K6-1-u6-X01"}],"explanation":["까닭이 빠졌어요.","맞는 곳까지 버렸어요.","판단에 까닭이 붙었어요 — 그 문장은 「뛰다가 넘어지면 다칠 수 있다」로 바로잡아요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#9','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C3',2,'mc','auto','「거짓된 표현 · 부풀린 표현 · 감추는 내용이 없는가」를 살피는 갈래는 어느 것인가요?',ARRAY['K6-1-u6-X03','K6-1-u6-X23']::text[],false,'{"seq":9,"concept":"K6-1-u6-C3","difficulty":2,"kind":"mc","stem":"「거짓된 표현 · 부풀린 표현 · 감추는 내용이 없는가」를 살피는 갈래는 어느 것인가요?","options":[{"t":"표현의 적절성","correct":true},{"t":"내용의 타당성","mis":"K6-1-u6-X03"},{"t":"글의 짜임","mis":"K6-1-u6-X03"},{"t":"글씨의 바르기","mis":"K6-1-u6-X23"}],"explanation":["타당성은 주장 · 이유 · 근거를 봐요.","짜임과는 달라요.","어떻게 말했는지 보는 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_basic#10','kor',6,1,'u6','L01','g6_1_kor_u6_L01_basic','lesson_basic','K6-1-u6-C2',3,'mc','auto','「이상한데?」 하는 물음이 비판적 읽기의 첫걸음인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X06','K6-1-u6-X05']::text[],false,'{"seq":10,"concept":"K6-1-u6-C2","difficulty":3,"kind":"mc","stem":"「이상한데?」 하는 물음이 비판적 읽기의 첫걸음인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"어디가 왜 이상한지 따져 보게 되어 글을 그대로 받아들이지 않게 되기 때문이다","correct":true},{"t":"이상한 글은 바로 버려야 하기 때문이다","mis":"K6-1-u6-X21"},{"t":"이상하다고 말하면 판단이 끝나기 때문이다","mis":"K6-1-u6-X06"},{"t":"이상한 곳을 많이 찾을수록 좋기 때문이다","mis":"K6-1-u6-X05"}],"explanation":["버리지 않고 따져 봐요.","물음에서 시작할 뿐이에요.","어디가 왜 이상한지 찾아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#1','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C3',2,'mc','auto','「글은 무엇을 말하는가와 어떻게 말하는가로 이루어져 있다」에서 「무엇을 말하는가」를 재는 갈래는 어느 것인가요?',ARRAY['K6-1-u6-X03','K6-1-u6-X23','K6-1-u6-X08']::text[],false,'{"seq":1,"concept":"K6-1-u6-C3","difficulty":2,"kind":"mc","stem":"「글은 무엇을 말하는가와 어떻게 말하는가로 이루어져 있다」에서 「무엇을 말하는가」를 재는 갈래는 어느 것인가요?","options":[{"t":"내용의 타당성","correct":true},{"t":"표현의 적절성","mis":"K6-1-u6-X03"},{"t":"글자의 크기","mis":"K6-1-u6-X23"},{"t":"글의 길이","mis":"K6-1-u6-X08"}],"explanation":["어떻게 말하는가를 재는 갈래예요.","크기와는 관계없어요.","내용이 이치에 맞는지 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#2','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C5',2,'error','auto','급식실 글을 읽은 사람들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X06']::text[],false,'{"seq":2,"concept":"K6-1-u6-C5","difficulty":2,"kind":"error","stem":"급식실 글을 읽은 사람들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"다른 친구 — 「이상한 줄이 하나 있으니 이 글은 다 엉터리야.」","correct":true,"mis_target":"K6-1-u6-X05"},{"t":"하영 — 「다치는 이야기는 받아들이고, 키 이야기만 까닭을 대어 짚자.」","mis":"K6-1-u6-X05"},{"t":"우재 — 「이상한 곳은 왜 이상한지 말해 볼게.」","mis":"K6-1-u6-X06"}],"explanation":["하영이는 받아들일 것을 골랐어요.","우재는 까닭을 대려 해요.","한 줄 때문에 맞는 곳까지 버리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#3','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C4',3,'mc','auto','물건을 알리는 광고를 읽을 때 먼저 살필 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X04']::text[],false,'{"seq":3,"concept":"K6-1-u6-C4","difficulty":3,"kind":"mc","stem":"물건을 알리는 광고를 읽을 때 먼저 살필 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건의 특징을 제대로 나타냈는지","correct":true},{"t":"그 주장이 나에게 도움이 되는지만","mis":"K6-1-u6-X04"},{"t":"등장인물의 마음이 어떠한지","mis":"K6-1-u6-X04"},{"t":"광고를 몇 번 보았는지","mis":"K6-1-u6-X04"}],"explanation":["그건 주장하는 글에서 먼저 봐요.","이야기를 읽을 때 살필 거예요.","알리려는 물건의 특징을 제대로 말했는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#4','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C1',3,'mc','auto','우재가 「읽고 나서 고개가 갸웃해졌어」라고 한 말에서 보이는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X01','K6-1-u6-X21','K6-1-u6-X05']::text[],false,'{"seq":4,"concept":"K6-1-u6-C1","difficulty":3,"kind":"mc","stem":"우재가 「읽고 나서 고개가 갸웃해졌어」라고 한 말에서 보이는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 그대로 믿지 않고 이상한 곳을 찾아보려는 태도","correct":true},{"t":"붙어 있는 글은 다 믿는 태도","mis":"K6-1-u6-X01"},{"t":"이상하면 읽기를 그만두는 태도","mis":"K6-1-u6-X21"},{"t":"글쓴이를 탓하려는 태도","mis":"K6-1-u6-X05"}],"explanation":["그대로 믿지 않았어요.","그만두지 않고 따져 봐요.","탓하려는 게 아니에요."],"asset":{"type":"speech","turns":[{"who":"우재","text":"급식실 앞 게시판에 새 글이 붙었어. 걸어 다니자는 내용이야."},{"who":"하영","text":"맞는 말이네. 국을 들고 부딪히면 크게 다칠 수 있으니까."},{"who":"우재","text":"그런데 가운데에 이상한 줄이 하나 있어. 읽고 나서 고개가 갸웃해졌어."},{"who":"하영","text":"어디 보자. 붙어 있다고 다 맞는 말은 아니니까 우리가 따져 보자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#5','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C6',3,'ox','auto','「이 문장은 이상해」라고만 말해도 판단을 다 한 거예요.',ARRAY['K6-1-u6-X06']::text[],false,'{"seq":5,"concept":"K6-1-u6-C6","difficulty":3,"kind":"ox","stem":"「이 문장은 이상해」라고만 말해도 판단을 다 한 거예요.","answer":"X","reason_options":[{"t":"왜 그렇게 판단했는지 까닭을 대야 다른 사람이 따져 볼 수 있기 때문에","correct":true},{"t":"이상하다고 느낀 것이 판단의 전부이기 때문에","mis":"K6-1-u6-X06"}],"mis":"K6-1-u6-X06","explanation":["느낌만으로는 부족해요.","까닭이 함께 가요.","까닭이 있어야 판단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#6','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C3',3,'mc','auto','판단하며 읽기의 두 갈래를 모두 쓴 판단은 어느 것인가요?',ARRAY['K6-1-u6-X46','K6-1-u6-X23','K6-1-u6-X08']::text[],false,'{"seq":6,"concept":"K6-1-u6-C3","difficulty":3,"kind":"mc","stem":"판단하며 읽기의 두 갈래를 모두 쓴 판단은 어느 것인가요?","options":[{"t":"「키 이야기는 주장과 이어지지 않고, 〈크게 다칠 수 있다〉는 부풀리지 않은 알맞은 말이다.」","correct":true},{"t":"「키 이야기는 주장과 이어지지 않는다.」로 끝낸다","mis":"K6-1-u6-X46"},{"t":"「글씨가 반듯해서 좋은 글이다.」","mis":"K6-1-u6-X23"},{"t":"「글이 짧아서 타당하다.」","mis":"K6-1-u6-X08"}],"explanation":["내용 한 갈래만 보았어요.","글씨는 갈래가 아니에요.","내용과 표현을 함께 살폈어요 — 키 문장은 「뛰다가 넘어지면 다칠 수 있다」로 바로잡아요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#7','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C5',3,'mc','auto','비판적으로 읽는 목적으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X01']::text[],false,'{"seq":7,"concept":"K6-1-u6-C5","difficulty":3,"kind":"mc","stem":"비판적으로 읽는 목적으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"글에서 나에게 필요한 정보를 골라내는 것","correct":true},{"t":"글을 깎아내리는 것","mis":"K6-1-u6-X05"},{"t":"글쓴이와 다투어 이기는 것","mis":"K6-1-u6-X05"},{"t":"적힌 것을 그대로 외우는 것","mis":"K6-1-u6-X01"}],"explanation":["깎아내리려는 게 아니에요.","다툼이 목적이 아니에요.","쓸 것을 골라내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#8','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C2',4,'mc','auto','급식실 글의 둘째 이유를 읽고 세울 물음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X02','K6-1-u6-X05','K6-1-u6-X01']::text[],false,'{"seq":8,"concept":"K6-1-u6-C2","difficulty":4,"kind":"mc","stem":"급식실 글의 둘째 이유를 읽고 세울 물음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「뛰는 일과 키가 자라는 일이 정말 관계가 있을까?」","correct":true},{"t":"「잘 모르겠지만 그냥 넘어가자.」","mis":"K6-1-u6-X02"},{"t":"「다른 문장에서도 틀린 곳을 더 찾아보자.」","mis":"K6-1-u6-X05"},{"t":"「게시판에 붙었으니 맞겠지.」","mis":"K6-1-u6-X01"}],"explanation":["넘기지 말고 멈춰요.","트집 잡기가 아니에요.","이상한 곳을 물음으로 바꿨어요 — 둘은 관계가 없어요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#9','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C5',4,'essay','teacher','급식실 글을 읽고 「틀린 곳이 있으니 이 글은 아무것도 믿을 수 없어.」라고 말하는 친구에게, 받아들일 곳과 짚을 곳을 나누어 까닭과 함께 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C5","difficulty":4,"kind":"essay","stem":"급식실 글을 읽고 「틀린 곳이 있으니 이 글은 아무것도 믿을 수 없어.」라고 말하는 친구에게, 받아들일 곳과 짚을 곳을 나누어 까닭과 함께 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 이 글에서 「뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있다」와 「식판을 쳐서 음식을 쏟게 할 수 있다」는 실제로 일어나는 일이라 받아들여도 좋아. 짚을 곳은 「뛰어다니면 키가 자라지 않는다」 하나야. 뛰는 일과 키가 자라는 일은 관계가 없으니까. 틀린 곳 하나 때문에 걸어 다니자는 주장까지 버리지 말고, 그 문장만 「뛰다가 넘어지면 다칠 수 있다」로 바로잡으면 돼.","scoring_points":["받아들일 곳을 까닭과 함께 썼는가","짚을 곳을 까닭과 함께 썼는가","글 전체를 버리지 않는다는 뜻을 담았는가"]},"explanation":["맞는 곳을 먼저 찾아요.","걸린 곳은 까닭을 대요.","흠 잡기가 아님을 말해요."],"asset":{"type":"passage","lines":["점심시간에 급식실에서 뛰는 친구들이 있습니다. 급식실에서는 걸어 다녔으면 좋겠습니다.","첫째, 뜨거운 국을 든 사람과 부딪히면 크게 다칠 수 있습니다.","둘째, 뛰어다니면 키가 자라지 않습니다.","셋째, 지나가는 사람의 식판을 쳐서 음식을 쏟게 할 수 있습니다.","급식실은 여러 사람이 함께 쓰는 곳입니다. 조금만 천천히 걸읍시다."],"title":"「급식실에서는 걸어 다닙시다」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L01_challenge#10','kor',6,1,'u6','L01','g6_1_kor_u6_L01_challenge','lesson_challenge','K6-1-u6-C3',4,'essay','teacher','판단하며 읽기의 두 갈래를 쓰고, 급식실 글에 대어 볼 물음을 갈래마다 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C3","difficulty":4,"kind":"essay","stem":"판단하며 읽기의 두 갈래를 쓰고, 급식실 글에 대어 볼 물음을 갈래마다 하나씩 쓰세요.","answer_guide":{"answer":"예: 두 갈래는 내용의 타당성과 표현의 적절성이다. 내용의 타당성으로는 「이유가 걸어 다니자는 주장과 이어지는가?」를 물을 수 있다. 표현의 적절성으로는 「부풀리거나 사실이 아닌 말로 나타내지 않았는가?」를 물을 수 있다. 무엇을 말하는가와 어떻게 말하는가를 함께 보아야 비판적으로 읽은 것이다.","scoring_points":["두 갈래의 이름을 썼는가","갈래마다 알맞은 물음을 썼는가","두 갈래를 함께 살핀다는 뜻을 썼는가"]},"explanation":["무엇과 어떻게를 떠올려요.","갈래마다 물음을 만들어요.","함께 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#1','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C8',1,'mc','auto','「타당성」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X23']::text[],false,'{"seq":1,"concept":"K6-1-u6-C8","difficulty":1,"kind":"mc","stem":"「타당성」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"이치에 맞는 옳은 성질","correct":true},{"t":"글이 길고 자세한 성질","mis":"K6-1-u6-X08"},{"t":"어려운 낱말이 많은 성질","mis":"K6-1-u6-X08"},{"t":"글씨가 바르고 고른 성질","mis":"K6-1-u6-X23"}],"explanation":["길이와는 관계없어요.","어려운 낱말 수가 아니에요.","이치에 맞게 옳은지를 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#2','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C7',1,'match','auto','주장하는 글의 부분과 그 부분이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C7","difficulty":1,"kind":"match","stem":"주장하는 글의 부분과 그 부분이 하는 일을 알맞게 이으세요.","pairs":[{"l":"서론","r":"읽는 사람의 관심을 끌고 글의 방향을 알림"},{"l":"본론","r":"주장을 뒷받침하는 이유와 근거를 제시함"},{"l":"결론","r":"글을 마무리하고 주장을 다시 정리함"}],"mis":"K6-1-u6-X07","explanation":["서론은 방향을 알려요.","본론은 이유와 근거예요.","결론은 주장을 다시 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#3','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C7',1,'mc','auto','「급식을 남기지 맙시다」의 주장은 무엇인가요?',ARRAY['K6-1-u6-X07','K6-1-u6-X11']::text[],false,'{"seq":3,"concept":"K6-1-u6-C7","difficulty":1,"kind":"mc","stem":"「급식을 남기지 맙시다」의 주장은 무엇인가요?","options":[{"t":"급식을 남기지 말자","correct":true},{"t":"식단표를 매일 확인하자","mis":"K6-1-u6-X07"},{"t":"급식을 더 많이 받자","mis":"K6-1-u6-X07"},{"t":"반찬을 골라 먹자","mis":"K6-1-u6-X11"}],"explanation":["근거에 나온 말이에요.","주장과 반대예요.","서론과 결론이 함께 가리켜요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#4','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C8',1,'mc','auto','내용의 타당성을 재는 세 물음에 들지 않는 것은 어느 것인가요?',ARRAY['K6-1-u6-X08']::text[],false,'{"seq":4,"concept":"K6-1-u6-C8","difficulty":1,"kind":"mc","stem":"내용의 타당성을 재는 세 물음에 들지 않는 것은 어느 것인가요?","options":[{"t":"글씨가 반듯하고 고른가?","correct":true},{"t":"주장은 가치 있고 중요한가?","mis":"K6-1-u6-X08"},{"t":"이유는 주장을 적절하게 뒷받침하는가?","mis":"K6-1-u6-X08"},{"t":"근거는 이유를 적절하게 뒷받침하는가?","mis":"K6-1-u6-X08"}],"explanation":["첫째 물음이에요.","둘째 물음이에요.","세 물음은 주장 · 이유 · 근거를 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#5','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C9',2,'mc','auto','가치 있고 중요한 주장은 어느 것인가요?',ARRAY['K6-1-u6-X09']::text[],false,'{"seq":5,"concept":"K6-1-u6-C9","difficulty":2,"kind":"mc","stem":"가치 있고 중요한 주장은 어느 것인가요?","options":[{"t":"복도 정수기 앞에서는 차례를 지킵시다","correct":true},{"t":"줄 서기 싫으면 물을 마시지 맙시다","mis":"K6-1-u6-X09"},{"t":"물을 아끼려면 세수를 하지 맙시다","mis":"K6-1-u6-X09"},{"t":"목이 마르면 앞사람을 밀고 먼저 마십시다","mis":"K6-1-u6-X09"}],"explanation":["다른 문제를 만들어요.","많은 사람이 받아들이기 어려워요.","여럿에게 도움이 되는 주장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#6','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C10',2,'mc','auto','「도서관 책을 접지 맙시다」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X10']::text[],false,'{"seq":6,"concept":"K6-1-u6-C10","difficulty":2,"kind":"mc","stem":"「도서관 책을 접지 맙시다」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"접힌 자국은 펴지지 않기 때문입니다","correct":true},{"t":"도서관은 조용한 곳이기 때문입니다","mis":"K6-1-u6-X10"},{"t":"책에는 여러 가지 이야기가 담겨 있기 때문입니다","mis":"K6-1-u6-X10"},{"t":"도서관 책은 무겁기 때문입니다","mis":"K6-1-u6-X10"}],"explanation":["맞는 말이지만 접는 일과 관계없어요.","책을 접는 일과 이어지지 않아요.","접는 일과 바로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#7','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C11',2,'mc','auto','문단 ④가 주장을 뒷받침하지 못하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X18']::text[],false,'{"seq":7,"concept":"K6-1-u6-C11","difficulty":2,"kind":"mc","stem":"문단 ④가 주장을 뒷받침하지 못하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"골라 먹는 일을 좋게 말해 남기지 말자는 주장과 어긋나기 때문이다","correct":true},{"t":"문단이 너무 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"반찬 이야기는 모두 거짓이기 때문이다","mis":"K6-1-u6-X18"},{"t":"근거가 너무 많기 때문이다","mis":"K6-1-u6-X08"}],"explanation":["길이 문제가 아니에요.","반찬이 여러 가지인 건 사실이에요.","주장과 반대 방향이에요 — 바르게는 「여러 반찬이 나오니 조금씩 담아 골고루 먹을 수 있습니다」예요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#8','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C12',2,'mc','auto','「급식을 남기지 맙시다」에서 근거로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":8,"concept":"K6-1-u6-C12","difficulty":2,"kind":"mc","stem":"「급식을 남기지 맙시다」에서 근거로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했다","correct":true},{"t":"영양 선생님께서 잔반통을 하루에 두 번씩 비운다고 하셨다","mis":"K6-1-u6-X05"},{"t":"식단표에 영양소를 나누어 담도록 짜여 있다고 안내되어 있다","mis":"K6-1-u6-X05"},{"t":"남긴 음식은 그대로 버려진다","mis":"K6-1-u6-X05"}],"explanation":["여쭈어 확인한 사실이에요.","누구나 볼 수 있는 안내예요.","한 사람의 짐작이에요 — 직접 세거나 여쭈어 확인한 사실로 바꿔야 해요."],"asset":{"type":"passage","lines":["① 점심시간이 끝난 급식실 잔반통에는 먹지 않은 밥과 반찬이 수북이 쌓여 있습니다.","급식을 남기지 않았으면 좋겠습니다.","② 첫째, 남긴 음식은 그대로 버려져 아깝게 사라집니다. 우리 학교 영양 선생님께","여쭈어보았더니, 잔반통이 매일 가득 차서 하루에 두 번씩 비운다고 하셨습니다.","③ 둘째, 골고루 먹어야 몸에 필요한 영양소를 얻을 수 있습니다. 급식실 앞 식단표에","밥과 국, 반찬이 영양소를 나누어 담도록 짜여 있다고 안내되어 있습니다."],"title":"「급식을 남기지 맙시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#9','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C13',2,'ox','auto','타당성은 주장하는 글에서만 따져요.',ARRAY['K6-1-u6-X13']::text[],false,'{"seq":9,"concept":"K6-1-u6-C13","difficulty":2,"kind":"ox","stem":"타당성은 주장하는 글에서만 따져요.","answer":"X","reason_options":[{"t":"알림글 · 소식 · 설명하는 글처럼 내용을 담은 글이면 같은 물음을 할 수 있기 때문에","correct":true},{"t":"다른 글에는 주장이 없어 따질 것이 없기 때문에","mis":"K6-1-u6-X13"}],"mis":"K6-1-u6-X13","explanation":["주장하는 글만이 아니에요.","알림글도 따져 볼 수 있어요.","내용을 담은 글이면 어디든요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_basic#10','kor',6,1,'u6','L02','g6_1_kor_u6_L02_basic','lesson_basic','K6-1-u6-C14',3,'mc','auto','스스로 세운 판단 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X14','K6-1-u6-X23']::text[],false,'{"seq":10,"concept":"K6-1-u6-C14","difficulty":3,"kind":"mc","stem":"스스로 세운 판단 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"「한쪽 이야기만 담지는 않았는가?」","correct":true},{"t":"「글이 몇 줄인가?」","mis":"K6-1-u6-X08"},{"t":"「기준은 세 가지뿐이니 더 세우지 않는다.」","mis":"K6-1-u6-X14"},{"t":"「제목 글씨가 예쁜가?」","mis":"K6-1-u6-X23"}],"explanation":["줄 수는 타당성과 관계없어요.","기준은 더 세워도 좋아요.","물음의 꼴로 세운 알맞은 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#1','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C10',2,'mc','auto','「참인 문장이라고 해서 다 이유가 되는 것은 아니다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X18','K6-1-u6-X10','K6-1-u6-X12']::text[],false,'{"seq":1,"concept":"K6-1-u6-C10","difficulty":2,"kind":"mc","stem":"「참인 문장이라고 해서 다 이유가 되는 것은 아니다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"맞는 말이라도 주장과 관련이 없으면 이유가 되지 못한다","correct":true},{"t":"이유는 거짓이어도 된다","mis":"K6-1-u6-X18"},{"t":"맞는 말은 모두 이유로 써야 한다","mis":"K6-1-u6-X10"},{"t":"이유에는 짐작만 쓴다","mis":"K6-1-u6-X12"}],"explanation":["거짓이면 더 안 돼요.","관련이 있어야 해요.","주장과 이어져야 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#2','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C8',2,'sa','auto','「이치에 맞는 옳은 성질」을 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C8","difficulty":2,"kind":"sa","stem":"「이치에 맞는 옳은 성질」을 뜻하는 낱말을 쓰세요.","answer":["타당성"],"explanation":["이치에 맞는가를 떠올려요.","내용을 재는 말이에요.","타당성이에요."],"mis":"K6-1-u6-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#3','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C11',3,'mc','auto','문단 ④를 주장 편으로 알맞게 고쳐 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X11','K6-1-u6-X10']::text[],false,'{"seq":3,"concept":"K6-1-u6-C11","difficulty":3,"kind":"mc","stem":"문단 ④를 주장 편으로 알맞게 고쳐 쓴 것은 어느 것인가요?","options":[{"t":"여러 반찬이 나오니 조금씩 담아 골고루 먹을 수 있습니다","correct":true},{"t":"좋아하는 반찬만 골라 먹으면 즐겁습니다","mis":"K6-1-u6-X11"},{"t":"급식에는 반찬이 여러 가지 나옵니다","mis":"K6-1-u6-X10"},{"t":"반찬이 많은 날에는 남겨도 됩니다","mis":"K6-1-u6-X11"}],"explanation":["여전히 반대 방향이에요.","사실이지만 주장과 이어지지 않아요.","같은 사실을 주장 쪽으로 이었어요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#4','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C12',3,'mc','auto','「급식을 남기지 맙시다」 문단 ⑤의 근거를 알맞게 고쳐 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X12','K6-1-u6-X26']::text[],false,'{"seq":4,"concept":"K6-1-u6-C12","difficulty":3,"kind":"mc","stem":"「급식을 남기지 맙시다」 문단 ⑤의 근거를 알맞게 고쳐 쓴 것은 어느 것인가요?","options":[{"t":"영양 선생님께 여쭈어보니 남은 음식을 치우는 데 날마다 손이 많이 든다고 하셨습니다","correct":true},{"t":"다른 친구도 그런 것 같다고 했습니다","mis":"K6-1-u6-X12"},{"t":"아마 다들 힘들 것입니다","mis":"K6-1-u6-X12"},{"t":"잔반은 정말 정말 많습니다","mis":"K6-1-u6-X26"}],"explanation":["짐작이 하나 더 붙었을 뿐이에요.","짐작이에요.","여쭈어 확인한 사실이에요 — 「늘어난 것 같다」는 짐작은 근거가 못 돼요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#5','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C9',3,'ox','auto','「물을 아끼려면 세수를 하지 맙시다」는 물을 아끼자는 뜻이니 가치 있는 주장이에요.',ARRAY['K6-1-u6-X09']::text[],false,'{"seq":5,"concept":"K6-1-u6-C9","difficulty":3,"kind":"ox","stem":"「물을 아끼려면 세수를 하지 맙시다」는 물을 아끼자는 뜻이니 가치 있는 주장이에요.","answer":"X","reason_options":[{"t":"하자는 대로 하면 몸을 깨끗이 하지 못하는 다른 문제가 생기고 많은 사람이 받아들이기 어렵기 때문에","correct":true},{"t":"물을 아끼는 일은 어떤 방법이든 늘 좋은 일이기 때문에","mis":"K6-1-u6-X09"}],"mis":"K6-1-u6-X09","explanation":["뜻이 좋아도 방법을 봐요.","다른 문제를 만들어요.","여럿에게 도움이 되어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#6','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C8',3,'match','auto','판단 물음과 그 물음이 재는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u6-C8","difficulty":3,"kind":"match","stem":"판단 물음과 그 물음이 재는 것을 알맞게 이으세요.","pairs":[{"l":"가치 있고 중요한가?","r":"주장"},{"l":"주장을 적절하게 뒷받침하는가?","r":"이유"},{"l":"이유를 적절하게 뒷받침하는가?","r":"근거"}],"mis":"K6-1-u6-X08","explanation":["가치는 주장을 재요.","이유가 주장을 받쳐요.","근거가 이유를 받쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#7','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C13',3,'mc','auto','급식실 앞에 「이번 주부터 급식실 문을 조금 일찍 엽니다. 줄이 길어 기다리는 시간이 많기 때문입니다.」라는 알림글이 붙었어요. 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u6-X13','K6-1-u6-X05','K6-1-u6-X15']::text[],false,'{"seq":7,"concept":"K6-1-u6-C13","difficulty":3,"kind":"mc","stem":"급식실 앞에 「이번 주부터 급식실 문을 조금 일찍 엽니다. 줄이 길어 기다리는 시간이 많기 때문입니다.」라는 알림글이 붙었어요. 알맞은 태도는 어느 것인가요?","options":[{"t":"알림글에도 「까닭이 알림 내용과 이어지는가」를 물어볼 수 있다","correct":true},{"t":"알림글은 주장하는 글이 아니니 따질 것이 없다","mis":"K6-1-u6-X13"},{"t":"알림글은 틀린 곳을 많이 찾아야 한다","mis":"K6-1-u6-X05"},{"t":"알림글은 큰 글씨만 읽으면 된다","mis":"K6-1-u6-X15"}],"explanation":["알림글도 내용을 담았어요.","트집이 목적이 아니에요.","같은 물음을 댈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#8','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C14',4,'mc','auto','「쓸데없는 정보가 들어 있지 않은가?」라는 기준을 이 글에 대었을 때 걸리는 곳은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X07']::text[],false,'{"seq":8,"concept":"K6-1-u6-C14","difficulty":4,"kind":"mc","stem":"「쓸데없는 정보가 들어 있지 않은가?」라는 기준을 이 글에 대었을 때 걸리는 곳은 어느 것인가요?","options":[{"t":"문단 ④ — 골라 먹는 재미 이야기는 남기지 말자는 주장에 쓸모가 없고 오히려 어긋난다","correct":true},{"t":"문단 ⑤의 「남긴 음식을 치우는 데에도 힘이 듭니다」","mis":"K6-1-u6-X05"},{"t":"문단 ⑥의 「급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다」","mis":"K6-1-u6-X07"},{"t":"문단 ⑥의 「먹을 만큼만 받고, 받은 만큼은 먹읍시다」","mis":"K6-1-u6-X07"}],"explanation":["주장과 이어진 이유예요.","결론의 마무리예요.","내가 세운 기준으로도 문단 ④가 걸려요 — 바르게는 「조금씩 담아 골고루 먹을 수 있다」예요."],"asset":{"type":"passage","lines":["④ 셋째, 급식에는 여러 가지 반찬이 나와서 골라 먹는 재미가 있습니다.","⑤ 넷째, 남긴 음식을 치우는 데에도 힘이 듭니다.","우리 반 친구가 잔반이 예전보다 늘어난 것 같다고 말했습니다.","⑥ 급식은 여러 사람의 손을 거쳐 우리 앞에 옵니다.","먹을 만큼만 받고, 받은 만큼은 먹읍시다."],"title":"「급식을 남기지 맙시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#9','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C9',4,'essay','teacher','「급식을 남기지 맙시다」를 세 기준(주장 · 이유 · 근거)으로 판단하고, 기준마다 판단의 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C9","difficulty":4,"kind":"essay","stem":"「급식을 남기지 맙시다」를 세 기준(주장 · 이유 · 근거)으로 판단하고, 기준마다 판단의 까닭을 쓰세요.","answer_guide":{"answer":"예: 주장 — 급식을 남기지 말자는 주장은 여러 사람에게 도움이 되고 누구나 받아들일 만해 가치 있다. 이유 — 문단 ②·③·⑤는 주장과 이어지지만 문단 ④는 골라 먹는 재미를 좋게 말해 주장과 어긋난다. 근거 — 영양 선생님께 여쭈어 확인한 사실은 알맞지만 「잔반이 늘어난 것 같다」는 친구의 말은 한 사람의 짐작이라 근거가 되지 못한다.","scoring_points":["주장의 가치를 까닭과 함께 판단했는가","어긋난 이유를 찾고 까닭을 썼는가","짐작 근거를 찾고 까닭을 썼는가"]},"explanation":["세 물음을 차례로 대요.","걸린 곳은 까닭을 대요.","받아들일 곳도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L02_challenge#10','kor',6,1,'u6','L02','g6_1_kor_u6_L02_challenge','lesson_challenge','K6-1-u6-C14',4,'essay','teacher','오늘 배운 세 기준 말고 내가 쓸 판단 기준 하나를 물음의 꼴로 세우고, 그 기준을 「급식을 남기지 맙시다」에 대어 본 결과를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C14","difficulty":4,"kind":"essay","stem":"오늘 배운 세 기준 말고 내가 쓸 판단 기준 하나를 물음의 꼴로 세우고, 그 기준을 「급식을 남기지 맙시다」에 대어 본 결과를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 내 기준 — 「문제가 아닌 일을 문제라고 하지는 않는가?」 이 기준을 대어 보니 이 글은 잔반통에 남은 음식이 쌓이는 일을 문제로 삼았는데, 영양 선생님 말씀처럼 실제로 잔반통을 하루에 두 번씩 비우므로 문제가 맞다. 그래서 이 기준에는 걸리지 않는다.","scoring_points":["물음의 꼴로 기준을 세웠는가","그 기준을 글에 대어 보았는가","판단의 까닭을 썼는가"]},"explanation":["물음의 꼴로 적어요.","글에 직접 대어 봐요.","결과에 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#1','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C15',1,'mc','auto','채린이가 겪은 일에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X01']::text[],false,'{"seq":1,"concept":"K6-1-u6-C15","difficulty":1,"kind":"mc","stem":"채린이가 겪은 일에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"글에 적혀 있다고 모두 그대로 일어나지는 않는다","correct":true},{"t":"큰 글씨만 읽으면 충분하다","mis":"K6-1-u6-X15"},{"t":"포장에 적힌 말은 다 맞다","mis":"K6-1-u6-X01"},{"t":"작은 글씨는 읽지 않아도 된다","mis":"K6-1-u6-X15"}],"explanation":["작은 글씨에 조건이 있었어요.","포장 글도 따져 봐요.","한 번 더 확인해요."],"asset":{"type":"speech","turns":[{"who":"채린","text":"지난주에 「이 지우개는 자국이 하나도 남지 않는다」는 말을 보고 샀거든."},{"who":"소담","text":"써 보니까 어땠는데?"},{"who":"채린","text":"자국은 남더라. 포장을 다시 읽어 봤더니 작은 글씨로 종이에 따라 다르다고 적혀 있었어."},{"who":"소담","text":"앞의 큰 글씨만 읽었으니 그런 거네. 다음부터는 뒤까지 읽어 봐야겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#2','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C16',1,'match','auto','안전모 글의 이유와 그 이유를 받치는 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C16","difficulty":1,"kind":"match","stem":"안전모 글의 이유와 그 이유를 받치는 근거를 알맞게 이으세요.","pairs":[{"l":"넘어질 때 머리를 지켜 준다","r":"안쪽 스티로폼 층이 부딪히는 힘을 나누어 받는다"},{"l":"나를 지키는 습관을 일찍 들일 수 있다","r":"사흘 동안 세어 보니 열 대 가운데 두 대뿐이었다"},{"l":"머리에 잘 맞게 써야 제 몫을 한다","r":"옆집 형이 헐렁한 것은 소용없다고 말해 주었다"}],"mis":"K6-1-u6-X16","explanation":["머리를 지키는 까닭이에요.","습관을 보여 주는 기록이에요.","같은 문단 안에서 짝을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#3','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C20',1,'mc','auto','한 편의 글을 세 기준으로 재는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X20']::text[],false,'{"seq":3,"concept":"K6-1-u6-C20","difficulty":1,"kind":"mc","stem":"한 편의 글을 세 기준으로 재는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주장 → 이유 → 근거","correct":true},{"t":"근거 → 주장 → 이유","mis":"K6-1-u6-X20"},{"t":"이유 → 근거 → 주장","mis":"K6-1-u6-X20"},{"t":"아무 차례로나 한꺼번에","mis":"K6-1-u6-X20"}],"explanation":["근거부터 재면 짝을 놓쳐요.","주장부터 봐요.","주장, 이유, 근거 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#4','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C21',1,'ox','auto','걸린 곳이 두 군데 있으면 그 글 전체를 버려야 해요.',ARRAY['K6-1-u6-X21']::text[],false,'{"seq":4,"concept":"K6-1-u6-C21","difficulty":1,"kind":"ox","stem":"걸린 곳이 두 군데 있으면 그 글 전체를 버려야 해요.","answer":"X","reason_options":[{"t":"걸린 곳만 까닭을 대어 짚고 타당한 부분은 받아들이면 되기 때문에","correct":true},{"t":"틀린 곳이 있는 글은 하나도 믿을 수 없기 때문에","mis":"K6-1-u6-X21"}],"mis":"K6-1-u6-X21","explanation":["쓸 수 있는 정보까지 버리게 돼요.","고르게 부족한 글은 드물어요.","받아들일 것을 골라내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#5','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C17',2,'mc','auto','「이 글의 주장은 가치 있고 중요한가요?」에 가장 좋은 답은 어느 것인가요?',ARRAY['K6-1-u6-X17','K6-1-u6-X09','K6-1-u6-X06']::text[],false,'{"seq":5,"concept":"K6-1-u6-C17","difficulty":2,"kind":"mc","stem":"「이 글의 주장은 가치 있고 중요한가요?」에 가장 좋은 답은 어느 것인가요?","options":[{"t":"가치 있다 — 다치는 일을 줄여 주고 누구나 받아들일 만하다","correct":true},{"t":"가치 있다 — 글에 그렇게 적혀 있기 때문이다","mis":"K6-1-u6-X17"},{"t":"가치 없다 — 안전모를 쓰면 번거롭기 때문이다","mis":"K6-1-u6-X09"},{"t":"가치 있다","mis":"K6-1-u6-X06"}],"explanation":["적혀 있다는 건 까닭이 아니에요.","번거로움보다 다치지 않는 게 커요.","판단과 까닭이 한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#6','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C18',2,'mc','auto','주장을 뒷받침하지 못하는 이유는 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":6,"concept":"K6-1-u6-C18","difficulty":2,"kind":"mc","stem":"주장을 뒷받침하지 못하는 이유는 어느 것인가요?","options":[{"t":"안전모를 쓰면 자전거가 더 빨리 달린다","correct":true},{"t":"넘어질 때 머리를 지켜 준다","mis":"K6-1-u6-X05"},{"t":"나를 지키는 습관을 일찍 들일 수 있다","mis":"K6-1-u6-X05"},{"t":"머리에 잘 맞게 써야 제 몫을 한다","mis":"K6-1-u6-X05"}],"explanation":["주장과 이어지는 이유예요.","이것도 주장과 이어져요.","사실도 아니고 주장과도 어긋나요 — 바르게는 「구멍이 뚫려 있어 오래 써도 답답하지 않습니다」예요."],"asset":{"type":"passage","lines":["① 자전거를 타는 사람이 늘어난 만큼 넘어지는 일도 늘었습니다.","자전거를 탈 때에는 안전모를 썼으면 좋겠습니다.","② 첫째, 넘어질 때 머리를 지켜 줍니다. 안전모 안쪽에 든 두꺼운 스티로폼 층이","부딪히는 힘을 나누어 받습니다.","③ 둘째, 안전모를 쓰면 자전거가 더 빨리 달립니다.","안전모에는 구멍이 여러 개 뚫려 있어 바람이 지나갑니다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#7','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C19',2,'mc','auto','근거로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":7,"concept":"K6-1-u6-C19","difficulty":2,"kind":"mc","stem":"근거로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었다","correct":true},{"t":"보관대를 사흘 동안 세어 보니 열 대 가운데 두 대뿐이었다","mis":"K6-1-u6-X05"},{"t":"안쪽 스티로폼 층이 부딪히는 힘을 나누어 받는다","mis":"K6-1-u6-X05"},{"t":"안전모 상자에 끈을 턱 아래에서 조이라고 적혀 있다","mis":"K6-1-u6-X05"}],"explanation":["직접 센 기록이에요.","누구나 확인할 수 있는 사실이에요.","전해 들은 말이라 다시 확인할 수 없어요 — 상자에 적힌 안내처럼 확인할 수 있는 것으로 바꿔요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#8','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C19',2,'mc','auto','좋은 근거들의 공통점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X12','K6-1-u6-X08']::text[],false,'{"seq":8,"concept":"K6-1-u6-C19","difficulty":2,"kind":"mc","stem":"좋은 근거들의 공통점으로 알맞은 것은 어느 것인가요?","options":[{"t":"다른 사람도 같은 길로 다시 가 확인할 수 있다","correct":true},{"t":"아는 사람이 말해 주었다","mis":"K6-1-u6-X19"},{"t":"글쓴이가 강하게 믿는다","mis":"K6-1-u6-X12"},{"t":"문장이 길고 자세하다","mis":"K6-1-u6-X08"}],"explanation":["전해 들은 말은 확인하기 어려워요.","믿음은 근거가 아니에요.","되짚어 확인할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#9','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C22',2,'mc','auto','둘레의 글을 판단하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X22','K6-1-u6-X05','K6-1-u6-X01']::text[],false,'{"seq":9,"concept":"K6-1-u6-C22","difficulty":2,"kind":"mc","stem":"둘레의 글을 판단하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"게시판 글의 주장 · 이유 · 근거를 옮겨 적고 세 기준으로 재어, 걸리는 곳은 까닭과 고칠 방법을 적는다","correct":true},{"t":"배운 기준은 공부 시간의 글에만 쓴다","mis":"K6-1-u6-X22"},{"t":"걸리는 곳의 개수만 센다","mis":"K6-1-u6-X05"},{"t":"포장에 적힌 글은 그대로 믿는다","mis":"K6-1-u6-X01"}],"explanation":["둘레의 글에도 대어 봐요.","개수가 아니라 까닭이에요.","포장 글도 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_basic#10','kor',6,1,'u6','L04','g6_1_kor_u6_L04_basic','lesson_basic','K6-1-u6-C21',3,'mc','auto','안전모 글에서 받아들여도 좋은 부분만 모은 것은 어느 것인가요?',ARRAY['K6-1-u6-X18','K6-1-u6-X21','K6-1-u6-X01']::text[],false,'{"seq":10,"concept":"K6-1-u6-C21","difficulty":3,"kind":"mc","stem":"안전모 글에서 받아들여도 좋은 부분만 모은 것은 어느 것인가요?","options":[{"t":"안전모를 쓰자는 주장 · 머리를 지켜 준다는 이유 · 사흘 동안 센 기록","correct":true},{"t":"더 빨리 달린다는 이유 · 옆집 형에게서 전해 들은 말","mis":"K6-1-u6-X18"},{"t":"받아들일 것이 하나도 없다","mis":"K6-1-u6-X21"},{"t":"글에 있는 모든 문장","mis":"K6-1-u6-X01"}],"explanation":["두 곳은 걸린 곳이에요 — 안전모는 빠르기와 관계없어요.","걸린 곳은 두 군데뿐이에요.","걸린 곳을 빼고 골라냈어요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#1','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C15',2,'mc','auto','소담이가 「다음부터는 뒤까지 읽어 봐야겠다」고 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X01','K6-1-u6-X21']::text[],false,'{"seq":1,"concept":"K6-1-u6-C15","difficulty":2,"kind":"mc","stem":"소담이가 「다음부터는 뒤까지 읽어 봐야겠다」고 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 글씨만 읽어서 작은 글씨에 적힌 조건을 놓쳤기 때문이다","correct":true},{"t":"큰 글씨가 틀렸으니 작은 글씨는 볼 필요가 없기 때문이다","mis":"K6-1-u6-X15"},{"t":"포장에 적힌 말은 늘 맞기 때문이다","mis":"K6-1-u6-X01"},{"t":"지우개를 버리려고 하기 때문이다","mis":"K6-1-u6-X21"}],"explanation":["작은 글씨에 답이 있었어요.","포장 글도 따져 봐요.","조건까지 읽고 확인해요."],"asset":{"type":"speech","turns":[{"who":"채린","text":"지난주에 「이 지우개는 자국이 하나도 남지 않는다」는 말을 보고 샀거든."},{"who":"소담","text":"써 보니까 어땠는데?"},{"who":"채린","text":"자국은 남더라. 포장을 다시 읽어 봤더니 작은 글씨로 종이에 따라 다르다고 적혀 있었어."},{"who":"소담","text":"앞의 큰 글씨만 읽었으니 그런 거네. 다음부터는 뒤까지 읽어 봐야겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#2','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C18',2,'ox','auto','「안전모를 쓰면 자전거가 더 빨리 달린다」는 두 곳에서 걸려요.',ARRAY['K6-1-u6-X28']::text[],false,'{"seq":2,"concept":"K6-1-u6-C18","difficulty":2,"kind":"ox","stem":"「안전모를 쓰면 자전거가 더 빨리 달린다」는 두 곳에서 걸려요.","answer":"O","reason_options":[{"t":"실제로 일어나지 않는 일이고, 빨리 달리는 일은 안전하자는 주장과도 어긋나기 때문에","correct":true},{"t":"한 문장은 한 곳에만 걸리기 때문에","mis":"K6-1-u6-X28"}],"mis":"K6-1-u6-X28","explanation":["사실이 아니에요.","주장과도 어긋나요.","한 문장이 두 곳에 걸릴 수 있어요 — 안전모는 빠르기와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#3','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C16',3,'mc','auto','「사흘 동안 세어 보니 열 대 가운데 두 대뿐이었다」가 받치는 이유는 어느 것인가요?',ARRAY['K6-1-u6-X16']::text[],false,'{"seq":3,"concept":"K6-1-u6-C16","difficulty":3,"kind":"mc","stem":"「사흘 동안 세어 보니 열 대 가운데 두 대뿐이었다」가 받치는 이유는 어느 것인가요?","options":[{"t":"나를 지키는 습관을 일찍 들일 수 있다","correct":true},{"t":"넘어질 때 머리를 지켜 준다","mis":"K6-1-u6-X16"},{"t":"자전거가 더 빨리 달린다","mis":"K6-1-u6-X16"},{"t":"머리에 잘 맞게 써야 제 몫을 한다","mis":"K6-1-u6-X16"}],"explanation":["그 이유의 근거는 스티로폼 층이에요.","이 이유는 걸린 문장이에요.","같은 문단 ④ 안에서 짝을 찾아요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#4','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C19',3,'mc','auto','안전모 글 문단 ⑤의 근거를 알맞게 고쳐 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X12']::text[],false,'{"seq":4,"concept":"K6-1-u6-C19","difficulty":3,"kind":"mc","stem":"안전모 글 문단 ⑤의 근거를 알맞게 고쳐 쓴 것은 어느 것인가요?","options":[{"t":"안전모 상자에는 머리둘레에 맞는 크기를 고르고 끈을 턱 아래에서 조이라고 적혀 있다","correct":true},{"t":"옆 반 친구도 그렇다고 말해 주었다","mis":"K6-1-u6-X19"},{"t":"아마 다들 그렇게 생각할 것이다","mis":"K6-1-u6-X12"},{"t":"형이 아주 크게 말해 주었다","mis":"K6-1-u6-X19"}],"explanation":["전해 들은 말이 하나 더 붙었을 뿐이에요.","짐작이에요.","누구나 확인할 수 있는 사실이에요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#5','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C17',3,'mc','auto','「가치 있다 — 글에 그렇게 적혀 있으므로」가 좋은 답이 아닌 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X37','K6-1-u6-X08','K6-1-u6-X01']::text[],false,'{"seq":5,"concept":"K6-1-u6-C17","difficulty":3,"kind":"mc","stem":"「가치 있다 — 글에 그렇게 적혀 있으므로」가 좋은 답이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"적혀 있다는 것은 주장이 왜 가치 있는지를 말해 주지 않기 때문이다","correct":true},{"t":"가치 있다는 판단이 틀렸기 때문이다","mis":"K6-1-u6-X37"},{"t":"까닭이 너무 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"글은 언제나 옳기 때문이다","mis":"K6-1-u6-X01"}],"explanation":["판단은 맞았어요.","길이 문제가 아니에요.","까닭이 판단을 받쳐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#6','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C20',3,'mc','auto','안전모 글의 근거를 따지기 전에 먼저 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X20']::text[],false,'{"seq":6,"concept":"K6-1-u6-C20","difficulty":3,"kind":"mc","stem":"안전모 글의 근거를 따지기 전에 먼저 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 이유를 먼저 재고, 근거가 어느 이유에 붙는지 잡는다","correct":true},{"t":"근거의 글자 수를 센다","mis":"K6-1-u6-X08"},{"t":"근거만 보고 주장은 건너뛴다","mis":"K6-1-u6-X20"},{"t":"세 기준을 아무 문단에나 한꺼번에 댄다","mis":"K6-1-u6-X20"}],"explanation":["글자 수는 관계없어요.","주장부터 재요.","주장 → 이유 → 근거 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#7','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C21',3,'mc','auto','「여섯 문단 가운데 걸린 곳은 두 군데」라고 판단한 뒤에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X05','K6-1-u6-X35']::text[],false,'{"seq":7,"concept":"K6-1-u6-C21","difficulty":3,"kind":"mc","stem":"「여섯 문단 가운데 걸린 곳은 두 군데」라고 판단한 뒤에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"걸린 두 곳은 고칠 방법을 적고, 나머지는 받아들인다","correct":true},{"t":"걸린 곳이 있으니 글을 버린다","mis":"K6-1-u6-X21"},{"t":"걸린 곳을 더 찾을 때까지 트집을 잡는다","mis":"K6-1-u6-X05"},{"t":"걸린 곳도 그냥 둔다","mis":"K6-1-u6-X35"}],"explanation":["쓸 정보까지 버려요.","트집이 목적이 아니에요.","받아들일 것과 고칠 것을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#8','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C22',4,'mc','auto','교실 게시판에 「쉬는 시간에는 교실에서만 놉시다. 운동장은 넓기 때문입니다.」가 붙었어요. 가장 알맞은 판단은 어느 것인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X22','K6-1-u6-X06']::text[],false,'{"seq":8,"concept":"K6-1-u6-C22","difficulty":4,"kind":"mc","stem":"교실 게시판에 「쉬는 시간에는 교실에서만 놉시다. 운동장은 넓기 때문입니다.」가 붙었어요. 가장 알맞은 판단은 어느 것인가요?","options":[{"t":"이유가 주장과 이어지지 않는다 — 운동장이 넓다는 말은 교실에서만 놀자는 주장을 받치지 못한다","correct":true},{"t":"주장이 짧아서 가치가 없다","mis":"K6-1-u6-X08"},{"t":"게시판 글이니 판단하지 않는다","mis":"K6-1-u6-X22"},{"t":"그냥 별로다","mis":"K6-1-u6-X06"}],"explanation":["길이로 가치를 재지 않아요.","둘레의 글에도 대어 봐요.","판단에 까닭이 붙었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#9','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C21',4,'essay','teacher','안전모 글을 판단한 결과를 「받아들일 것」과 「걸린 것」으로 나누어 쓰고, 각각의 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C21","difficulty":4,"kind":"essay","stem":"안전모 글을 판단한 결과를 「받아들일 것」과 「걸린 것」으로 나누어 쓰고, 각각의 까닭을 쓰세요.","answer_guide":{"answer":"예: 받아들일 것 — 안전모를 쓰자는 주장(다치는 일을 줄여 주어 가치 있다), 머리를 지켜 준다는 이유와 스티로폼 층 근거(누구나 확인할 수 있다), 사흘 동안 센 기록(직접 센 기록이다). 걸린 것 — 문단 ③ 「더 빨리 달린다」(사실이 아니고 주장과도 어긋난다), 문단 ⑤ 옆집 형의 말(전해 들은 말이라 확인할 수 없다).","scoring_points":["받아들일 것을 까닭과 함께 썼는가","걸린 두 곳을 까닭과 함께 썼는가","글 전체를 버리지 않았는가"]},"explanation":["정리표를 떠올려요.","걸린 곳은 둘이에요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["④ 셋째, 나를 지키는 습관을 일찍 들일 수 있습니다. 우리 학교 자전거 보관대를","사흘 동안 세어 보니, 안전모를 함께 걸어 둔 자전거는 열 대 가운데 두 대뿐이었습니다.","⑤ 넷째, 안전모는 머리에 잘 맞게 써야 제 몫을 합니다.","옆집 형이 헐렁한 안전모는 소용이 없다고 말해 주었습니다.","⑥ 그 잠깐이 오래 남을 일을 막아 줍니다. 자전거를 탈 때에는 안전모를 씁시다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L04_challenge#10','kor',6,1,'u6','L04','g6_1_kor_u6_L04_challenge','lesson_challenge','K6-1-u6-C18',4,'essay','teacher','문단 ③의 이유가 걸리는 두 곳을 쓰고, 주장 편에 서도록 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C18","difficulty":4,"kind":"essay","stem":"문단 ③의 이유가 걸리는 두 곳을 쓰고, 주장 편에 서도록 고쳐 쓰세요.","answer_guide":{"answer":"예: 첫째, 안전모는 자전거의 빠르기와 관계가 없어 실제로 일어나지 않는 일이다. 둘째, 빨리 달리는 일은 안전을 지키자는 주장과도 어긋난다. 고쳐 쓰면 — 「안전모에는 구멍이 뚫려 있어 오래 써도 답답하지 않습니다.」","scoring_points":["사실이 아님을 썼는가","주장과 어긋남을 썼는가","주장 편으로 고쳐 썼는가"]},"explanation":["정말 일어나는 일인지 물어요.","주장 편인지 물어요.","같은 사실을 주장 쪽으로 이어요."],"asset":{"type":"passage","lines":["① 자전거를 타는 사람이 늘어난 만큼 넘어지는 일도 늘었습니다.","자전거를 탈 때에는 안전모를 썼으면 좋겠습니다.","② 첫째, 넘어질 때 머리를 지켜 줍니다. 안전모 안쪽에 든 두꺼운 스티로폼 층이","부딪히는 힘을 나누어 받습니다.","③ 둘째, 안전모를 쓰면 자전거가 더 빨리 달립니다.","안전모에는 구멍이 여러 개 뚫려 있어 바람이 지나갑니다."],"title":"「자전거를 탈 때 안전모를 씁시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#1','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C23',1,'mc','auto','「표현의 적절성」이 재는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X03']::text[],false,'{"seq":1,"concept":"K6-1-u6-C23","difficulty":1,"kind":"mc","stem":"「표현의 적절성」이 재는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 내용을 알맞은 말로 나타냈는가","correct":true},{"t":"글씨가 예쁜가","mis":"K6-1-u6-X23"},{"t":"문장이 긴가","mis":"K6-1-u6-X23"},{"t":"주장이 가치 있고 중요한가","mis":"K6-1-u6-X03"}],"explanation":["글씨는 재지 않아요.","길이도 아니에요.","어떻게 말했는가를 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#2','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C26',1,'match','auto','표현의 적절성을 재는 기준과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C26","difficulty":1,"kind":"match","stem":"표현의 적절성을 재는 기준과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"거짓된 표현","r":"없는 것을 있는 것처럼 말함"},{"l":"과장된 표현","r":"있는 것을 실제보다 부풀림"},{"l":"감추는 내용","r":"알아야 할 것을 밝히지 않음"}],"mis":"K6-1-u6-X25","explanation":["없는 걸 있다고 하면 거짓이에요.","있는 걸 부풀리면 과장이에요.","빠뜨리면 감춤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#3','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C24',1,'mc','auto','재이가 깨달은 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X01']::text[],false,'{"seq":3,"concept":"K6-1-u6-C24","difficulty":1,"kind":"mc","stem":"재이가 깨달은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 크게 했는지만큼 무엇을 작게 했는지도 보아야 한다","correct":true},{"t":"큰 글씨만 보면 된다","mis":"K6-1-u6-X24"},{"t":"작은 글씨는 실수로 작게 쓴 것이다","mis":"K6-1-u6-X24"},{"t":"빨간 글씨는 다 맞는 말이다","mis":"K6-1-u6-X01"}],"explanation":["큰 글씨만 보면 조건을 놓쳐요.","일부러 작게 쓴 거예요.","작게 쓴 것도 살펴요."],"asset":{"type":"speech","turns":[{"who":"라율","text":"문구점 앞에 「하나 사면 하나 더」라고 크고 빨갛게 적혀 있었어."},{"who":"재이","text":"그 글씨만 눈에 들어오지. 그런데 밑에 작게 뭐라고 더 적혀 있지 않았어?"},{"who":"라율","text":"맞아. 가서 보니 정해진 물건 몇 가지만 그렇다고 아주 작게 적혀 있더라."},{"who":"재이","text":"큰 글씨는 눈에 띄라고 크게 쓴 거고, 작은 글씨는 안 보이라고 작게 쓴 거네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#4','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C24',1,'mc','auto','광고에서 「여기를 봐 달라」고 표시한 자국으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X24']::text[],false,'{"seq":4,"concept":"K6-1-u6-C24","difficulty":1,"kind":"mc","stem":"광고에서 「여기를 봐 달라」고 표시한 자국으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 글씨 · 진한 색 · 느낌표","correct":true},{"t":"아주 작은 글씨","mis":"K6-1-u6-X24"},{"t":"흐린 회색 글씨","mis":"K6-1-u6-X24"},{"t":"비워 둔 곳","mis":"K6-1-u6-X24"}],"explanation":["작은 글씨는 눈에 덜 띄어요.","흐린 글씨도 그래요.","크게 · 진하게 · 느낌표로 강조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#5','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C25',2,'mc','auto','물통 광고에서 거짓된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X25']::text[],false,'{"seq":5,"concept":"K6-1-u6-C25","difficulty":2,"kind":"mc","stem":"물통 광고에서 거짓된 표현은 어느 것인가요?","options":[{"t":"뚜껑을 열어도 얼음이 녹지 않아요","correct":true},{"t":"두 겹 벽이 바깥 열을 막아 줍니다","mis":"K6-1-u6-X05"},{"t":"가방에 넣어 들고 다닐 수 있습니다","mis":"K6-1-u6-X05"},{"t":"여름 준비, 이것 하나면 끝!","mis":"K6-1-u6-X25"}],"explanation":["실제로 있는 기능이에요.","「이것 하나면 끝」은 부풀린 과장이라 거짓과 갈라요.","뚜껑을 열면 바깥 공기가 바로 들어와 얼음이 녹아요 — 거짓이에요."],"asset":{"type":"passage","lines":["장면 ① 물통을 든 아이가 환하게 웃는 큰 그림","　　「여름 준비, 이것 하나면 끝!」 「하루 종일 시원한 물통」","장면 ② 물통 안에 얼음이 가득한 그림","　　「얼음이 하루 종일 그대로! 뚜껑을 열어도 녹지 않아요.」","　　「두 겹 벽이 바깥 열을 막아 줍니다.」"],"title":"물통 광고 「하루 종일 시원한 물통」 — 앞 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#6','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C26',2,'mc','auto','과장된 표현과 그 까닭을 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X24','K6-1-u6-X27']::text[],false,'{"seq":6,"concept":"K6-1-u6-C26","difficulty":2,"kind":"mc","stem":"과장된 표현과 그 까닭을 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"「절대 새지 않는」 — 새지 않게 만든 것은 맞지만 어떤 경우에도 그렇다고 부풀렸다","correct":true},{"t":"「절대 새지 않는」 — 없는 기능을 있다고 했다","mis":"K6-1-u6-X25"},{"t":"「※ 뚜껑을 끝까지 … 샐 수 있음」 — 작게 써서 부풀렸다","mis":"K6-1-u6-X24"},{"t":"「가장 많이 팔린 일등」 — 어떤 경우에도 그렇다고 했다","mis":"K6-1-u6-X27"}],"explanation":["새지 않게 만든 기능은 있어요.","작은 글씨는 부풀린 게 아니에요.","있는 기능을 부풀렸어요 — 작은 글씨가 스스로 샐 수 있다고 밝혀요."],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#7','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C27',2,'mc','auto','감추는 내용이 있는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X24']::text[],false,'{"seq":7,"concept":"K6-1-u6-C27","difficulty":2,"kind":"mc","stem":"감추는 내용이 있는 문구는 어느 것인가요?","options":[{"t":"가장 많이 팔린 일등!","correct":true},{"t":"두 겹 벽이 바깥 열을 막아 줍니다","mis":"K6-1-u6-X05"},{"t":"물을 담아 들고 다니는 물통","mis":"K6-1-u6-X05"},{"t":"※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음","mis":"K6-1-u6-X24"}],"explanation":["있는 기능을 밝혔어요.","되묻고 싶은 게 남지 않아요.","언제 · 어디에서 · 무엇과 견주어 일등인지 밝히지 않았어요."],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#8','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C28',2,'mc','auto','거짓된 표현과 과장된 표현을 가르는 자로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X23','K6-1-u6-X25']::text[],false,'{"seq":8,"concept":"K6-1-u6-C28","difficulty":2,"kind":"mc","stem":"거짓된 표현과 과장된 표현을 가르는 자로 알맞은 것은 어느 것인가요?","options":[{"t":"그 기능이 실제로 있는가","correct":true},{"t":"글씨가 얼마나 큰가","mis":"K6-1-u6-X24"},{"t":"느낌표가 몇 개인가","mis":"K6-1-u6-X23"},{"t":"값이 얼마인가","mis":"K6-1-u6-X25"}],"explanation":["크기로 가르지 않아요.","느낌표 개수가 아니에요.","없으면 거짓, 부풀리면 과장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#9','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C30',2,'ox','auto','부풀리고 감추는 일은 광고에서만 일어나요.',ARRAY['K6-1-u6-X29']::text[],false,'{"seq":9,"concept":"K6-1-u6-C30","difficulty":2,"kind":"ox","stem":"부풀리고 감추는 일은 광고에서만 일어나요.","answer":"X","reason_options":[{"t":"설득하려는 글이면 주장하는 글이나 안내문에서도 일어날 수 있기 때문에","correct":true},{"t":"광고는 물건을 팔려는 글이라 광고만 그렇기 때문에","mis":"K6-1-u6-X29"}],"mis":"K6-1-u6-X29","explanation":["광고만의 일이 아니에요.","안내문도 따져 봐요.","어떤 글 앞에서도 세 물음을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_basic#10','kor',6,1,'u6','L07','g6_1_kor_u6_L07_basic','lesson_basic','K6-1-u6-C29',3,'mc','auto','「이보다 좋은 물통은 없습니다!」를 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X25','K6-1-u6-X26']::text[],false,'{"seq":10,"concept":"K6-1-u6-C29","difficulty":3,"kind":"mc","stem":"「이보다 좋은 물통은 없습니다!」를 바르게 판단한 것은 어느 것인가요?","options":[{"t":"실제보다 부풀린 과장이면서, 어떤 점에서 좋은지 밝히지 않은 감춤이기도 하다","correct":true},{"t":"과장일 뿐 감춤과는 상관없다","mis":"K6-1-u6-X28"},{"t":"없는 기능을 말한 거짓일 뿐이다","mis":"K6-1-u6-X25"},{"t":"알맞은 표현이다","mis":"K6-1-u6-X26"}],"explanation":["한 기준에만 걸리지 않아요.","물통의 기능은 있어요.","두 기준에 함께 걸려요."],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#1','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C25',2,'sa','auto','없는 기능을 있다고 말한 표현을 무엇이라고 하는지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u6-C25","difficulty":2,"kind":"sa","stem":"없는 기능을 있다고 말한 표현을 무엇이라고 하는지 쓰세요.","answer":["거짓된표현","거짓된 표현"],"explanation":["과장과 헷갈리지 말아요.","그 기능이 실제로 없어요.","거짓된 표현이에요."],"mis":"K6-1-u6-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#2','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C26',2,'ox','auto','「여름 준비, 이것 하나면 끝!」은 과장된 표현이에요.',ARRAY['K6-1-u6-X25']::text[],false,'{"seq":2,"concept":"K6-1-u6-C26","difficulty":2,"kind":"ox","stem":"「여름 준비, 이것 하나면 끝!」은 과장된 표현이에요.","answer":"O","reason_options":[{"t":"여름 준비에는 모자나 옷도 있어 물통 하나로 끝나지 않는데 부풀렸기 때문에","correct":true},{"t":"물통에 없는 기능을 있다고 했기 때문에","mis":"K6-1-u6-X25"}],"mis":"K6-1-u6-X25","explanation":["부풀린 말이에요.","물통은 쓸모가 있으니 거짓은 아니에요.","하나로 다 된다고 하면 과장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#3','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C27',3,'mc','auto','감추는 표현을 밝히는 표현으로 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X26','K6-1-u6-X27']::text[],false,'{"seq":3,"concept":"K6-1-u6-C27","difficulty":3,"kind":"mc","stem":"감추는 표현을 밝히는 표현으로 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「아이를 돕는 물통」 → 「물을 여섯 시간 동안 차게 지켜 주는 물통」","correct":true},{"t":"「아이를 돕는 물통」 → 「세상 모든 아이를 돕는 물통」","mis":"K6-1-u6-X26"},{"t":"「아이를 돕는 물통」 → 「아이를 아주아주 돕는 물통」","mis":"K6-1-u6-X26"},{"t":"「아이를 돕는 물통」 → 「아이를 돕는 바로 그 물통」","mis":"K6-1-u6-X27"}],"explanation":["더 부풀렸어요.","크기만 키웠어요.","무엇을 얼마나 하는지 밝혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#4','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C24',3,'mc','auto','물통 광고가 「※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X27','K6-1-u6-X24']::text[],false,'{"seq":4,"concept":"K6-1-u6-C24","difficulty":3,"kind":"mc","stem":"물통 광고가 「※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"꼭 알아야 할 조건을 눈에 들어오지 않게 적어, 큰 글씨 「절대 새지 않는」과 함께 보면 감추는 내용에 가깝다","correct":true},{"t":"작은 글씨는 읽지 않아도 된다","mis":"K6-1-u6-X15"},{"t":"조건을 적었으니 아무 문제가 없다","mis":"K6-1-u6-X27"},{"t":"작게 쓴 것은 실수일 뿐이다","mis":"K6-1-u6-X24"}],"explanation":["조건이 거기 있어요.","읽을 수 있는 크기여야 해요.","작게 한 것도 뜻이 있어요. (바로잡기: 새지 않게 만든 뚜껑도 끝까지 닫지 않으면 샐 수 있어요.)"],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#5','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C30',3,'mc','auto','부풀리지 않았지만 믿기 어려운 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X26']::text[],false,'{"seq":5,"concept":"K6-1-u6-C30","difficulty":3,"kind":"mc","stem":"부풀리지 않았지만 믿기 어려운 표현은 어느 것인가요?","options":[{"t":"아주 오래전에 조사한 내용을 지금도 그렇다고 적은 안내문","correct":true},{"t":"어제 직접 세어 본 기록","mis":"K6-1-u6-X05"},{"t":"「절대 새지 않는」처럼 부풀린 말","mis":"K6-1-u6-X26"},{"t":"상자에 적힌 사용 안내","mis":"K6-1-u6-X05"}],"explanation":["확인할 수 있는 기록이에요.","부풀리지 않은 것을 찾아야 해요.","오래되어 지금과 맞지 않을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#6','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C29',3,'mc','auto','한 표현이 두 기준에 함께 걸릴 수 있음을 알면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X21']::text[],false,'{"seq":6,"concept":"K6-1-u6-C29","difficulty":3,"kind":"mc","stem":"한 표현이 두 기준에 함께 걸릴 수 있음을 알면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"기준 하나로 끝내지 않고 남은 기준으로도 다시 훑어 놓치는 곳이 줄어든다","correct":true},{"t":"걸리는 기준 하나만 찾으면 된다","mis":"K6-1-u6-X28"},{"t":"표현마다 기준을 하나씩만 붙인다","mis":"K6-1-u6-X28"},{"t":"두 기준에 걸리면 그 광고를 버린다","mis":"K6-1-u6-X21"}],"explanation":["하나 찾고 멈추면 놓쳐요.","기준은 서로를 밀어내지 않아요.","버리지 않고 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#7','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C28',3,'mc','auto','「두 겹 벽이 바깥 열을 막아 줍니다」는 알맞고 「뚜껑을 열어도 얼음이 녹지 않아요」는 거짓인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X24','K6-1-u6-X05']::text[],false,'{"seq":7,"concept":"K6-1-u6-C28","difficulty":3,"kind":"mc","stem":"「두 겹 벽이 바깥 열을 막아 줍니다」는 알맞고 「뚜껑을 열어도 얼음이 녹지 않아요」는 거짓인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞은 실제로 있는 기능이고, 뒤는 뚜껑을 열면 바깥 공기가 들어와 막을 수 없는 일을 있다고 했기 때문이다","correct":true},{"t":"앞의 문장이 더 짧기 때문이다","mis":"K6-1-u6-X23"},{"t":"뒤의 문장에는 느낌표가 없기 때문이다","mis":"K6-1-u6-X24"},{"t":"둘 다 거짓이기 때문이다","mis":"K6-1-u6-X05"}],"explanation":["길이로 가르지 않아요.","느낌표와 관계없어요.","기능이 실제로 있는지로 갈라요 — 뚜껑을 열면 얼음은 녹아요."],"asset":{"type":"passage","lines":["장면 ① 물통을 든 아이가 환하게 웃는 큰 그림","　　「여름 준비, 이것 하나면 끝!」 「하루 종일 시원한 물통」","장면 ② 물통 안에 얼음이 가득한 그림","　　「얼음이 하루 종일 그대로! 뚜껑을 열어도 녹지 않아요.」","　　「두 겹 벽이 바깥 열을 막아 줍니다.」"],"title":"물통 광고 「하루 종일 시원한 물통」 — 앞 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#8','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C31',4,'mc','auto','둘레의 광고를 재어 공책에 적은 것 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X17','K6-1-u6-X45']::text[],false,'{"seq":8,"concept":"K6-1-u6-C31","difficulty":4,"kind":"mc","stem":"둘레의 광고를 재어 공책에 적은 것 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「한 번만 발라도 하루 종일 촉촉」 — 과장 ×: 바르는 양과 날씨에 따라 다를 텐데 부풀렸다","correct":true},{"t":"「한 번만 발라도 하루 종일 촉촉」 — × : 그냥 별로","mis":"K6-1-u6-X06"},{"t":"「한 번만 발라도 하루 종일 촉촉」 — ○ : 광고에 적혀 있으니까","mis":"K6-1-u6-X17"},{"t":"「한 번만 발라도 하루 종일 촉촉」 — × : 만든 회사가 싫어서","mis":"K6-1-u6-X45"}],"explanation":["까닭이 없어요.","적혀 있다는 건 까닭이 아니에요.","판단과 까닭이 한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#9','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C27',4,'essay','teacher','물통 광고에서 감추는 내용을 하나 찾아 왜 감춤인지 쓰고, 감춘 것을 밝히는 문구로 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C27","difficulty":4,"kind":"essay","stem":"물통 광고에서 감추는 내용을 하나 찾아 왜 감춤인지 쓰고, 감춘 것을 밝히는 문구로 고쳐 쓰세요.","answer_guide":{"answer":"예: 「가장 많이 팔린 일등!」은 감추는 내용이다. 언제, 어디에서, 무엇과 견주어 일등인지 밝히지 않아 읽고 나서 「그런데 어디에서?」라는 물음이 남는다. 고쳐 쓰면 — 「지난 여름 우리 동네 문구점에서 물통 가운데 가장 많이 팔렸어요.」","scoring_points":["감추는 문구를 찾았는가","무엇을 감추었는지 까닭을 썼는가","감춘 것을 밝히도록 고쳐 썼는가"]},"explanation":["「그런데 어디에서?」가 남는 문구를 찾아요.","빠진 것을 말해요.","빠진 것을 채워 고쳐요."],"asset":{"type":"passage","lines":["장면 ③ 「일등」이라고 적힌 커다란 금빛 딱지","　　「이보다 좋은 물통은 없습니다! 가장 많이 팔린 일등!」","장면 ④ 물통을 가방에 거꾸로 넣은 그림","　　「절대 새지 않는 안심 뚜껑!」","　　(아주 작은 글씨) ※ 뚜껑을 끝까지 돌려 닫지 않으면 샐 수 있음."],"title":"물통 광고 — 뒤 장면 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L07_challenge#10','kor',6,1,'u6','L07','g6_1_kor_u6_L07_challenge','lesson_challenge','K6-1-u6-C30',4,'essay','teacher','「부풀리고 감추는 건 광고니까 그런 거야.」라고 말하는 친구에게, 광고가 아닌 글의 예와 「부풀리지 않았어도 믿기 어려운 경우」를 넣어 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C30","difficulty":4,"kind":"essay","stem":"「부풀리고 감추는 건 광고니까 그런 거야.」라고 말하는 친구에게, 광고가 아닌 글의 예와 「부풀리지 않았어도 믿기 어려운 경우」를 넣어 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 부풀리고 감추는 일은 광고만 하는 게 아니야. 주장하는 글에서 「이것만 하면 모든 문제가 사라진다」고 쓰거나, 안내문에서 꼭 알아야 할 조건을 작게 적는 것도 같아. 그리고 부풀리지 않았어도 아주 오래전에 조사한 내용을 지금도 그렇다고 쓰거나 두루뭉술하게 써서 오해하게 하면 믿기 어려워. 그러니 어떤 글이든 세 물음을 대어 봐야 해.","scoring_points":["광고가 아닌 글의 예를 들었는가","부풀리지 않아도 믿기 어려운 경우를 썼는가","어떤 글에나 기준을 댄다고 정리했는가"]},"explanation":["설득하려는 다른 글을 떠올려요.","오래된 · 흐린 정보를 떠올려요.","세 물음으로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#1','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C32',1,'mc','auto','설명하는 글을 읽을 때 더 조심해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X08','K6-1-u6-X03']::text[],false,'{"seq":1,"concept":"K6-1-u6-C32","difficulty":1,"kind":"mc","stem":"설명하는 글을 읽을 때 더 조심해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"알려 주려고 쓴 글이라 여겨 적힌 대로 외우기 쉽기 때문이다","correct":true},{"t":"설명하는 글은 언제나 거짓이기 때문이다","mis":"K6-1-u6-X05"},{"t":"설명하는 글은 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"설명하는 글에는 표현이 없기 때문이다","mis":"K6-1-u6-X03"}],"explanation":["늘 거짓인 건 아니에요.","길이와 관계없어요.","그대로 외우기 쉬워 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#2','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C32',1,'mc','auto','「숨을 쉬는 그릇, 옹기」가 설명하는 것은 무엇인가요?',ARRAY['K6-1-u6-X04']::text[],false,'{"seq":2,"concept":"K6-1-u6-C32","difficulty":1,"kind":"mc","stem":"「숨을 쉬는 그릇, 옹기」가 설명하는 것은 무엇인가요?","options":[{"t":"옹기의 특징과 쓰임","correct":true},{"t":"김치를 담그는 차례","mis":"K6-1-u6-X04"},{"t":"옛집을 짓는 방법","mis":"K6-1-u6-X04"},{"t":"흙을 고르는 방법","mis":"K6-1-u6-X04"}],"explanation":["김치는 담는 음식으로 나올 뿐이에요.","옛집은 옹기를 둔 곳이에요.","제목과 문단 ①이 함께 가리켜요."],"asset":{"type":"passage","lines":["① 옹기는 흙을 빚어 높은 열에 구운 그릇입니다. 옛사람들은 김치와 간장, 된장처럼","오래 두고 먹는 음식을 옹기에 담았습니다.","② 흙을 구울 때 흙 속에 섞인 아주 작은 알갱이가 타면서 벽에 눈에 보이지 않는","작은 구멍이 남습니다. 이 구멍으로 공기가 아주 천천히 드나듭니다.","③ 김치나 장은 시간이 지나면서 맛이 드는 음식입니다. 이런 음식은 공기가 조금씩","드나드는 그릇에서 맛이 잘 듭니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#3','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C35',1,'ox','auto','과장된 표현은 거짓말이 아니니 그대로 믿어도 돼요.',ARRAY['K6-1-u6-X34']::text[],false,'{"seq":3,"concept":"K6-1-u6-C35","difficulty":1,"kind":"ox","stem":"과장된 표현은 거짓말이 아니니 그대로 믿어도 돼요.","answer":"X","reason_options":[{"t":"있는 것을 부풀려 읽는 사람을 지나치게 믿게 만들기 때문에","correct":true},{"t":"거짓만 아니면 알맞은 표현이기 때문에","mis":"K6-1-u6-X34"}],"mis":"K6-1-u6-X34","explanation":["거짓이 아니어도 걸러요.","더 알아채기 어려워요.","지나친 믿음이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#4','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C32',1,'match','auto','설명하는 글의 걸린 표현과 그것이 읽는 사람에게 남기는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u6-C32","difficulty":1,"kind":"match","stem":"설명하는 글의 걸린 표현과 그것이 읽는 사람에게 남기는 것을 알맞게 이으세요.","pairs":[{"l":"거짓된 표현","r":"잘못된 지식"},{"l":"과장된 표현","r":"지나친 믿음"},{"l":"감추는 내용","r":"한쪽만 아는 사람"}],"mis":"K6-1-u6-X31","explanation":["거짓은 잘못 알게 해요.","과장은 지나치게 믿게 해요.","감춤은 한쪽만 알게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#5','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C34',2,'mc','auto','옹기 글에서 거짓된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X25']::text[],false,'{"seq":5,"concept":"K6-1-u6-C34","difficulty":2,"kind":"mc","stem":"옹기 글에서 거짓된 표현은 어느 것인가요?","options":[{"t":"요즘 대부분의 가정에서도 김치를 옹기에만 담아 보관합니다","correct":true},{"t":"볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다","mis":"K6-1-u6-X05"},{"t":"옹기를 보면 옛사람들이 살림의 이치를 담았음을 알 수 있습니다","mis":"K6-1-u6-X05"},{"t":"옹기는 어디에나 놓아도 좋습니다","mis":"K6-1-u6-X25"}],"explanation":["사실이에요.","글쓴이의 정리예요.","오늘날엔 김치를 냉장고나 밀폐 용기에 더 많이 담아요 — 바르게는 「오늘날에도 장을 담그는 집에서는 옹기를 씁니다」예요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#6','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C35',2,'mc','auto','옹기 글에서 과장된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X28']::text[],false,'{"seq":6,"concept":"K6-1-u6-C35","difficulty":2,"kind":"mc","stem":"옹기 글에서 과장된 표현은 어느 것인가요?","options":[{"t":"옹기에 담아 두면 음식이 절대 상하지 않습니다","correct":true},{"t":"옛집에는 옹기를 나란히 두었습니다","mis":"K6-1-u6-X05"},{"t":"옹기는 어디에나 놓아도 좋습니다","mis":"K6-1-u6-X28"},{"t":"옹기를 보면 살림의 이치를 알 수 있습니다","mis":"K6-1-u6-X05"}],"explanation":["사실이에요.","이건 감추는 내용이에요.","옹기에 담아도 오래 두면 상해요 — 바르게는 「김치나 장의 맛이 천천히 듭니다」예요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#7','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C36',2,'mc','auto','「옹기는 어디에나 놓아도 좋습니다」가 감춘 것은 어느 것인가요?',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":7,"concept":"K6-1-u6-C36","difficulty":2,"kind":"mc","stem":"「옹기는 어디에나 놓아도 좋습니다」가 감춘 것은 어느 것인가요?","options":[{"t":"옹기는 무겁고 잘 깨진다는 점","correct":true},{"t":"옹기는 흙으로 만든다는 점","mis":"K6-1-u6-X27"},{"t":"옹기에 김치를 담았다는 점","mis":"K6-1-u6-X27"},{"t":"감춘 것이 없다","mis":"K6-1-u6-X27"}],"explanation":["앞 문단에서 밝혔어요.","그것도 밝혔어요.","알아야 할 것을 빼놓았어요 — 바르게는 「무겁고 잘 깨지므로 옮기지 않아도 되는 곳에 두어야 합니다」예요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#8','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C33',2,'mc','auto','설명하는 글에 세 기준을 대는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X32']::text[],false,'{"seq":8,"concept":"K6-1-u6-C33","difficulty":2,"kind":"mc","stem":"설명하는 글에 세 기준을 대는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"거짓을 들고 글 전체를 훑고, 다시 과장을, 마지막으로 감춤을 들고 처음부터 훑는다","correct":true},{"t":"한 문단에서 세 기준을 한꺼번에 잰다","mis":"K6-1-u6-X32"},{"t":"첫 문단만 꼼꼼히 잰다","mis":"K6-1-u6-X32"},{"t":"마음에 드는 문단만 잰다","mis":"K6-1-u6-X32"}],"explanation":["한꺼번에 재면 놓쳐요.","글 전체를 훑어요.","기준 하나로 전체를 훑어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#9','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C38',2,'mc','auto','옹기 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X36','K6-1-u6-X31']::text[],false,'{"seq":9,"concept":"K6-1-u6-C38","difficulty":2,"kind":"mc","stem":"옹기 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「옹기를 쓰면서 불편한 점은 없었을까?」","correct":true},{"t":"「옹기는 왜 이렇게 좋을까?」","mis":"K6-1-u6-X36"},{"t":"「이 글을 다 외웠을까?」","mis":"K6-1-u6-X31"},{"t":"「다른 글은 읽을 필요가 없겠지?」","mis":"K6-1-u6-X36"}],"explanation":["같은 쪽에서 본 물음이에요.","외우기가 목적이 아니에요.","다른 쪽에서 물었어요 — 관련 글을 더 찾아 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_basic#10','kor',6,1,'u6','L09','g6_1_kor_u6_L09_basic','lesson_basic','K6-1-u6-C37',3,'mc','auto','걸린 문장과 고쳐 쓴 문장의 짝이 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X33']::text[],false,'{"seq":10,"concept":"K6-1-u6-C37","difficulty":3,"kind":"mc","stem":"걸린 문장과 고쳐 쓴 문장의 짝이 알맞은 것은 어느 것인가요?","options":[{"t":"「절대 상하지 않는다」 → 「김치나 장의 맛이 천천히 든다」","correct":true},{"t":"「어디에나 놓아도 좋다」 → 「어디에나 놓아도 정말 좋다」","mis":"K6-1-u6-X35"},{"t":"「대부분 옹기에만 담는다」 → 「모두 옹기에만 담는다」","mis":"K6-1-u6-X33"},{"t":"「절대 상하지 않는다」 → 「옹기는 그릇이다」","mis":"K6-1-u6-X35"}],"explanation":["감춘 것을 밝히지 않았어요.","더 넓게 말했어요.","부풀린 것을 덜어 냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#1','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C34',2,'mc','auto','설명하는 글에서 나오면 한 번 멈추어야 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X33']::text[],false,'{"seq":1,"concept":"K6-1-u6-C34","difficulty":2,"kind":"mc","stem":"설명하는 글에서 나오면 한 번 멈추어야 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"대부분 · 모두 · 언제나","correct":true},{"t":"그리고 · 그래서","mis":"K6-1-u6-X33"},{"t":"옛날 · 요즘","mis":"K6-1-u6-X33"},{"t":"크다 · 작다","mis":"K6-1-u6-X33"}],"explanation":["이어 주는 말이에요.","때를 나타낼 뿐이에요.","넓게 말하는 말에 멈춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#2','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C39',2,'ox','auto','까닭이 타당하면 나와 다른 판단도 받아들일 수 있어요.',ARRAY['K6-1-u6-X37']::text[],false,'{"seq":2,"concept":"K6-1-u6-C39","difficulty":2,"kind":"ox","stem":"까닭이 타당하면 나와 다른 판단도 받아들일 수 있어요.","answer":"O","reason_options":[{"t":"까닭이 붙은 판단은 따져 볼 수 있고, 판단은 하나로 정해진 답을 맞히는 일이 아니기 때문에","correct":true},{"t":"판단은 언제나 하나로 정해져 있기 때문에","mis":"K6-1-u6-X37"}],"mis":"K6-1-u6-X37","explanation":["까닭을 들어 봐요.","따져 보고 받아들여요.","다른 판단도 열려 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#3','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C36',3,'mc','auto','감추는 내용을 찾는 신호로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X24','K6-1-u6-X23']::text[],false,'{"seq":3,"concept":"K6-1-u6-C36","difficulty":3,"kind":"mc","stem":"감추는 내용을 찾는 신호로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 나서 되묻고 싶은 것이 남는다","correct":true},{"t":"문장에 사실이 아닌 말이 있다","mis":"K6-1-u6-X25"},{"t":"느낌표가 많다","mis":"K6-1-u6-X24"},{"t":"문장이 길다","mis":"K6-1-u6-X23"}],"explanation":["그건 거짓의 신호예요.","느낌표 수와 관계없어요.","되물을 게 남으면 따라가 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#4','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C33',3,'mc','auto','한 문단에서 세 기준을 한꺼번에 재지 않는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X32','K6-1-u6-X46']::text[],false,'{"seq":4,"concept":"K6-1-u6-C33","difficulty":3,"kind":"mc","stem":"한 문단에서 세 기준을 한꺼번에 재지 않는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한꺼번에 재면 놓치기 쉽고, 글 전체가 고르게 알맞거나 고르게 어긋나지는 않기 때문이다","correct":true},{"t":"세 기준은 한 문단에만 쓰기 때문이다","mis":"K6-1-u6-X32"},{"t":"기준은 하나만 쓰면 되기 때문이다","mis":"K6-1-u6-X46"},{"t":"문단은 따질 필요가 없기 때문이다","mis":"K6-1-u6-X32"}],"explanation":["글 전체에 대요.","세 기준을 다 대요.","기준 하나로 전체를 훑어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#5','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C39',3,'mc','auto','「이 문장은 과장됐어」에 까닭을 붙여 말한 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X37','K6-1-u6-X45']::text[],false,'{"seq":5,"concept":"K6-1-u6-C39","difficulty":3,"kind":"mc","stem":"「이 문장은 과장됐어」에 까닭을 붙여 말한 것은 어느 것인가요?","options":[{"t":"「옹기에 담아도 오래 두면 상하니까 과장됐어.」","correct":true},{"t":"「그냥 과장된 느낌이야.」","mis":"K6-1-u6-X06"},{"t":"「내 판단과 다르면 다 틀린 거야.」","mis":"K6-1-u6-X37"},{"t":"「글쓴이가 별로라서 과장이야.」","mis":"K6-1-u6-X45"}],"explanation":["느낌뿐이에요.","까닭을 들어 봐야 해요.","사람이 아니라 문장을 판단해요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#6','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C38',3,'mc','auto','다른 관점의 글을 더 찾아 읽은 뒤 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X36','K6-1-u6-X01']::text[],false,'{"seq":6,"concept":"K6-1-u6-C38","difficulty":3,"kind":"mc","stem":"다른 관점의 글을 더 찾아 읽은 뒤 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"처음 글에 없던 사실을 보태 적고, 판단을 다시 해 본다","correct":true},{"t":"처음 글이 틀렸다며 버린다","mis":"K6-1-u6-X21"},{"t":"두 글 가운데 마음에 드는 쪽만 믿는다","mis":"K6-1-u6-X36"},{"t":"새로 읽은 글은 따지지 않고 믿는다","mis":"K6-1-u6-X01"}],"explanation":["버리지 않고 보태요.","두 쪽을 함께 봐요.","새 글도 따져 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#7','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C32',3,'mc','auto','「요즘 대부분의 가정에서도 김치를 옹기에만 담아 보관합니다」를 그대로 외운 학생에게 생길 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X31']::text[],false,'{"seq":7,"concept":"K6-1-u6-C32","difficulty":3,"kind":"mc","stem":"「요즘 대부분의 가정에서도 김치를 옹기에만 담아 보관합니다」를 그대로 외운 학생에게 생길 일로 알맞은 것은 어느 것인가요?","options":[{"t":"오늘날 김치를 보관하는 방법에 대해 잘못된 지식을 갖게 된다","correct":true},{"t":"한쪽만 아는 사람이 된다","mis":"K6-1-u6-X25"},{"t":"아무 일도 생기지 않는다","mis":"K6-1-u6-X31"},{"t":"옹기를 더 정확히 알게 된다","mis":"K6-1-u6-X31"}],"explanation":["그건 감추는 내용이 남기는 거예요.","외운 것이 지식이 돼요.","거짓은 잘못된 지식이 돼요 — 오늘날엔 냉장고나 밀폐 용기를 더 많이 써요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#8','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C37',4,'mc','auto','「옹기는 어디에나 놓아도 좋습니다」를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X26']::text[],false,'{"seq":8,"concept":"K6-1-u6-C37","difficulty":4,"kind":"mc","stem":"「옹기는 어디에나 놓아도 좋습니다」를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"옹기는 무겁고 잘 깨지므로 옮기지 않아도 되는 곳에 두어야 합니다","correct":true},{"t":"옹기는 어디에나 놓아도 아주 좋습니다","mis":"K6-1-u6-X35"},{"t":"옹기는 절대 깨지지 않으니 어디에나 둡니다","mis":"K6-1-u6-X26"},{"t":"옹기는 어디에도 두지 맙시다","mis":"K6-1-u6-X35"}],"explanation":["감춘 것을 밝히지 않았어요.","거꾸로 부풀렸어요.","알아야 할 것을 밝혔어요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#9','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C38',4,'essay','teacher','옹기 글은 옹기의 좋은 점만 드러내요. 다른 관점의 물음을 두 가지 쓰고, 그 답을 어디에서 찾을지와 한 편만 읽고 판단하면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C38","difficulty":4,"kind":"essay","stem":"옹기 글은 옹기의 좋은 점만 드러내요. 다른 관점의 물음을 두 가지 쓰고, 그 답을 어디에서 찾을지와 한 편만 읽고 판단하면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 물음 — 「옹기를 쓰면서 불편한 점은 없었을까?」, 「왜 오늘날에는 옹기를 덜 쓸까?」 학교 도서관의 책이나 백과사전에서 옹기와 관련 있는 글을 한 편 더 찾아 읽겠다. 한 편의 글은 한쪽 이야기만 담을 수 있어서, 그것만 읽고 판단하면 옹기를 한쪽만 아는 사람이 되기 때문이다.","scoring_points":["다른 관점의 물음을 두 가지 썼는가","찾아 읽을 곳을 썼는가","한 편만 읽으면 안 되는 까닭을 썼는가"]},"explanation":["다른 쪽에서 물어요.","찾을 곳을 정해요.","한쪽만 알게 되는 위험을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L09_challenge#10','kor',6,1,'u6','L09','g6_1_kor_u6_L09_challenge','lesson_challenge','K6-1-u6-C37',4,'essay','teacher','옹기 글의 걸린 문장 셋 가운데 둘을 골라, 어느 기준에 걸리는지 · 그 까닭 · 고쳐 쓴 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C37","difficulty":4,"kind":"essay","stem":"옹기 글의 걸린 문장 셋 가운데 둘을 골라, 어느 기준에 걸리는지 · 그 까닭 · 고쳐 쓴 문장을 쓰세요.","answer_guide":{"answer":"예: 「옹기에 담아 두면 음식이 절대 상하지 않습니다」는 과장된 표현이다. 옹기에 담아도 오래 두면 상하기 때문이다. 고쳐 쓰면 「옹기에 담아 두면 김치나 장의 맛이 천천히 듭니다.」 「옹기는 어디에나 놓아도 좋습니다」는 감추는 내용이 있다. 무겁고 잘 깨진다는 점을 밝히지 않았다. 고쳐 쓰면 「옹기는 무겁고 잘 깨지므로 옮기지 않아도 되는 곳에 두어야 합니다.」","scoring_points":["걸리는 기준을 바르게 썼는가","까닭을 썼는가","기준에 맞게 고쳐 썼는가"]},"explanation":["기준을 먼저 정해요.","까닭을 대요.","덜어 내거나 더 밝혀요."],"asset":{"type":"passage","lines":["④ 옛집에는 볕이 잘 들고 바람이 통하는 곳에 옹기를 나란히 두었습니다.","옹기는 어디에나 놓아도 좋습니다.","⑤ 옹기에 담아 두면 음식이 절대 상하지 않습니다. 그래서 요즘 대부분의 가정에서도","김치를 옹기에만 담아 보관합니다.","⑥ 옹기를 보면 옛사람들이 그릇 하나에도 살림의 이치를 담았음을 알 수 있습니다."],"title":"「숨을 쉬는 그릇, 옹기」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#1','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C41',1,'mc','auto','공익 광고의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X39']::text[],false,'{"seq":1,"concept":"K6-1-u6-C41","difficulty":1,"kind":"mc","stem":"공익 광고의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빌린 물건은 빌린 그대로 돌려주자","correct":true},{"t":"망가뜨릴까 걱정되니 아무것도 빌려주지 말자","mis":"K6-1-u6-X39"},{"t":"빌려 간 사람이 알아서 하게 두자","mis":"K6-1-u6-X39"},{"t":"내 물건이 얼마나 좋은지 자랑하자","mis":"K6-1-u6-X39"}],"explanation":["다른 문제를 만들어요.","고쳐지지 않아요.","여럿에게 도움이 되고 고치면 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#2','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C48',1,'match','auto','문장의 빈칸에 알맞은 낱말을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u6-C48","difficulty":1,"kind":"match","stem":"문장의 빈칸에 알맞은 낱말을 이으세요.","pairs":[{"l":"고무줄을 길게 (　)","r":"늘이다"},{"l":"쉬는 시간을 조금 더 (　)","r":"늘리다"},{"l":"과녁 한가운데를 (　)","r":"맞히다"}],"mis":"K6-1-u6-X47","explanation":["길게 하면 늘이다예요.","많게 하면 늘리다예요.","겨냥한 곳에 닿게 하면 맞히다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#3','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C49',1,'mc','auto','바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":3,"concept":"K6-1-u6-C49","difficulty":1,"kind":"mc","stem":"바르게 쓴 문장은 어느 것인가요?","options":[{"t":"그렇게 하면 안 돼요.","correct":true},{"t":"감기가 다 낳았습니다.","mis":"K6-1-u6-X48"},{"t":"몇일이나 걸릴까요?","mis":"K6-1-u6-X48"},{"t":"오랫만에 사촌을 만났습니다.","mis":"K6-1-u6-X48"}],"explanation":["병이 없어지면 「나았다」예요.","「며칠」이 바른 말이에요.","「되어요」가 줄면 「돼요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#4','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C40',1,'mc','auto','만드는 사람이 되어 광고를 만들 때 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X38','K6-1-u6-X42']::text[],false,'{"seq":4,"concept":"K6-1-u6-C40","difficulty":1,"kind":"mc","stem":"만드는 사람이 되어 광고를 만들 때 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽을 때 걸렸던 것들이 만들 때 하지 말아야 할 것이 된다","correct":true},{"t":"남의 글에서 찾은 흠도 내 글에서는 괜찮다","mis":"K6-1-u6-X38"},{"t":"만들 때는 눈에 띄기만 하면 된다","mis":"K6-1-u6-X42"},{"t":"만들 때는 배운 기준을 잊어도 된다","mis":"K6-1-u6-X38"}],"explanation":["내 글에서도 흠이에요.","믿을 수 있어야 해요.","자를 뒤집어 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#5','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C42',2,'mc','auto','첫 번째 초안에서 고치지 않아도 되는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X26']::text[],false,'{"seq":5,"concept":"K6-1-u6-C42","difficulty":2,"kind":"mc","stem":"첫 번째 초안에서 고치지 않아도 되는 문구는 어느 것인가요?","options":[{"t":"ㄹ. 빌린 그대로 — 그것이 다음에도 빌릴 수 있는 길","correct":true},{"t":"ㄱ. 빌려주면 백 퍼센트 망가집니다!","mis":"K6-1-u6-X26"},{"t":"ㄴ. 이 광고 하나면 우리 반 문제가 모두 사라집니다.","mis":"K6-1-u6-X26"},{"t":"ㄷ. 빌린 물건, 절대 그냥 돌려주지 마세요.","mis":"K6-1-u6-X26"}],"explanation":["늘 망가지지는 않아요 — 부풀렸어요.","광고 하나로 다 사라지지 않아요.","부풀리지 않고 뜻이 분명해요 — ㄱ~ㄷ은 부풀린 말이라 고쳐 써요."],"asset":{"type":"passage","lines":["장면 — 반으로 갈라진 지우개 옆에 빈 필통이 열려 있는 그림","ㄱ. 빌려주면 백 퍼센트 망가집니다!","ㄴ. 이 광고 하나면 우리 반 문제가 모두 사라집니다.","ㄷ. 빌린 물건, 절대 그냥 돌려주지 마세요.","ㄹ. 빌린 그대로 — 그것이 다음에도 빌릴 수 있는 길"],"title":"공익 광고 첫 번째 초안 「빌린 물건은 빌린 그대로」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#6','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C42',2,'match','auto','부풀린 문구와 알맞게 고친 문구를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u6-C42","difficulty":2,"kind":"match","stem":"부풀린 문구와 알맞게 고친 문구를 이으세요.","pairs":[{"l":"백 퍼센트 망가집니다","r":"빌려준 지우개가 반으로 돌아왔습니다"},{"l":"문제가 모두 사라집니다","r":"한 사람이 지키면 한 사람이 웃습니다"},{"l":"절대 그냥 돌려주지 마세요","r":"돌려줄 때 한 번만 살펴 주세요"}],"mis":"K6-1-u6-X35","explanation":["겪은 일로 바꿨어요.","있는 만큼 말했어요.","뜻은 두고 크기만 줄였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#7','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C43',2,'ox','auto','광고는 틀린 말만 없으면 눈에 띄지 않아도 돼요.',ARRAY['K6-1-u6-X41']::text[],false,'{"seq":7,"concept":"K6-1-u6-C43","difficulty":2,"kind":"ox","stem":"광고는 틀린 말만 없으면 눈에 띄지 않아도 돼요.","answer":"X","reason_options":[{"t":"짧은 순간에 인상을 남겨야 하는 글이라 아무도 보지 않으면 뜻을 전하지 못하기 때문에","correct":true},{"t":"광고는 적절성만 재면 되기 때문에","mis":"K6-1-u6-X41"}],"mis":"K6-1-u6-X41","explanation":["눈에 띄어야 해요.","적절성만 재지는 않아요.","믿을 수 있으면서 눈에 띄게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#8','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C44',2,'mc','auto','광고의 표현 요소를 알맞게 고른 것은 어느 것인가요?',ARRAY['K6-1-u6-X43']::text[],false,'{"seq":8,"concept":"K6-1-u6-C44","difficulty":2,"kind":"mc","stem":"광고의 표현 요소를 알맞게 고른 것은 어느 것인가요?","options":[{"t":"가장 하고 싶은 한 줄만 크게 하고, 꼭 알릴 조건은 읽을 수 있는 크기로 적는다","correct":true},{"t":"모든 줄을 다 크게 한다","mis":"K6-1-u6-X43"},{"t":"온통 진한 색으로 칠한다","mis":"K6-1-u6-X43"},{"t":"조건은 아주 작게 적는다","mis":"K6-1-u6-X43"}],"explanation":["다 크면 아무것도 크지 않아요.","온통 진하면 강조가 사라져요.","조건은 읽을 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#9','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C46',2,'mc','auto','친구의 광고를 판단하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X45']::text[],false,'{"seq":9,"concept":"K6-1-u6-C46","difficulty":2,"kind":"mc","stem":"친구의 광고를 판단하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「〈모두 사라집니다〉가 부풀려졌어. 실제로는 늘 그렇지는 않으니까. 그림은 주제를 잘 보여 줘.」","correct":true},{"t":"「이건 과장이야.」","mis":"K6-1-u6-X06"},{"t":"「너는 원래 부풀리기를 잘하잖아.」","mis":"K6-1-u6-X45"},{"t":"「별로인 것 같아.」","mis":"K6-1-u6-X06"}],"explanation":["까닭이 없어요.","사람이 아니라 문구를 봐요.","까닭과 잘한 점이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_basic#10','kor',6,1,'u6','L12','g6_1_kor_u6_L12_basic','lesson_basic','K6-1-u6-C47',3,'mc','auto','「그늘막을 더 세웁시다」에서 표현이 알맞지 않은 문장과 걸리는 기준을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-1-u6-X03','K6-1-u6-X05','K6-1-u6-X26']::text[],false,'{"seq":10,"concept":"K6-1-u6-C47","difficulty":3,"kind":"mc","stem":"「그늘막을 더 세웁시다」에서 표현이 알맞지 않은 문장과 걸리는 기준을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"「더위가 모두 사라집니다」 — 과장 / 「절대 덥지 않습니다」 — 거짓","correct":true},{"t":"「이야기를 나눌 수 있어 즐겁습니다」 — 과장","mis":"K6-1-u6-X03"},{"t":"「세우는 데 오래 걸리지 않습니다」 — 거짓","mis":"K6-1-u6-X05"},{"t":"「절대 덥지 않습니다」 — 알맞은 표현","mis":"K6-1-u6-X26"}],"explanation":["그건 내용(어긋난 이유)에서 걸려요.","걸리지 않는 문장이에요.","그늘막 아래도 더울 수 있어요 — 바르게는 「볕을 가려 조금 덜 덥습니다」예요."],"asset":{"type":"passage","lines":["④ 셋째, 그늘막 아래에서는 친구들과 이야기를 나눌 수 있어 즐겁습니다.","⑤ 그늘막 하나면 여름 더위가 모두 사라집니다. 그늘막 아래에서는 절대 덥지 않습니다.","⑥ 그늘막은 세우는 데 오래 걸리지 않습니다.","여름이 오기 전에 건널목 앞에 그늘막을 더 세웁시다."],"title":"「그늘막을 더 세웁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#1','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C45',2,'mc','auto','광고를 발표할 때 밝힐 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u6-X44','K6-1-u6-X42']::text[],false,'{"seq":1,"concept":"K6-1-u6-C45","difficulty":2,"kind":"mc","stem":"광고를 발표할 때 밝힐 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구 광고보다 내 광고가 낫다는 말","correct":true},{"t":"어떤 문제를 보고 이 주제를 골랐는지","mis":"K6-1-u6-X44"},{"t":"어떤 표현 요소로 무엇을 강조했는지","mis":"K6-1-u6-X44"},{"t":"일부러 세게 쓴 곳과 그 까닭","mis":"K6-1-u6-X42"}],"explanation":["밝혀야 할 거예요.","이것도 밝혀요.","발표는 견주어 이기는 일이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#2','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C48',2,'mc','auto','「목표를 (　) 끝까지 노력했다.」의 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":2,"concept":"K6-1-u6-C48","difficulty":2,"kind":"mc","stem":"「목표를 (　) 끝까지 노력했다.」의 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"좇아","correct":true},{"t":"쫓아","mis":"K6-1-u6-X47"},{"t":"맞혀","mis":"K6-1-u6-X47"},{"t":"늘여","mis":"K6-1-u6-X47"}],"explanation":["몰아내거나 급히 따라가는 뜻이에요.","답을 대는 뜻이에요.","목표를 따르는 것은 「좇다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#3','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C42',3,'mc','auto','부풀린 말을 덜어 낸 광고가 오히려 오래 남는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X40','K6-1-u6-X41']::text[],false,'{"seq":3,"concept":"K6-1-u6-C42","difficulty":3,"kind":"mc","stem":"부풀린 말을 덜어 낸 광고가 오히려 오래 남는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"보는 사람이 겪은 일에 가까워 믿고 받아들이기 쉽기 때문이다","correct":true},{"t":"덜어 내면 힘이 약해지기 때문이다","mis":"K6-1-u6-X40"},{"t":"글이 짧아져 아무도 읽지 않기 때문이다","mis":"K6-1-u6-X40"},{"t":"눈에 띄지 않아도 되기 때문이다","mis":"K6-1-u6-X41"}],"explanation":["힘은 그대로예요.","짧아도 남아요.","사실에 가까운 말이 오래 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#4','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C43',3,'mc','auto','눈에 띄게 하려고 일부러 세게 쓴 곳이 있을 때 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X42','K6-1-u6-X41']::text[],false,'{"seq":4,"concept":"K6-1-u6-C43","difficulty":3,"kind":"mc","stem":"눈에 띄게 하려고 일부러 세게 쓴 곳이 있을 때 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"발표할 때 그렇게 한 까닭을 밝힌다","correct":true},{"t":"아무 말 없이 그대로 둔다","mis":"K6-1-u6-X42"},{"t":"눈에 띄지 않게 모두 지운다","mis":"K6-1-u6-X41"},{"t":"더 크게 부풀린다","mis":"K6-1-u6-X42"}],"explanation":["숨기면 속이는 셈이에요.","눈에 띄는 것도 필요해요.","스스로 밝히면 속이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#5','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C49',3,'mc','auto','맞춤법이 헷갈릴 때 가리는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":5,"concept":"K6-1-u6-C49","difficulty":3,"kind":"mc","stem":"맞춤법이 헷갈릴 때 가리는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"본디 말로 늘여 소리 내어 본다(되어요 · 오래간만에)","correct":true},{"t":"소리 나는 대로 쓴다","mis":"K6-1-u6-X48"},{"t":"짧은 쪽을 고른다","mis":"K6-1-u6-X48"},{"t":"아무 쪽이나 쓴다","mis":"K6-1-u6-X48"}],"explanation":["소리대로 쓰면 틀리기 쉬워요.","짧다고 맞지 않아요.","본디 말로 늘이면 가려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#6','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C41',3,'mc','auto','「청소 시간에 맡은 곳만 하고 남은 것을 지나친다」가 공익 광고 주제로 알맞은 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X39','K6-1-u6-X42']::text[],false,'{"seq":6,"concept":"K6-1-u6-C41","difficulty":3,"kind":"mc","stem":"「청소 시간에 맡은 곳만 하고 남은 것을 지나친다」가 공익 광고 주제로 알맞은 까닭은 어느 것인가요?","options":[{"t":"여럿이 함께 겪고, 고치면 나아지는 일이기 때문이다","correct":true},{"t":"나 혼자만 겪는 일이기 때문이다","mis":"K6-1-u6-X39"},{"t":"고쳐도 달라지지 않는 일이기 때문이다","mis":"K6-1-u6-X39"},{"t":"눈에 띄는 그림을 그릴 수 있기 때문이다","mis":"K6-1-u6-X42"}],"explanation":["여럿이 겪어요.","고치면 나아져요.","그림보다 주제의 가치가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#7','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C46',3,'mc','auto','판단이 「결과와 근거가 한 짝」이어야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X45']::text[],false,'{"seq":7,"concept":"K6-1-u6-C46","difficulty":3,"kind":"mc","stem":"판단이 「결과와 근거가 한 짝」이어야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거 없는 판단은 기분일 뿐이라 친구가 무엇을 어떻게 고칠지 알 수 없기 때문이다","correct":true},{"t":"판단은 짧을수록 좋기 때문이다","mis":"K6-1-u6-X06"},{"t":"친구를 이기려면 근거가 필요하기 때문이다","mis":"K6-1-u6-X45"},{"t":"근거는 속으로만 생각해도 되기 때문이다","mis":"K6-1-u6-X06"}],"explanation":["짧으면 까닭이 빠져요.","이기려는 게 아니에요.","말해야 고칠 곳을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#8','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C47',4,'mc','auto','「그늘막을 더 세웁시다」를 두 자로 잰 결과로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X46']::text[],false,'{"seq":8,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"「그늘막을 더 세웁시다」를 두 자로 잰 결과로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 문단 ②·③, 직접 센 근거는 받아들이고, 문단 ④(어긋난 이유)와 ⑤(과장 · 거짓)는 까닭을 대어 짚는다","correct":true},{"t":"걸린 곳이 셋이니 주장까지 버린다","mis":"K6-1-u6-X21"},{"t":"내용은 타당하니 표현은 볼 필요가 없다","mis":"K6-1-u6-X46"},{"t":"표현만 고치면 이유는 볼 필요가 없다","mis":"K6-1-u6-X46"}],"explanation":["주장까지 버리지 않아요.","표현도 재요.","받아들일 것과 물릴 것을 갈랐어요 — ⑤문단은 「볕을 가려 조금 덜 덥다」로 바로잡아요."],"asset":{"type":"passage","lines":["① 신호를 기다리는 동안 볕을 피할 곳이 없습니다.","학교 앞 건널목에 그늘막을 더 세웠으면 좋겠습니다.","② 첫째, 볕을 가려 주면 기다리는 동안 덜 지칩니다. 지난 여름 우리 반에서 세어 보니","아침마다 건널목 앞에 스무 명 남짓이 함께 서 있었습니다.","③ 둘째, 그늘막은 색이 밝아 멀리서도 눈에 띕니다.","차를 모는 사람이 건널목을 일찍 알아볼 수 있습니다."],"title":"「그늘막을 더 세웁시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#9','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C42',4,'essay','teacher','첫 번째 초안의 ㄱ~ㄷ 가운데 두 문구를 골라 무엇이 걸리는지 쓰고, 뜻은 살리면서 알맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u6-C42","difficulty":4,"kind":"essay","stem":"첫 번째 초안의 ㄱ~ㄷ 가운데 두 문구를 골라 무엇이 걸리는지 쓰고, 뜻은 살리면서 알맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: ㄱ 「빌려주면 백 퍼센트 망가집니다!」는 늘 그렇게 되지는 않으니 부풀린 과장이다. 고쳐 쓰면 「빌려준 지우개가 반으로 돌아왔습니다.」 ㄴ 「이 광고 하나면 우리 반 문제가 모두 사라집니다.」는 광고 하나로 모든 문제가 사라지지 않으니 과장이다. 고쳐 쓰면 「한 사람이 지키면 한 사람이 웃습니다.」","scoring_points":["두 문구를 골랐는가","무엇이 걸리는지 까닭을 썼는가","뜻을 살려 알맞게 고쳐 썼는가"]},"explanation":["부풀린 말을 찾아요.","실제로 늘 그런지 물어요.","크기만 줄여 고쳐요. (바로잡기: 광고 하나로 문제가 다 사라지지 않아요.)"],"asset":{"type":"passage","lines":["장면 — 반으로 갈라진 지우개 옆에 빈 필통이 열려 있는 그림","ㄱ. 빌려주면 백 퍼센트 망가집니다!","ㄴ. 이 광고 하나면 우리 반 문제가 모두 사라집니다.","ㄷ. 빌린 물건, 절대 그냥 돌려주지 마세요.","ㄹ. 빌린 그대로 — 그것이 다음에도 빌릴 수 있는 길"],"title":"공익 광고 첫 번째 초안 「빌린 물건은 빌린 그대로」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_L12_challenge#10','kor',6,1,'u6','L12','g6_1_kor_u6_L12_challenge','lesson_challenge','K6-1-u6-C43',4,'essay','teacher','광고를 만들 때 「틀린 말만 없으면 되지」와 「눈에 띄기만 하면 되지」 사이에서 어떻게 할지 쓰고, 내가 만들 광고의 크게 쓸 한 줄과 발표 때 밝힐 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u6-C43","difficulty":4,"kind":"essay","stem":"광고를 만들 때 「틀린 말만 없으면 되지」와 「눈에 띄기만 하면 되지」 사이에서 어떻게 할지 쓰고, 내가 만들 광고의 크게 쓸 한 줄과 발표 때 밝힐 말을 쓰세요.","answer_guide":{"answer":"예: 틀린 말만 없으면 아무도 보지 않고, 눈에 띄기만 하면 믿을 수 없다. 그래서 사실에 가까운 말로 쓰되 가장 하고 싶은 한 줄만 크게 하겠다. 크게 쓸 한 줄 — 「돌려줄 때 한 번만 살펴 주세요」. 발표 때 — 「빌린 물건이 망가져 돌아온 일을 보고 주제를 골랐고, 반으로 갈라진 지우개 그림을 크게 그려 문제를 보여 주었습니다. 그림을 일부러 크게 그린 까닭은 한눈에 문제를 보여 주고 싶어서입니다.」","scoring_points":["두 쪽 사이에서 어떻게 할지 썼는가","크게 쓸 한 줄을 알맞게 썼는가","발표 때 고른 까닭과 강조한 것을 밝혔는가"]},"explanation":["양쪽을 다 막아요.","한 줄만 크게 해요.","손댄 곳의 까닭을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#1','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C1',1,'mc','auto','글을 그대로 받아들이지 않고 내용과 표현이 알맞은지 판단하며 읽는 것을 무엇이라고 하나요?',ARRAY['K6-1-u6-X01','K6-1-u6-X03']::text[],false,'{"seq":1,"concept":"K6-1-u6-C1","difficulty":1,"kind":"mc","stem":"글을 그대로 받아들이지 않고 내용과 표현이 알맞은지 판단하며 읽는 것을 무엇이라고 하나요?","options":[{"t":"비판적으로 읽기","correct":true},{"t":"훑어 읽기","mis":"K6-1-u6-X01"},{"t":"소리 내어 읽기","mis":"K6-1-u6-X03"},{"t":"외우며 읽기","mis":"K6-1-u6-X01"}],"explanation":["빠르게 보는 읽기예요.","읽는 방법이 달라요.","판단하며 읽는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#2','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C8',1,'mc','auto','내용의 타당성을 재는 세 물음이 차례로 재는 것은 무엇인가요?',ARRAY['K6-1-u6-X08','K6-1-u6-X07','K6-1-u6-X03']::text[],false,'{"seq":2,"concept":"K6-1-u6-C8","difficulty":1,"kind":"mc","stem":"내용의 타당성을 재는 세 물음이 차례로 재는 것은 무엇인가요?","options":[{"t":"주장 · 이유 · 근거","correct":true},{"t":"제목 · 그림 · 글씨","mis":"K6-1-u6-X08"},{"t":"서론 · 본론 · 결론","mis":"K6-1-u6-X07"},{"t":"거짓 · 과장 · 감춤","mis":"K6-1-u6-X03"}],"explanation":["겉모습을 재지 않아요.","짜임이 아니에요.","그건 표현의 적절성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#3','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C7',1,'mc','auto','주장하는 글에서 주장을 찾을 때 함께 보면 좋은 두 부분은 어디인가요?',ARRAY['K6-1-u6-X07']::text[],false,'{"seq":3,"concept":"K6-1-u6-C7","difficulty":1,"kind":"mc","stem":"주장하는 글에서 주장을 찾을 때 함께 보면 좋은 두 부분은 어디인가요?","options":[{"t":"서론과 결론","correct":true},{"t":"본론의 첫째 이유와 둘째 이유","mis":"K6-1-u6-X07"},{"t":"제목과 그림","mis":"K6-1-u6-X07"},{"t":"근거와 출처","mis":"K6-1-u6-X07"}],"explanation":["이유는 주장을 받쳐요.","그림만으로는 몰라요.","서론과 결론이 함께 가리켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#4','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C25',1,'mc','auto','없는 것을 있는 것처럼 말한 표현을 무엇이라고 하나요?',ARRAY['K6-1-u6-X25','K6-1-u6-X26']::text[],false,'{"seq":4,"concept":"K6-1-u6-C25","difficulty":1,"kind":"mc","stem":"없는 것을 있는 것처럼 말한 표현을 무엇이라고 하나요?","options":[{"t":"거짓된 표현","correct":true},{"t":"과장된 표현","mis":"K6-1-u6-X25"},{"t":"감추는 내용","mis":"K6-1-u6-X25"},{"t":"알맞은 표현","mis":"K6-1-u6-X26"}],"explanation":["과장은 있는 것을 부풀려요.","감춤은 빼놓는 거예요.","없는 걸 있다고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#5','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C24',1,'mc','auto','광고를 볼 때 큰 글씨와 함께 꼭 살펴야 할 것은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X23']::text[],false,'{"seq":5,"concept":"K6-1-u6-C24","difficulty":1,"kind":"mc","stem":"광고를 볼 때 큰 글씨와 함께 꼭 살펴야 할 것은 어느 것인가요?","options":[{"t":"작게 적은 글씨","correct":true},{"t":"광고의 테두리 색","mis":"K6-1-u6-X24"},{"t":"광고를 붙인 높이","mis":"K6-1-u6-X24"},{"t":"광고에 쓰인 글자 수","mis":"K6-1-u6-X23"}],"explanation":["테두리가 아니에요.","높이와 관계없어요.","작게 쓴 데 조건이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#6','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C32',1,'mc','auto','설명하는 글의 거짓된 표현이 읽는 사람에게 남기는 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X31']::text[],false,'{"seq":6,"concept":"K6-1-u6-C32","difficulty":1,"kind":"mc","stem":"설명하는 글의 거짓된 표현이 읽는 사람에게 남기는 것은 어느 것인가요?","options":[{"t":"잘못된 지식","correct":true},{"t":"지나친 믿음","mis":"K6-1-u6-X25"},{"t":"한쪽만 아는 생각","mis":"K6-1-u6-X25"},{"t":"아무것도 남지 않는다","mis":"K6-1-u6-X31"}],"explanation":["과장이 남기는 거예요.","감춤이 남기는 거예요.","거짓은 잘못된 지식이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#7','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C41',1,'mc','auto','공익 광고의 주제로 고를 일은 어느 것인가요?',ARRAY['K6-1-u6-X39','K6-1-u6-X42']::text[],false,'{"seq":7,"concept":"K6-1-u6-C41","difficulty":1,"kind":"mc","stem":"공익 광고의 주제로 고를 일은 어느 것인가요?","options":[{"t":"여럿이 함께 겪고 고치면 나아지는 일","correct":true},{"t":"나 혼자만 겪는 일","mis":"K6-1-u6-X39"},{"t":"고쳐도 달라지지 않는 일","mis":"K6-1-u6-X39"},{"t":"눈에 띄는 그림을 그리기 쉬운 일","mis":"K6-1-u6-X42"}],"explanation":["여럿이 겪어야 해요.","나아질 수 있어야 해요.","주제의 가치가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#8','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C48',1,'mc','auto','「바지 길이를 길게 (　)」의 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":8,"concept":"K6-1-u6-C48","difficulty":1,"kind":"mc","stem":"「바지 길이를 길게 (　)」의 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"늘였다","correct":true},{"t":"늘렸다","mis":"K6-1-u6-X47"},{"t":"맞혔다","mis":"K6-1-u6-X47"},{"t":"쫓았다","mis":"K6-1-u6-X47"}],"explanation":["수나 양을 많게 할 때 써요.","답을 대는 뜻이에요.","길게 하면 「늘이다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#9','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C7',2,'mc','auto','담희 글의 주장은 무엇인가요?',ARRAY['K6-1-u6-X11','K6-1-u6-X07']::text[],false,'{"seq":9,"concept":"K6-1-u6-C7","difficulty":2,"kind":"mc","stem":"담희 글의 주장은 무엇인가요?","options":[{"t":"쉬는 시간마다 창문을 열어 두자","correct":true},{"t":"창문을 닫아 두자","mis":"K6-1-u6-X11"},{"t":"감기에 걸리지 않게 하자","mis":"K6-1-u6-X07"},{"t":"셋째 시간을 줄이자","mis":"K6-1-u6-X07"}],"explanation":["주장과 반대예요.","이유에 나온 말이에요.","서론과 결론이 함께 가리켜요. (바로잡기: 창문을 열어도 감기에 걸릴 수 있어요.) (바로잡기: 창문을 열어도 해결 안 되는 문제가 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#10','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C12',2,'mc','auto','담희 글에서 근거로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X26','K6-1-u6-X16']::text[],false,'{"seq":10,"concept":"K6-1-u6-C12","difficulty":2,"kind":"mc","stem":"담희 글에서 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"일주일 동안 창문을 열어 보니 「답답하다」고 적은 친구가 날마다 줄었다","correct":true},{"t":"옆 반 친구가 감기에 안 걸린다고 말해 주었다","mis":"K6-1-u6-X19"},{"t":"창문만 열면 모든 문제가 사라진다","mis":"K6-1-u6-X26"},{"t":"추운 날에는 잠깐만 열어도 된다","mis":"K6-1-u6-X16"}],"explanation":["전해 들은 말이에요.","부풀린 말이에요.","직접 해 보고 적은 기록이에요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#11','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C25',2,'mc','auto','형광펜 광고에서 거짓된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X25']::text[],false,'{"seq":11,"concept":"K6-1-u6-C25","difficulty":2,"kind":"mc","stem":"형광펜 광고에서 거짓된 표현은 어느 것인가요?","options":[{"t":"공부가 저절로 되는 형광펜!","correct":true},{"t":"다섯 가지 색이 한 묶음","mis":"K6-1-u6-X05"},{"t":"뚜껑을 닫아 두면 잘 마르지 않아요","mis":"K6-1-u6-X05"},{"t":"영원히 마르지 않는 잉크!","mis":"K6-1-u6-X25"}],"explanation":["사실을 밝힌 말이에요.","실제로 있는 기능이에요.","형광펜에는 공부를 대신해 주는 기능이 없어요 — 거짓이에요. (바로잡기: 뚜껑을 열어 두면 잉크는 마를 수 있어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#12','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C27',2,'mc','auto','형광펜 광고에서 감추는 내용이 있는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X24']::text[],false,'{"seq":12,"concept":"K6-1-u6-C27","difficulty":2,"kind":"mc","stem":"형광펜 광고에서 감추는 내용이 있는 문구는 어느 것인가요?","options":[{"t":"가장 많이 팔린 형광펜!","correct":true},{"t":"다섯 가지 색이 한 묶음","mis":"K6-1-u6-X05"},{"t":"뚜껑을 닫아 두면 잘 마르지 않아요","mis":"K6-1-u6-X05"},{"t":"※ 뚜껑을 열어 두면 금방 마를 수 있음","mis":"K6-1-u6-X24"}],"explanation":["밝힌 말이에요.","되묻고 싶은 게 없어요.","언제 · 어디에서 · 무엇과 견주었는지 빠졌어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#13','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C34',2,'mc','auto','갯벌 글에서 거짓된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X25']::text[],false,'{"seq":13,"concept":"K6-1-u6-C34","difficulty":2,"kind":"mc","stem":"갯벌 글에서 거짓된 표현은 어느 것인가요?","options":[{"t":"요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다","correct":true},{"t":"바닷물은 하루에 두 번쯤 들어왔다가 빠져나갑니다","mis":"K6-1-u6-X05"},{"t":"갯벌에는 게, 조개, 갯지렁이가 삽니다","mis":"K6-1-u6-X05"},{"t":"갯벌은 언제든 걸어 들어가 놀아도 좋습니다","mis":"K6-1-u6-X25"}],"explanation":["사실이에요.","사실이에요.","모래 바닷가 · 바위 바닷가도 있어요 — 바르게는 「우리나라 바닷가 가운데에는 갯벌이 넓게 펼쳐진 곳이 있습니다」예요. (바로잡기: 갯벌 생물도 지나치게 잡으면 줄어들어요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#14','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C33',2,'mc','auto','갯벌 글에 세 기준을 대는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X32']::text[],false,'{"seq":14,"concept":"K6-1-u6-C33","difficulty":2,"kind":"mc","stem":"갯벌 글에 세 기준을 대는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"거짓을 들고 문단 ①~⑥을 훑고, 다시 과장을, 마지막으로 감춤을 들고 처음부터 훑는다","correct":true},{"t":"문단 ④에서만 세 기준을 한꺼번에 잰다","mis":"K6-1-u6-X32"},{"t":"제목만 보고 판단한다","mis":"K6-1-u6-X32"},{"t":"좋아 보이는 문단은 건너뛴다","mis":"K6-1-u6-X32"}],"explanation":["한 문단만 보면 놓쳐요.","글 전체를 훑어요.","기준 하나로 전체를 훑어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#15','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C42',2,'mc','auto','도율이의 초안에서 고치지 않아도 되는 문구는 어느 것인가요?',ARRAY['K6-1-u6-X26']::text[],false,'{"seq":15,"concept":"K6-1-u6-C42","difficulty":2,"kind":"mc","stem":"도율이의 초안에서 고치지 않아도 되는 문구는 어느 것인가요?","options":[{"t":"ㄹ. 잠가요, 비누칠하는 동안","correct":true},{"t":"ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","mis":"K6-1-u6-X26"},{"t":"ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","mis":"K6-1-u6-X26"},{"t":"ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","mis":"K6-1-u6-X26"}],"explanation":["사실이 아니에요 — 지구의 물이 하루 만에 마르지 않아요.","부풀렸어요.","뜻이 분명하고 부풀리지 않았어요 — ㄷ도 없는 벌금 규칙을 있다고 한 거짓이에요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#16','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C21',2,'mc','auto','도율이의 첫 말 「이 글은 다 버리는 게 낫겠다」에 대한 판단으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X01','K6-1-u6-X05']::text[],false,'{"seq":16,"concept":"K6-1-u6-C21","difficulty":2,"kind":"mc","stem":"도율이의 첫 말 「이 글은 다 버리는 게 낫겠다」에 대한 판단으로 알맞은 것은 어느 것인가요?","options":[{"t":"걸린 곳만 짚고 주장과 직접 센 기록은 받아들여야 한다","correct":true},{"t":"걸린 곳이 셋이니 버리는 게 맞다","mis":"K6-1-u6-X21"},{"t":"걸린 곳이 있어도 모두 받아들여야 한다","mis":"K6-1-u6-X01"},{"t":"더 많은 흠을 찾아야 한다","mis":"K6-1-u6-X05"}],"explanation":["쓸 것까지 버려요.","걸린 곳은 짚어요.","받아들일 것과 물릴 것을 나눠요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#17','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C20',3,'mc','auto','담희 글을 차례대로 잰 결과로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X10','K6-1-u6-X19']::text[],false,'{"seq":17,"concept":"K6-1-u6-C20","difficulty":3,"kind":"mc","stem":"담희 글을 차례대로 잰 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"주장은 가치 있음 → 이유 ③은 어긋나고 ④는 사실이 아님 → 근거 ④는 전해 들은 말이라 걸림","correct":true},{"t":"근거가 하나 걸렸으니 주장도 가치 없음","mis":"K6-1-u6-X21"},{"t":"이유 ③은 맞는 말이니 뒷받침함","mis":"K6-1-u6-X10"},{"t":"전해 들은 말도 누가 말했는지 있으니 알맞음","mis":"K6-1-u6-X19"}],"explanation":["주장의 가치는 따로 재요.","맞는 말이어도 어긋나요.","주장 → 이유 → 근거 차례로 쟀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#18','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C37',3,'mc','auto','「공부가 저절로 되는 형광펜!」을 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X26']::text[],false,'{"seq":18,"concept":"K6-1-u6-C37","difficulty":3,"kind":"mc","stem":"「공부가 저절로 되는 형광펜!」을 알맞게 고친 것은 어느 것인가요?","options":[{"t":"중요한 곳을 눈에 띄게 표시해 주는 형광펜","correct":true},{"t":"공부가 정말 저절로 되는 형광펜","mis":"K6-1-u6-X35"},{"t":"세상 모든 공부를 대신하는 형광펜","mis":"K6-1-u6-X26"},{"t":"형광펜을 쓰지 맙시다","mis":"K6-1-u6-X35"}],"explanation":["거짓을 그대로 두었어요.","더 부풀렸어요.","형광펜이 실제로 하는 일만 말했어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#19','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C37',3,'mc','auto','「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」를 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X33']::text[],false,'{"seq":19,"concept":"K6-1-u6-C37","difficulty":3,"kind":"mc","stem":"「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」를 알맞게 고친 것은 어느 것인가요?","options":[{"t":"갯벌에 들어갈 때에는 바닷물이 들어오는 때를 확인하고 어른과 함께 가야 합니다","correct":true},{"t":"갯벌은 언제든 정말 놀아도 좋습니다","mis":"K6-1-u6-X35"},{"t":"갯벌에는 절대 들어가지 맙시다","mis":"K6-1-u6-X35"},{"t":"갯벌은 언제나 안전합니다","mis":"K6-1-u6-X33"}],"explanation":["감춘 것을 밝히지 않았어요.","뜻까지 바꿨어요.","알아야 할 것을 밝혔어요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#20','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C42',3,'mc','auto','「이 광고만 보면 물 낭비가 모두 사라집니다」를 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X26']::text[],false,'{"seq":20,"concept":"K6-1-u6-C42","difficulty":3,"kind":"mc","stem":"「이 광고만 보면 물 낭비가 모두 사라집니다」를 알맞게 고친 것은 어느 것인가요?","options":[{"t":"한 사람이 잠그면 한 컵만큼 물이 남습니다","correct":true},{"t":"이 광고만 보면 물 낭비가 정말 다 사라집니다","mis":"K6-1-u6-X35"},{"t":"물 낭비는 영원히 사라집니다","mis":"K6-1-u6-X26"},{"t":"물을 아예 쓰지 맙시다","mis":"K6-1-u6-X35"}],"explanation":["부풀린 그대로예요.","더 부풀렸어요.","뜻은 살리고 크기만 줄였어요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#21','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',3,'mc','auto','「그늘막을 더 세웁시다」에 두 자를 모두 댄 판단은 어느 것인가요?',ARRAY['K6-1-u6-X46','K6-1-u6-X21']::text[],false,'{"seq":21,"concept":"K6-1-u6-C47","difficulty":3,"kind":"mc","stem":"「그늘막을 더 세웁시다」에 두 자를 모두 댄 판단은 어느 것인가요?","options":[{"t":"내용: 문단 ④가 주장과 어긋남 · 표현: 문단 ⑤가 과장과 거짓","correct":true},{"t":"내용: 문단 ④가 어긋남 — 표현은 보지 않음","mis":"K6-1-u6-X46"},{"t":"표현: 문단 ⑤가 과장 — 내용은 보지 않음","mis":"K6-1-u6-X46"},{"t":"걸린 곳이 있으니 모두 버림","mis":"K6-1-u6-X21"}],"explanation":["표현도 봐야 해요.","내용도 봐야 해요.","여섯 물음을 다 댔어요 — ⑤는 「볕을 가려 조금 덜 덥다」로 바로잡아요. (바로잡기: 그늘막 아래도 더울 수 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 그늘막 아래에서는 친구들과 이야기를 나눌 수 있어 즐겁습니다.","⑤ 그늘막 하나면 여름 더위가 모두 사라집니다. 그늘막 아래에서는 절대 덥지 않습니다.","⑥ 그늘막은 세우는 데 오래 걸리지 않습니다.","여름이 오기 전에 건널목 앞에 그늘막을 더 세웁시다."],"title":"「그늘막을 더 세웁시다」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#22','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C48',3,'mc','auto','낱말을 바르게 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":22,"concept":"K6-1-u6-C48","difficulty":3,"kind":"mc","stem":"낱말을 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"고양이가 마당의 참새를 쫓았다.","correct":true},{"t":"꿈을 쫓아 열심히 공부했다.","mis":"K6-1-u6-X47"},{"t":"수수께끼의 답을 맞추었다.","mis":"K6-1-u6-X47"},{"t":"모둠 수를 하나 늘였다.","mis":"K6-1-u6-X47"}],"explanation":["목표를 따르면 「좇다」예요.","답을 옳게 대면 「맞히다」예요.","수를 많게 하면 「늘리다」예요 — 몰아내거나 뒤를 따르면 「쫓다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#23','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',4,'mc','auto','담희 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X21','K6-1-u6-X01','K6-1-u6-X46']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"담희 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"주장과 문단 ②의 이유 · 기록은 받아들일 만하지만, 어긋난 이유 ③ · 사실이 아닌 이유와 전해 들은 근거 ④ · 과장 ⑤를 고쳐야 한다","correct":true},{"t":"걸린 곳이 많으니 버리고 새로 써야 한다","mis":"K6-1-u6-X21"},{"t":"주장이 좋으니 고칠 곳이 없다","mis":"K6-1-u6-X01"},{"t":"표현만 고치면 된다","mis":"K6-1-u6-X46"}],"explanation":["버리지 않고 고쳐요.","걸린 곳이 있어요.","내용도 걸린 곳이 있어요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#24','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C18',4,'essay','teacher','담희 글에서 내용이 걸리는 곳 두 군데를 찾아 까닭을 쓰고, 그중 하나를 주장 편에 서도록 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C18","difficulty":4,"kind":"essay","stem":"담희 글에서 내용이 걸리는 곳 두 군데를 찾아 까닭을 쓰고, 그중 하나를 주장 편에 서도록 고쳐 쓰세요.","answer_guide":{"answer":"예: 문단 ③ 「창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있다」는 닫자는 쪽을 가리켜 열어 두자는 주장과 어긋난다. 문단 ④ 「창문을 열어 두면 감기에 걸리지 않는다」는 사실이 아니고, 옆 반 친구의 말은 전해 들은 말이라 확인할 수 없다. 문단 ③을 고치면 — 「둘째, 바깥 공기를 들이면 머리가 맑아진 느낌이 들어 다음 시간을 더 상쾌하게 시작할 수 있습니다.」","scoring_points":["걸리는 곳 두 군데를 찾았는가","각각 까닭을 썼는가","하나를 주장 편으로 고쳐 썼는가"]},"explanation":["세 기준을 차례로 대요.","까닭을 붙여요.","같은 문제를 주장 쪽으로 이어요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_a#25','kor',6,1,'u6','','g6_1_kor_u6_review_a','unit_review','K6-1-u6-C47',4,'essay','teacher','이 단원이 남긴 여섯 물음을 쓰고, 그 물음을 쓸 때 꼭 함께 해야 할 일 한 가지를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C47","difficulty":4,"kind":"essay","stem":"이 단원이 남긴 여섯 물음을 쓰고, 그 물음을 쓸 때 꼭 함께 해야 할 일 한 가지를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 내용의 타당성 — 주장은 가치 있고 중요한가, 이유는 주장을 뒷받침하는가, 근거는 이유를 뒷받침하는가. 표현의 적절성 — 거짓된 표현이 있는가, 과장된 표현이 있는가, 감추는 내용이 있는가. 이 물음을 쓸 때에는 그렇게 판단한 까닭을 함께 대야 한다. 까닭 없는 판단은 기분일 뿐이라 다른 사람이 따져 볼 수 없기 때문이다.","scoring_points":["내용의 타당성 세 물음을 썼는가","표현의 적절성 세 물음을 썼는가","까닭을 함께 대야 함을 썼는가"]},"explanation":["두 자를 떠올려요.","여섯 물음을 써요.","까닭과 이어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#1','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C3',1,'mc','auto','판단하며 읽기의 두 갈래로 알맞게 묶은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X03','K6-1-u6-X07']::text[],false,'{"seq":1,"concept":"K6-1-u6-C3","difficulty":1,"kind":"mc","stem":"판단하며 읽기의 두 갈래로 알맞게 묶은 것은 어느 것인가요?","options":[{"t":"내용의 타당성 · 표현의 적절성","correct":true},{"t":"글의 길이 · 글씨의 크기","mis":"K6-1-u6-X23"},{"t":"제목 · 그림","mis":"K6-1-u6-X03"},{"t":"서론 · 결론","mis":"K6-1-u6-X07"}],"explanation":["길이와 크기는 갈래가 아니에요.","제목과 그림만이 아니에요.","무엇을 · 어떻게 말하는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#2','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C12',1,'mc','auto','근거가 갖추어야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X12','K6-1-u6-X07','K6-1-u6-X19']::text[],false,'{"seq":2,"concept":"K6-1-u6-C12","difficulty":1,"kind":"mc","stem":"근거가 갖추어야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"이유와 관련이 있고 객관적인 사실이나 정보를 활용한다","correct":true},{"t":"글쓴이의 짐작을 담는다","mis":"K6-1-u6-X12"},{"t":"주장을 한 번 더 말한다","mis":"K6-1-u6-X07"},{"t":"전해 들은 말을 옮긴다","mis":"K6-1-u6-X19"}],"explanation":["짐작은 근거가 못 돼요.","주장을 되풀이하는 건 근거가 아니에요.","확인할 수 있는 사실이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#3','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C13',1,'ox','auto','알림글이나 설명하는 글에도 타당성을 물어볼 수 있어요.',ARRAY['K6-1-u6-X13']::text[],false,'{"seq":3,"concept":"K6-1-u6-C13","difficulty":1,"kind":"ox","stem":"알림글이나 설명하는 글에도 타당성을 물어볼 수 있어요.","answer":"O","reason_options":[{"t":"내용을 담은 글이면 어디에든 같은 물음을 댈 수 있기 때문에","correct":true},{"t":"주장하는 글에서만 잴 수 있기 때문에","mis":"K6-1-u6-X13"}],"mis":"K6-1-u6-X13","explanation":["주장하는 글만이 아니에요.","내용을 담은 글이면 돼요.","어디에나 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#4','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C26',1,'mc','auto','있는 것을 실제보다 부풀린 표현을 무엇이라고 하나요?',ARRAY['K6-1-u6-X25','K6-1-u6-X27','K6-1-u6-X34']::text[],false,'{"seq":4,"concept":"K6-1-u6-C26","difficulty":1,"kind":"mc","stem":"있는 것을 실제보다 부풀린 표현을 무엇이라고 하나요?","options":[{"t":"과장된 표현","correct":true},{"t":"거짓된 표현","mis":"K6-1-u6-X25"},{"t":"감추는 내용","mis":"K6-1-u6-X27"},{"t":"알맞은 표현","mis":"K6-1-u6-X34"}],"explanation":["기능이 있으면 거짓이 아니에요.","감춤과 달라요.","부풀리면 과장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#5','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C28',1,'mc','auto','거짓과 과장을 가르는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X25','K6-1-u6-X23']::text[],false,'{"seq":5,"concept":"K6-1-u6-C28","difficulty":1,"kind":"mc","stem":"거짓과 과장을 가르는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「그 기능이 실제로 있는가?」","correct":true},{"t":"「글씨가 큰가?」","mis":"K6-1-u6-X24"},{"t":"「값이 싼가?」","mis":"K6-1-u6-X25"},{"t":"「그림이 예쁜가?」","mis":"K6-1-u6-X23"}],"explanation":["크기로 가르지 않아요.","값과 관계없어요.","기능이 있는지로 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#6','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C34',1,'mc','auto','설명하는 글에서 「대부분 · 모두 · 언제나」가 나오면 할 일은 어느 것인가요?',ARRAY['K6-1-u6-X33','K6-1-u6-X26','K6-1-u6-X31']::text[],false,'{"seq":6,"concept":"K6-1-u6-C34","difficulty":1,"kind":"mc","stem":"설명하는 글에서 「대부분 · 모두 · 언제나」가 나오면 할 일은 어느 것인가요?","options":[{"t":"그렇게 넓게 말할 만한 사실인지 멈추어 묻는다","correct":true},{"t":"그냥 지나친다","mis":"K6-1-u6-X33"},{"t":"더 넓게 「세상 모든」으로 바꾼다","mis":"K6-1-u6-X26"},{"t":"그 문장을 외운다","mis":"K6-1-u6-X31"}],"explanation":["멈춰 봐요.","더 부풀리면 안 돼요.","넓게 말할 만한지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#7','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C44',1,'mc','auto','광고에서 크게 쓸 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X43']::text[],false,'{"seq":7,"concept":"K6-1-u6-C44","difficulty":1,"kind":"mc","stem":"광고에서 크게 쓸 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"가장 하고 싶은 한 줄","correct":true},{"t":"모든 줄","mis":"K6-1-u6-X43"},{"t":"꼭 알려야 할 조건만 아주 작게","mis":"K6-1-u6-X43"},{"t":"아무 줄이나","mis":"K6-1-u6-X43"}],"explanation":["다 크면 아무것도 크지 않아요.","조건은 읽을 수 있게 적어요.","한 줄만 크게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#8','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C48',1,'mc','auto','「퍼즐 조각을 서로 (　) 보았다」의 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K6-1-u6-X47']::text[],false,'{"seq":8,"concept":"K6-1-u6-C48","difficulty":1,"kind":"mc","stem":"「퍼즐 조각을 서로 (　) 보았다」의 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"맞추어","correct":true},{"t":"맞히어","mis":"K6-1-u6-X47"},{"t":"늘이어","mis":"K6-1-u6-X47"},{"t":"좇아","mis":"K6-1-u6-X47"}],"explanation":["답을 옳게 대는 뜻이에요.","길게 하는 뜻이에요.","서로 대어 보면 「맞추다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#9','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C11',2,'mc','auto','담희 글에서 주장과 어긋나는 이유는 어느 것인가요?',ARRAY['K6-1-u6-X05','K6-1-u6-X07']::text[],false,'{"seq":9,"concept":"K6-1-u6-C11","difficulty":2,"kind":"mc","stem":"담희 글에서 주장과 어긋나는 이유는 어느 것인가요?","options":[{"t":"창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있다","correct":true},{"t":"바깥 공기가 들어와 교실 공기가 바뀐다","mis":"K6-1-u6-X05"},{"t":"셋째 시간이 끝날 무렵 교실 공기가 답답해진다","mis":"K6-1-u6-X07"},{"t":"추운 날에는 잠깐만 열어도 된다","mis":"K6-1-u6-X05"}],"explanation":["주장과 이어지는 이유예요.","문제를 꺼낸 서론이에요.","닫자는 쪽을 가리켜 어긋나요 — 열자는 주장 편으로 고쳐야 해요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#10','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C19',2,'mc','auto','「옆 반 친구가 그렇게 말해 주었습니다」가 근거로 알맞지 않은 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X19','K6-1-u6-X08']::text[],false,'{"seq":10,"concept":"K6-1-u6-C19","difficulty":2,"kind":"mc","stem":"「옆 반 친구가 그렇게 말해 주었습니다」가 근거로 알맞지 않은 까닭은 어느 것인가요?","options":[{"t":"한 사람에게서 전해 들은 말이라 누구도 다시 확인할 수 없기 때문이다","correct":true},{"t":"옆 반 친구는 어리기 때문이다","mis":"K6-1-u6-X19"},{"t":"근거가 너무 길기 때문이다","mis":"K6-1-u6-X08"},{"t":"친구 이름을 밝히지 않았기 때문이다","mis":"K6-1-u6-X19"}],"explanation":["나이 문제가 아니에요.","길이 문제가 아니에요.","이름을 밝혀도 전해 들은 말이에요 — 확인할 수 있는 근거로 바꿔요. (바로잡기: 창문을 열어도 감기에 걸릴 수 있어요.) (바로잡기: 창문을 열어도 해결 안 되는 문제가 있어요.)"],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#11','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C26',2,'mc','auto','「영원히 마르지 않는 잉크!」가 걸리는 기준과 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X25','K6-1-u6-X17','K6-1-u6-X27']::text[],false,'{"seq":11,"concept":"K6-1-u6-C26","difficulty":2,"kind":"mc","stem":"「영원히 마르지 않는 잉크!」가 걸리는 기준과 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"과장 — 잘 마르지 않게 만든 것은 맞지만 어떤 경우에도 그렇다고 부풀렸다","correct":true},{"t":"거짓 — 잉크가 아예 없다","mis":"K6-1-u6-X25"},{"t":"알맞음 — 광고에 적혀 있다","mis":"K6-1-u6-X17"},{"t":"감춤 — 색을 밝히지 않았다","mis":"K6-1-u6-X27"}],"explanation":["기능은 있어요.","적혀 있다는 건 까닭이 아니에요.","있는 기능을 부풀렸어요 — 작은 글씨가 마를 수 있다고 밝혀요. (바로잡기: 형광펜에는 공부를 대신해 주는 기능이 없어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#12','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C24',2,'mc','auto','형광펜 광고가 「※ 뚜껑을 열어 두면 금방 마를 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X15','K6-1-u6-X27','K6-1-u6-X24']::text[],false,'{"seq":12,"concept":"K6-1-u6-C24","difficulty":2,"kind":"mc","stem":"형광펜 광고가 「※ 뚜껑을 열어 두면 금방 마를 수 있음」을 아주 작게 적은 것을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"꼭 알아야 할 조건을 눈에 들어오지 않게 적어, 「영원히 마르지 않는」과 함께 보면 감추는 내용에 가깝다","correct":true},{"t":"작은 글씨는 안 읽어도 된다","mis":"K6-1-u6-X15"},{"t":"적었으니 아무 문제가 없다","mis":"K6-1-u6-X27"},{"t":"실수로 작게 썼을 뿐이다","mis":"K6-1-u6-X24"}],"explanation":["조건이 거기 있어요.","읽을 수 있는 크기여야 해요.","작게 쓴 것도 뜻이 있어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#13','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C35',2,'mc','auto','갯벌 글에서 과장된 표현은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X05']::text[],false,'{"seq":13,"concept":"K6-1-u6-C35","difficulty":2,"kind":"mc","stem":"갯벌 글에서 과장된 표현은 어느 것인가요?","options":[{"t":"갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다","correct":true},{"t":"갯벌은 언제든 걸어 들어가 놀아도 좋습니다","mis":"K6-1-u6-X28"},{"t":"갯벌을 보면 살림터를 알 수 있습니다","mis":"K6-1-u6-X05"},{"t":"갯벌 생물이 바닷물을 깨끗하게 하는 데 도움을 줍니다","mis":"K6-1-u6-X05"}],"explanation":["이건 감추는 내용이에요.","글쓴이의 정리예요.","지나치게 잡으면 줄어들어요 — 바르게는 「알맞게 잡으면 다시 늘어날 수 있습니다」예요. (바로잡기: 우리나라에는 모래 바닷가 · 바위 바닷가도 있어요.) (바로잡기: 바닷물이 들어오는 때에는 갯벌에 들어가면 위험해요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#14','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C38',2,'mc','auto','갯벌 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X36','K6-1-u6-X31']::text[],false,'{"seq":14,"concept":"K6-1-u6-C38","difficulty":2,"kind":"mc","stem":"갯벌 글을 읽고 다른 관점에서 세울 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「갯벌이 줄어들면 어떤 일이 생길까?」","correct":true},{"t":"「갯벌은 왜 이렇게 좋을까?」","mis":"K6-1-u6-X36"},{"t":"「이 글만 읽으면 충분하겠지?」","mis":"K6-1-u6-X36"},{"t":"「이 글을 다 외웠을까?」","mis":"K6-1-u6-X31"}],"explanation":["같은 쪽의 물음이에요.","한 편만 읽고 끝내지 않아요.","다른 쪽에서 물었어요 — 관련 글을 더 찾아 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#15','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C40',2,'mc','auto','도율이가 초안을 스스로 검사할 때 쓸 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X23','K6-1-u6-X42','K6-1-u6-X38']::text[],false,'{"seq":15,"concept":"K6-1-u6-C40","difficulty":2,"kind":"mc","stem":"도율이가 초안을 스스로 검사할 때 쓸 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「없는 것을 있다고 했는가 · 부풀렸는가 · 감추었는가?」","correct":true},{"t":"「글씨가 예쁜가?」","mis":"K6-1-u6-X23"},{"t":"「남의 광고보다 센가?」","mis":"K6-1-u6-X42"},{"t":"「내 광고니까 괜찮은가?」","mis":"K6-1-u6-X38"}],"explanation":["겉모습이 아니에요.","세기를 겨루지 않아요.","읽을 때의 자를 만들 때도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#16','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C6',2,'mc','auto','담희가 도율이에게 「까닭을 말해 줄래?」라고 한 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X45','K6-1-u6-X06','K6-1-u6-X21']::text[],false,'{"seq":16,"concept":"K6-1-u6-C6","difficulty":2,"kind":"mc","stem":"담희가 도율이에게 「까닭을 말해 줄래?」라고 한 까닭은 어느 것인가요?","options":[{"t":"까닭 없는 판단으로는 어디를 어떻게 고칠지 알 수 없기 때문이다","correct":true},{"t":"도율이를 이기고 싶기 때문이다","mis":"K6-1-u6-X45"},{"t":"「별로야」만으로 충분하기 때문이다","mis":"K6-1-u6-X06"},{"t":"⑤문단을 버리고 싶기 때문이다","mis":"K6-1-u6-X21"}],"explanation":["이기려는 게 아니에요.","까닭이 있어야 해요.","판단은 결과와 근거가 한 짝이에요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#17','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C21',3,'mc','auto','담희 글에서 받아들여도 좋은 부분만 모은 것은 어느 것인가요?',ARRAY['K6-1-u6-X11','K6-1-u6-X21','K6-1-u6-X01']::text[],false,'{"seq":17,"concept":"K6-1-u6-C21","difficulty":3,"kind":"mc","stem":"담희 글에서 받아들여도 좋은 부분만 모은 것은 어느 것인가요?","options":[{"t":"창문을 열자는 주장 · 공기가 바뀐다는 이유 · 일주일 동안 적은 기록","correct":true},{"t":"창문을 닫으면 조용하다는 이유 · 옆 반 친구의 말","mis":"K6-1-u6-X11"},{"t":"받아들일 것이 하나도 없다","mis":"K6-1-u6-X21"},{"t":"글의 모든 문장","mis":"K6-1-u6-X01"}],"explanation":["걸린 곳들이에요.","걸린 곳만 짚어요.","걸린 곳을 빼고 골라냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#18','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C27',3,'mc','auto','「가장 많이 팔린 형광펜!」을 감춘 것 없이 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X27','K6-1-u6-X26']::text[],false,'{"seq":18,"concept":"K6-1-u6-C27","difficulty":3,"kind":"mc","stem":"「가장 많이 팔린 형광펜!」을 감춘 것 없이 고친 것은 어느 것인가요?","options":[{"t":"지난달 우리 학교 앞 문구점에서 형광펜 가운데 가장 많이 팔렸어요","correct":true},{"t":"정말 가장 많이 팔린 형광펜!","mis":"K6-1-u6-X27"},{"t":"세상에서 가장 많이 팔린 형광펜!","mis":"K6-1-u6-X26"},{"t":"누구나 아는 그 형광펜!","mis":"K6-1-u6-X27"}],"explanation":["언제 · 어디인지 여전히 없어요.","더 넓게 부풀렸어요.","언제 · 어디에서를 밝혔어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#19','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C36',3,'mc','auto','갯벌 글 문단 ④를 읽고 남는 「되묻고 싶은 것」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":19,"concept":"K6-1-u6-C36","difficulty":3,"kind":"mc","stem":"갯벌 글 문단 ④를 읽고 남는 「되묻고 싶은 것」으로 알맞은 것은 어느 것인가요?","options":[{"t":"「바닷물이 들어올 때에도 괜찮을까?」","correct":true},{"t":"「갯벌은 넓을까?」","mis":"K6-1-u6-X27"},{"t":"「게는 어디에 살까?」","mis":"K6-1-u6-X27"},{"t":"「되물을 것이 없다.」","mis":"K6-1-u6-X27"}],"explanation":["앞에서 밝혔어요.","문단 ②에 있어요.","그 물음이 감춘 것을 가리켜요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#20','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C45',3,'mc','auto','도율이가 발표할 때 밝힐 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X44','K6-1-u6-X42']::text[],false,'{"seq":20,"concept":"K6-1-u6-C45","difficulty":3,"kind":"mc","stem":"도율이가 발표할 때 밝힐 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「수돗가에서 물이 그냥 흐르는 것을 보고 골랐어요. 그림의 물줄기를 일부러 크게 그린 까닭은 낭비를 한눈에 보여 주고 싶어서예요.」","correct":true},{"t":"「광고를 만들었어요. 끝.」","mis":"K6-1-u6-X44"},{"t":"「세게 쓴 곳은 말하지 않을게요.」","mis":"K6-1-u6-X42"},{"t":"「제 광고가 반에서 제일 나아요.」","mis":"K6-1-u6-X44"}],"explanation":["만든 뜻이 빠졌어요.","숨기면 속이는 셈이에요.","고른 까닭 · 강조한 것 · 세게 그린 까닭을 밝혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#21','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C3',3,'mc','auto','광고 · 주장하는 글 · 설명하는 글에 모두 댈 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u6-X29','K6-1-u6-X13','K6-1-u6-X23']::text[],false,'{"seq":21,"concept":"K6-1-u6-C3","difficulty":3,"kind":"mc","stem":"광고 · 주장하는 글 · 설명하는 글에 모두 댈 수 있는 것은 어느 것인가요?","options":[{"t":"내용의 타당성 세 물음과 표현의 적절성 세 물음","correct":true},{"t":"광고에만 쓰는 세 물음","mis":"K6-1-u6-X29"},{"t":"주장하는 글에만 쓰는 세 물음","mis":"K6-1-u6-X13"},{"t":"글씨 크기를 재는 자","mis":"K6-1-u6-X23"}],"explanation":["광고만의 일이 아니에요.","주장하는 글만도 아니에요.","여섯 물음은 어디에나 대요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#22','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C49',3,'mc','auto','맞춤법이 모두 바른 문장은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":22,"concept":"K6-1-u6-C49","difficulty":3,"kind":"mc","stem":"맞춤법이 모두 바른 문장은 어느 것인가요?","options":[{"t":"며칠 아팠는데 이제 다 나았어요.","correct":true},{"t":"몇일 아팠는데 이제 다 나았어요.","mis":"K6-1-u6-X48"},{"t":"며칠 아팠는데 이제 다 낳았어요.","mis":"K6-1-u6-X48"},{"t":"몇일 아팠는데 이제 다 낳았어요.","mis":"K6-1-u6-X48"}],"explanation":["「며칠」이에요.","병은 「나았다」예요.","둘 다 바르게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#23','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C47',4,'mc','auto','형광펜 광고 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X29','K6-1-u6-X21','K6-1-u6-X28']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"형광펜 광고 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"「다섯 가지 색」 · 「닫아 두면 잘 마르지 않음」은 알맞지만, 거짓 하나(공부가 저절로) · 과장(가장 밝은 · 영원히) · 감춤(가장 많이 팔린 · 작은 글씨)이 있다","correct":true},{"t":"광고는 원래 그러니 따질 것이 없다","mis":"K6-1-u6-X29"},{"t":"걸린 곳이 있으니 모든 문구가 엉터리다","mis":"K6-1-u6-X21"},{"t":"과장만 있고 거짓과 감춤은 없다","mis":"K6-1-u6-X28"}],"explanation":["광고도 따져요.","알맞은 문구도 있어요.","세 기준 모두에 걸린 곳이 있어요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#24','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C29',4,'essay','teacher','형광펜 광고에서 두 기준에 함께 걸리는 문구를 하나 찾아 두 기준과 까닭을 쓰고, 알맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C29","difficulty":4,"kind":"essay","stem":"형광펜 광고에서 두 기준에 함께 걸리는 문구를 하나 찾아 두 기준과 까닭을 쓰고, 알맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 「세상에서 가장 밝은 색!」은 과장이다. 형광펜의 색이 밝기는 해도 세상에서 가장 밝다고 부풀렸다. 동시에 감추는 내용도 있다. 무엇과 견주어 가장 밝은지 밝히지 않았다. 고쳐 쓰면 — 「어두운 글씨 위에서도 잘 보이는 밝은 색」.","scoring_points":["두 기준에 걸리는 문구를 찾았는가","두 기준과 까닭을 썼는가","알맞게 고쳐 썼는가"]},"explanation":["한 기준에서 멈추지 말아요.","기준마다 까닭을 대요.","덜어 내고 밝혀요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_b#25','kor',6,1,'u6','','g6_1_kor_u6_review_b','unit_review','K6-1-u6-C5',4,'essay','teacher','「비판적으로 읽기는 흠을 잡는 일이 아니다」라는 말의 뜻을, 이 단원에서 읽은 글 하나를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C5","difficulty":4,"kind":"essay","stem":"「비판적으로 읽기는 흠을 잡는 일이 아니다」라는 말의 뜻을, 이 단원에서 읽은 글 하나를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 안전모 글에는 「더 빨리 달린다」와 「옆집 형의 말」처럼 걸린 곳이 두 군데 있었다. 그렇다고 글 전체를 버리지 않고, 안전모를 쓰자는 주장과 머리를 지켜 준다는 이유, 직접 센 기록은 받아들였다. 비판적으로 읽는다는 것은 틀린 곳을 많이 찾는 것이 아니라 받아들일 것과 물릴 것을 까닭을 대어 스스로 가르는 일이다.","scoring_points":["단원의 글 하나를 예로 들었는가","받아들인 것과 짚은 것을 나누었는가","흠 잡기가 아닌 까닭을 정리했는가"]},"explanation":["읽은 글을 떠올려요.","받아들인 것도 써요.","골라내는 읽기로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#1','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C5',1,'ox','auto','비판적으로 읽는 목적은 글을 깎아내리는 거예요.',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":1,"concept":"K6-1-u6-C5","difficulty":1,"kind":"ox","stem":"비판적으로 읽는 목적은 글을 깎아내리는 거예요.","answer":"X","reason_options":[{"t":"맞는 곳은 받아들이고 나에게 필요한 정보를 골라내는 것이 목적이기 때문에","correct":true},{"t":"흠을 찾아내야 잘 읽은 것이기 때문에","mis":"K6-1-u6-X05"}],"mis":"K6-1-u6-X05","explanation":["깎아내리기가 아니에요.","트집이 목적이 아니에요.","골라내는 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#2','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C10',1,'ox','auto','맞는 말이면 주장과 관련이 없어도 이유가 돼요.',ARRAY['K6-1-u6-X10']::text[],false,'{"seq":2,"concept":"K6-1-u6-C10","difficulty":1,"kind":"ox","stem":"맞는 말이면 주장과 관련이 없어도 이유가 돼요.","answer":"X","reason_options":[{"t":"이유는 주장과 관련이 있어야 주장을 뒷받침할 수 있기 때문에","correct":true},{"t":"참인 문장은 모두 이유로 쓸 수 있기 때문에","mis":"K6-1-u6-X10"}],"mis":"K6-1-u6-X10","explanation":["참이어도 관련이 있어야 해요.","주장과 이어져야 해요.","참인 문장이라고 다 이유는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#3','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C14',1,'mc','auto','판단 기준에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X14','K6-1-u6-X06','K6-1-u6-X05']::text[],false,'{"seq":3,"concept":"K6-1-u6-C14","difficulty":1,"kind":"mc","stem":"판단 기준에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"세 기준 말고도 알맞은 기준을 물음의 꼴로 스스로 세워 쓸 수 있다","correct":true},{"t":"기준은 정해진 세 가지뿐이다","mis":"K6-1-u6-X14"},{"t":"기준은 그날 기분에 따라 정한다","mis":"K6-1-u6-X06"},{"t":"기준이 많을수록 흠을 많이 찾아 좋다","mis":"K6-1-u6-X05"}],"explanation":["더 세워도 좋아요.","기분은 기준이 아니에요.","흠 찾기가 목적이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#4','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C27',1,'mc','auto','알아야 할 것을 밝히지 않은 것을 무엇이라고 하나요?',ARRAY['K6-1-u6-X27','K6-1-u6-X14']::text[],false,'{"seq":4,"concept":"K6-1-u6-C27","difficulty":1,"kind":"mc","stem":"알아야 할 것을 밝히지 않은 것을 무엇이라고 하나요?","options":[{"t":"감추는 내용","correct":true},{"t":"거짓된 표현","mis":"K6-1-u6-X27"},{"t":"과장된 표현","mis":"K6-1-u6-X27"},{"t":"스스로 세운 기준","mis":"K6-1-u6-X14"}],"explanation":["틀린 말은 없을 수 있어요.","부풀린 것도 아니에요.","빼놓으면 감춤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#5','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C15',1,'ox','auto','포장에 크게 적힌 말만 읽으면 물건을 다 안 거예요.',ARRAY['K6-1-u6-X15']::text[],false,'{"seq":5,"concept":"K6-1-u6-C15","difficulty":1,"kind":"ox","stem":"포장에 크게 적힌 말만 읽으면 물건을 다 안 거예요.","answer":"X","reason_options":[{"t":"작은 글씨나 뒷부분에 조건이 적혀 있을 수 있어 한 번 더 확인해야 하기 때문에","correct":true},{"t":"큰 글씨에 모든 것이 적혀 있기 때문에","mis":"K6-1-u6-X15"}],"mis":"K6-1-u6-X15","explanation":["작은 글씨도 읽어요.","뒷부분까지 봐요.","한 번 더 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#6','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C35',1,'ox','auto','과장된 표현은 거짓말이 아니라서 더 알아채기 어려워요.',ARRAY['K6-1-u6-X34']::text[],false,'{"seq":6,"concept":"K6-1-u6-C35","difficulty":1,"kind":"ox","stem":"과장된 표현은 거짓말이 아니라서 더 알아채기 어려워요.","answer":"O","reason_options":[{"t":"있는 것을 부풀린 말이라 읽는 사람이 지나치게 믿게 되기 때문에","correct":true},{"t":"과장은 아무 문제가 없는 표현이기 때문에","mis":"K6-1-u6-X34"}],"mis":"K6-1-u6-X34","explanation":["문제가 있어요.","지나친 믿음을 남겨요.","그래서 더 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#7','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C40',1,'ox','auto','남의 글에서 찾아낸 흠은 내가 만든 글에서도 흠이에요.',ARRAY['K6-1-u6-X38']::text[],false,'{"seq":7,"concept":"K6-1-u6-C40","difficulty":1,"kind":"ox","stem":"남의 글에서 찾아낸 흠은 내가 만든 글에서도 흠이에요.","answer":"O","reason_options":[{"t":"읽을 때 걸렸던 것들이 만들 때 하지 말아야 할 것이 되기 때문에","correct":true},{"t":"내 글은 내가 만들었으니 괜찮기 때문에","mis":"K6-1-u6-X38"}],"mis":"K6-1-u6-X38","explanation":["내 글도 같은 자로 재요.","자를 뒤집어 들어요.","똑같이 흠이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#8','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C49',1,'mc','auto','「몇 날」을 뜻하는 말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":8,"concept":"K6-1-u6-C49","difficulty":1,"kind":"mc","stem":"「몇 날」을 뜻하는 말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"며칠","correct":true},{"t":"몇일","mis":"K6-1-u6-X48"},{"t":"몇 일","mis":"K6-1-u6-X48"},{"t":"멷일","mis":"K6-1-u6-X48"}],"explanation":["한 낱말로 「며칠」이에요.","띄어 쓰지 않아요.","몇 날을 뜻하는 「며칠」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#9','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C18',2,'mc','auto','담희 글 문단 ④의 이유가 걸리는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X10','K6-1-u6-X08','K6-1-u6-X18']::text[],false,'{"seq":9,"concept":"K6-1-u6-C18","difficulty":2,"kind":"mc","stem":"담희 글 문단 ④의 이유가 걸리는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"창문을 열어도 감기에 걸릴 수 있어 사실이 아니기 때문이다","correct":true},{"t":"창문 이야기가 아니기 때문이다","mis":"K6-1-u6-X10"},{"t":"문단이 짧기 때문이다","mis":"K6-1-u6-X08"},{"t":"감기는 누구나 알기 때문이다","mis":"K6-1-u6-X18"}],"explanation":["창문 이야기가 맞아요.","길이 문제가 아니에요.","실제로 일어나지 않는 일이에요 — 바르게는 「바깥 공기가 들어와 답답함이 줄어듭니다」처럼 말해요."],"asset":{"type":"passage","lines":["④ 셋째, 창문을 열어 두면 감기에 걸리지 않습니다.","옆 반 친구가 그렇게 말해 주었습니다.","⑤ 창문만 열면 교실의 모든 문제가 사라집니다.","⑥ 추운 날에는 잠깐만 열어도 됩니다. 쉬는 시간마다 창문을 열어 둡시다."],"title":"담희의 글 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#10','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C16',2,'mc','auto','「「답답하다」고 적은 친구가 날마다 줄었다」는 어느 이유를 받치나요?',ARRAY['K6-1-u6-X16']::text[],false,'{"seq":10,"concept":"K6-1-u6-C16","difficulty":2,"kind":"mc","stem":"「「답답하다」고 적은 친구가 날마다 줄었다」는 어느 이유를 받치나요?","options":[{"t":"바깥 공기가 들어와 교실 공기가 바뀐다","correct":true},{"t":"창문을 닫으면 조용하다","mis":"K6-1-u6-X16"},{"t":"감기에 걸리지 않는다","mis":"K6-1-u6-X16"},{"t":"모든 문제가 사라진다","mis":"K6-1-u6-X16"}],"explanation":["반대 쪽 이유예요.","사실이 아닌 이유예요.","같은 문단 ② 안에서 짝을 찾아요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#11','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C28',2,'mc','auto','「공부가 저절로 되는」은 거짓, 「영원히 마르지 않는」은 과장으로 가른 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X24','K6-1-u6-X23','K6-1-u6-X25']::text[],false,'{"seq":11,"concept":"K6-1-u6-C28","difficulty":2,"kind":"mc","stem":"「공부가 저절로 되는」은 거짓, 「영원히 마르지 않는」은 과장으로 가른 까닭은 어느 것인가요?","options":[{"t":"앞은 형광펜에 없는 기능이고, 뒤는 있는 기능(잘 마르지 않음)을 부풀렸기 때문이다","correct":true},{"t":"앞의 글씨가 더 크기 때문이다","mis":"K6-1-u6-X24"},{"t":"뒤에 느낌표가 있기 때문이다","mis":"K6-1-u6-X23"},{"t":"둘 다 같은 것이기 때문이다","mis":"K6-1-u6-X25"}],"explanation":["크기로 가르지 않아요.","느낌표와 관계없어요.","기능이 실제로 있는지로 갈라요. (바로잡기: 형광펜에는 공부를 대신해 주는 기능이 없어요.) (바로잡기: 뚜껑을 열어 두면 잉크는 마를 수 있어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#12','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C30',2,'ox','auto','안내문이나 주장하는 글도 부풀리거나 감출 수 있어요.',ARRAY['K6-1-u6-X29']::text[],false,'{"seq":12,"concept":"K6-1-u6-C30","difficulty":2,"kind":"ox","stem":"안내문이나 주장하는 글도 부풀리거나 감출 수 있어요.","answer":"O","reason_options":[{"t":"설득하려는 글이면 어디서든 일어날 수 있기 때문에","correct":true},{"t":"부풀리고 감추는 건 광고에서만 일어나기 때문에","mis":"K6-1-u6-X29"}],"mis":"K6-1-u6-X29","explanation":["광고만의 일이 아니에요.","어떤 글에도 세 물음을 대요.","설득하는 글이면 어디든요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#13','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C36',2,'mc','auto','「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」가 감춘 것은 어느 것인가요?',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":13,"concept":"K6-1-u6-C36","difficulty":2,"kind":"mc","stem":"「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」가 감춘 것은 어느 것인가요?","options":[{"t":"바닷물이 들어오는 때에는 위험하니 그때를 확인해야 한다는 점","correct":true},{"t":"갯벌이 넓다는 점","mis":"K6-1-u6-X27"},{"t":"갯벌에 게가 산다는 점","mis":"K6-1-u6-X27"},{"t":"감춘 것이 없다","mis":"K6-1-u6-X27"}],"explanation":["앞에서 밝혔어요.","그것도 밝혔어요.","알아야 할 것을 빼놓았어요 — 바르게는 「바닷물이 들어오는 때를 확인하고 어른과 함께 들어가야 합니다」예요. (바로잡기: 우리나라에는 모래 바닷가 · 바위 바닷가도 있어요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#14','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C37',2,'mc','auto','「갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다」를 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u6-X35','K6-1-u6-X33']::text[],false,'{"seq":14,"concept":"K6-1-u6-C37","difficulty":2,"kind":"mc","stem":"「갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다」를 알맞게 고친 것은 어느 것인가요?","options":[{"t":"갯벌 생물은 알맞게 잡으면 다시 늘어날 수 있지만, 지나치게 잡으면 줄어듭니다","correct":true},{"t":"갯벌 생물은 아무리 잡아도 정말 절대 줄지 않습니다","mis":"K6-1-u6-X35"},{"t":"갯벌 생물은 하나도 잡지 맙시다","mis":"K6-1-u6-X35"},{"t":"갯벌 생물은 언제나 늘어납니다","mis":"K6-1-u6-X33"}],"explanation":["더 부풀렸어요.","뜻까지 바꿨어요.","있는 만큼 말했어요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#15','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C41',2,'mc','auto','도율이가 고른 주제 「비누칠하는 동안 물 잠그기」가 알맞은 까닭은 어느 것인가요?',ARRAY['K6-1-u6-X39','K6-1-u6-X42']::text[],false,'{"seq":15,"concept":"K6-1-u6-C41","difficulty":2,"kind":"mc","stem":"도율이가 고른 주제 「비누칠하는 동안 물 잠그기」가 알맞은 까닭은 어느 것인가요?","options":[{"t":"여럿이 함께 겪고, 고치면 물을 덜 쓰게 되어 나아지는 일이기 때문이다","correct":true},{"t":"나 혼자만 겪는 일이기 때문이다","mis":"K6-1-u6-X39"},{"t":"고쳐도 달라지지 않기 때문이다","mis":"K6-1-u6-X39"},{"t":"부풀리기 쉬운 주제이기 때문이다","mis":"K6-1-u6-X42"}],"explanation":["여럿이 겪어요.","고치면 나아져요.","부풀리기 쉬운 게 까닭이 아니에요. (바로잡기: 물을 틀어 놓아도 지구의 물이 하루 만에 마르지 않아요.) (바로잡기: 물을 틀어 두었다고 벌금을 내는 벌금 규칙은 없어요.)"],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#16','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C46',2,'mc','auto','도율이가 ⑤문단을 알맞게 판단해 말한 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X45','K6-1-u6-X21']::text[],false,'{"seq":16,"concept":"K6-1-u6-C46","difficulty":2,"kind":"mc","stem":"도율이가 ⑤문단을 알맞게 판단해 말한 것은 어느 것인가요?","options":[{"t":"「〈모든 문제가 사라진다〉는 부풀렸어. 창문을 열어도 해결 안 되는 문제가 있으니까. 그래도 직접 센 기록은 좋아.」","correct":true},{"t":"「⑤문단은 그냥 별로야.」","mis":"K6-1-u6-X06"},{"t":"「너는 늘 과장하잖아.」","mis":"K6-1-u6-X45"},{"t":"「⑤문단 때문에 글 전체가 엉터리야.」","mis":"K6-1-u6-X21"}],"explanation":["까닭이 없어요.","사람을 겨누지 않아요.","까닭과 잘한 점이 함께 있어요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#17','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C17',3,'mc','auto','「담희 글의 문단 ④는 뒷받침하지 못한다」에 붙일 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X17','K6-1-u6-X06','K6-1-u6-X20']::text[],false,'{"seq":17,"concept":"K6-1-u6-C17","difficulty":3,"kind":"mc","stem":"「담희 글의 문단 ④는 뒷받침하지 못한다」에 붙일 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"창문을 열어도 감기에 걸릴 수 있어 사실이 아니고, 근거도 전해 들은 말이라 확인할 수 없기 때문이다","correct":true},{"t":"담희 글에 그렇게 적혀 있기 때문이다","mis":"K6-1-u6-X17"},{"t":"감기 이야기는 재미없기 때문이다","mis":"K6-1-u6-X06"},{"t":"문단 ④가 맨 뒤에 있기 때문이다","mis":"K6-1-u6-X20"}],"explanation":["적혀 있다는 건 까닭이 아니에요.","재미로 재지 않아요.","두 곳을 까닭과 함께 짚었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#18','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C31',3,'mc','auto','둘레의 광고를 재며 공책에 적은 것 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X06','K6-1-u6-X17','K6-1-u6-X45']::text[],false,'{"seq":18,"concept":"K6-1-u6-C31","difficulty":3,"kind":"mc","stem":"둘레의 광고를 재며 공책에 적은 것 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「먹기만 하면 키가 쑥쑥」 — 거짓 ×: 먹는 것 하나로 키가 크지는 않아 없는 효과를 말했다","correct":true},{"t":"「먹기만 하면 키가 쑥쑥」 — ×: 그냥 싫다","mis":"K6-1-u6-X06"},{"t":"「먹기만 하면 키가 쑥쑥」 — ○: 상자에 크게 적혀 있다","mis":"K6-1-u6-X17"},{"t":"「먹기만 하면 키가 쑥쑥」 — ×: 광고 모델이 별로다","mis":"K6-1-u6-X45"}],"explanation":["까닭이 없어요.","크게 적힌 건 까닭이 아니에요.","판단에 까닭이 붙었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#19','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C39',3,'mc','auto','친구는 갯벌 글 ⑤문단의 「절대 줄어들지 않는다」를 거짓이라고 했어요. 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u6-X37','K6-1-u6-X21']::text[],false,'{"seq":19,"concept":"K6-1-u6-C39","difficulty":3,"kind":"mc","stem":"친구는 갯벌 글 ⑤문단의 「절대 줄어들지 않는다」를 거짓이라고 했어요. 알맞은 태도는 어느 것인가요?","options":[{"t":"까닭을 들어 보고, 그 까닭이 타당하면 내 판단(과장)과 달라도 받아들일 수 있다","correct":true},{"t":"내 판단과 다르니 틀렸다고 한다","mis":"K6-1-u6-X37"},{"t":"까닭은 듣지 않고 기준 이름만 따진다","mis":"K6-1-u6-X37"},{"t":"둘 다 틀렸으니 판단하지 않는다","mis":"K6-1-u6-X21"}],"explanation":["까닭부터 들어요.","까닭이 중요해요.","판단은 정해진 답 맞히기가 아니에요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#20','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C43',3,'mc','auto','도율이가 「잠가요, 비누칠하는 동안」만 작게 적고 꾸밈 없이 두었다면 생길 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X41','K6-1-u6-X42']::text[],false,'{"seq":20,"concept":"K6-1-u6-C43","difficulty":3,"kind":"mc","stem":"도율이가 「잠가요, 비누칠하는 동안」만 작게 적고 꾸밈 없이 두었다면 생길 일로 알맞은 것은 어느 것인가요?","options":[{"t":"틀린 말은 없지만 눈에 띄지 않아 아무도 보지 않는 광고가 되기 쉽다","correct":true},{"t":"가장 좋은 광고가 된다","mis":"K6-1-u6-X41"},{"t":"믿을 수 없는 광고가 된다","mis":"K6-1-u6-X42"},{"t":"아무 일도 없다","mis":"K6-1-u6-X41"}],"explanation":["보아야 뜻이 전해져요.","부풀리지 않아 믿을 수는 있어요.","눈에 띄게도 만들어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#21','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C14',3,'mc','auto','그늘막 글에 내가 세운 기준 「한쪽 이야기만 담지는 않았는가?」를 대었을 때 알맞은 판단은 어느 것인가요?',ARRAY['K6-1-u6-X14','K6-1-u6-X01','K6-1-u6-X06']::text[],false,'{"seq":21,"concept":"K6-1-u6-C14","difficulty":3,"kind":"mc","stem":"그늘막 글에 내가 세운 기준 「한쪽 이야기만 담지는 않았는가?」를 대었을 때 알맞은 판단은 어느 것인가요?","options":[{"t":"그늘막의 좋은 점만 담아, 세우는 데 드는 비용이나 세울 곳 같은 다른 쪽 이야기가 빠졌다","correct":true},{"t":"기준은 세 가지뿐이라 이 기준은 댈 수 없다","mis":"K6-1-u6-X14"},{"t":"그늘막 글은 흠이 없다","mis":"K6-1-u6-X01"},{"t":"그냥 한쪽 같다","mis":"K6-1-u6-X06"}],"explanation":["스스로 기준을 세워도 돼요.","따져 보아요.","판단에 까닭이 붙었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#22','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C9',3,'mc','auto','하자는 대로 했을 때 다른 문제가 생겨 가치 있다고 보기 어려운 주장은 어느 것인가요?',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":22,"concept":"K6-1-u6-C9","difficulty":3,"kind":"mc","stem":"하자는 대로 했을 때 다른 문제가 생겨 가치 있다고 보기 어려운 주장은 어느 것인가요?","options":[{"t":"창문을 열어 두려면 겨울에도 하루 종일 열어 둡시다","correct":true},{"t":"쉬는 시간마다 창문을 잠깐 열어 둡시다","mis":"K6-1-u6-X05"},{"t":"복도 정수기 앞에서는 차례를 지킵시다","mis":"K6-1-u6-X05"},{"t":"빌린 물건은 빌린 그대로 돌려줍시다","mis":"K6-1-u6-X05"}],"explanation":["여럿에게 도움이 되는 주장이에요.","이것도 가치 있어요.","추위라는 다른 문제를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#23','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C47',4,'mc','auto','갯벌 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X31','K6-1-u6-X21','K6-1-u6-X46']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"갯벌 글 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"문단 ①~③의 설명은 그대로 배워도 좋지만, ④의 감춤 · ⑤의 과장과 거짓을 고치고 다른 관점의 글도 찾아 읽는다","correct":true},{"t":"설명하는 글이니 그대로 외운다","mis":"K6-1-u6-X31"},{"t":"걸린 곳이 있으니 갯벌 이야기는 모두 믿지 않는다","mis":"K6-1-u6-X21"},{"t":"표현은 괜찮고 내용만 따지면 된다","mis":"K6-1-u6-X46"}],"explanation":["외우기 전에 따져요.","맞는 설명은 배워요.","표현에 걸린 곳이 있어요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#24','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C36',4,'essay','teacher','갯벌 글의 문단 ④가 무엇을 감추었는지 쓰고, 그것을 알지 못한 채 읽은 사람에게 생길 수 있는 일과 고쳐 쓴 문장을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C36","difficulty":4,"kind":"essay","stem":"갯벌 글의 문단 ④가 무엇을 감추었는지 쓰고, 그것을 알지 못한 채 읽은 사람에게 생길 수 있는 일과 고쳐 쓴 문장을 쓰세요.","answer_guide":{"answer":"예: 「갯벌은 언제든 걸어 들어가 놀아도 좋습니다」는 바닷물이 들어오는 때에는 위험하다는 점을 감추었다. 이것을 모르는 사람은 물이 들어오는 줄 모르고 멀리 들어갔다가 위험해질 수 있다. 고쳐 쓰면 — 「갯벌에 들어갈 때에는 바닷물이 들어오는 때를 확인하고 어른과 함께 가야 합니다.」","scoring_points":["감춘 것을 썼는가","읽는 사람에게 생길 일을 썼는가","감춘 것을 밝혀 고쳐 썼는가"]},"explanation":["되묻고 싶은 것을 찾아요.","한쪽만 알면 생길 일을 떠올려요.","알아야 할 것을 밝혀요."],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_c#25','kor',6,1,'u6','','g6_1_kor_u6_review_c','unit_review','K6-1-u6-C32',4,'essay','teacher','광고보다 설명하는 글을 읽을 때 더 조심해야 하는 까닭을 쓰고, 설명하는 글에서 거짓 · 과장 · 감춤이 각각 무엇을 남기는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C32","difficulty":4,"kind":"essay","stem":"광고보다 설명하는 글을 읽을 때 더 조심해야 하는 까닭을 쓰고, 설명하는 글에서 거짓 · 과장 · 감춤이 각각 무엇을 남기는지 쓰세요.","answer_guide":{"answer":"예: 광고는 알리려고 쓴 글인 줄 알아 부풀린 말을 걸러 읽지만, 설명하는 글은 알려 주려고 쓴 글이라 여겨 적힌 대로 외우기 쉽다. 그래서 거짓된 표현은 잘못된 지식이 되고, 과장된 표현은 지나친 믿음이 되며, 감추는 내용은 한쪽만 아는 사람을 만든다.","scoring_points":["더 조심해야 하는 까닭을 썼는가","세 가지가 남기는 것을 썼는가","광고와 견주어 설명했는가"]},"explanation":["읽는 사람의 마음을 떠올려요.","세 가지를 하나씩 써요.","광고와 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#1','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C2',1,'ox','auto','읽다가 「이상한데?」 하고 멈추는 것이 비판적 읽기의 첫걸음이에요.',ARRAY['K6-1-u6-X21']::text[],false,'{"seq":1,"concept":"K6-1-u6-C2","difficulty":1,"kind":"ox","stem":"읽다가 「이상한데?」 하고 멈추는 것이 비판적 읽기의 첫걸음이에요.","answer":"O","reason_options":[{"t":"의문이 드는 곳을 짚어야 어디가 왜 이상한지 따져 볼 수 있기 때문에","correct":true},{"t":"이상한 곳이 있으면 바로 글을 버리기 위해서이기 때문에","mis":"K6-1-u6-X21"}],"mis":"K6-1-u6-X21","explanation":["버리려고 멈추는 게 아니에요.","따져 보려고 멈춰요.","물음에서 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#2','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C9',1,'mc','auto','주장이 가치 있고 중요한지 재는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X09','K6-1-u6-X08','K6-1-u6-X23']::text[],false,'{"seq":2,"concept":"K6-1-u6-C9","difficulty":1,"kind":"mc","stem":"주장이 가치 있고 중요한지 재는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 사람에게 도움이 되고 많은 사람이 받아들일 수 있는가?","correct":true},{"t":"글쓴이가 그 주장을 좋아하는가?","mis":"K6-1-u6-X09"},{"t":"주장이 짧은가?","mis":"K6-1-u6-X08"},{"t":"주장에 느낌표가 있는가?","mis":"K6-1-u6-X23"}],"explanation":["글쓴이의 마음으로 재지 않아요.","길이로 재지 않아요.","여럿에게 도움이 되는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#3','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C20',1,'mc','auto','한 편의 글을 재는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X20']::text[],false,'{"seq":3,"concept":"K6-1-u6-C20","difficulty":1,"kind":"mc","stem":"한 편의 글을 재는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주장을 재고, 이유를 재고, 근거를 잰다","correct":true},{"t":"근거부터 재고 주장은 마지막에 본다","mis":"K6-1-u6-X20"},{"t":"마음에 드는 문단부터 잰다","mis":"K6-1-u6-X20"},{"t":"세 기준을 한꺼번에 아무 데나 댄다","mis":"K6-1-u6-X20"}],"explanation":["주장부터 봐요.","차례가 있어요.","주장 → 이유 → 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#4','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C23',1,'mc','auto','표현의 적절성은 무엇을 재나요?',ARRAY['K6-1-u6-X23','K6-1-u6-X03']::text[],false,'{"seq":4,"concept":"K6-1-u6-C23","difficulty":1,"kind":"mc","stem":"표현의 적절성은 무엇을 재나요?","options":[{"t":"내용을 어떻게 말했는가","correct":true},{"t":"글씨를 얼마나 예쁘게 썼는가","mis":"K6-1-u6-X23"},{"t":"글이 얼마나 긴가","mis":"K6-1-u6-X23"},{"t":"주장이 가치 있는가","mis":"K6-1-u6-X03"}],"explanation":["겉모습이 아니에요.","길이도 아니에요.","어떻게 말했는지 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#5','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C29',1,'ox','auto','한 광고 문구가 과장이면서 감춤일 수도 있어요.',ARRAY['K6-1-u6-X28']::text[],false,'{"seq":5,"concept":"K6-1-u6-C29","difficulty":1,"kind":"ox","stem":"한 광고 문구가 과장이면서 감춤일 수도 있어요.","answer":"O","reason_options":[{"t":"한 문구가 두 기준에 함께 걸릴 수 있기 때문에","correct":true},{"t":"한 문구는 한 기준에만 걸리기 때문에","mis":"K6-1-u6-X28"}],"mis":"K6-1-u6-X28","explanation":["기준은 서로 밀어내지 않아요.","두 기준에 함께 걸려요.","하나씩 들고 훑어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#6','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C36',1,'ox','auto','틀린 말이 하나도 없으면 감춘 것도 없어요.',ARRAY['K6-1-u6-X27']::text[],false,'{"seq":6,"concept":"K6-1-u6-C36","difficulty":1,"kind":"ox","stem":"틀린 말이 하나도 없으면 감춘 것도 없어요.","answer":"X","reason_options":[{"t":"틀린 말 없이도 알아야 할 것을 빼놓아 한쪽만 알게 할 수 있기 때문에","correct":true},{"t":"감춤은 틀린 말을 할 때만 생기기 때문에","mis":"K6-1-u6-X27"}],"mis":"K6-1-u6-X27","explanation":["틀린 말이 없어도 감출 수 있어요.","빼놓은 것을 봐요.","되묻고 싶은 게 남는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#7','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C46',1,'ox','auto','친구의 광고를 판단할 때에는 만든 사람이 아니라 문구를 두고 말해요.',ARRAY['K6-1-u6-X45']::text[],false,'{"seq":7,"concept":"K6-1-u6-C46","difficulty":1,"kind":"ox","stem":"친구의 광고를 판단할 때에는 만든 사람이 아니라 문구를 두고 말해요.","answer":"O","reason_options":[{"t":"어느 문구가 왜 걸리는지 짚어야 친구가 고칠 곳을 알 수 있기 때문에","correct":true},{"t":"만든 사람을 두고 말해야 더 정확하기 때문에","mis":"K6-1-u6-X45"}],"mis":"K6-1-u6-X45","explanation":["사람을 겨누지 않아요.","문구를 짚어요.","까닭과 잘한 점도 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#8','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C49',1,'mc','auto','「오래간만에」가 줄어든 말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K6-1-u6-X48']::text[],false,'{"seq":8,"concept":"K6-1-u6-C49","difficulty":1,"kind":"mc","stem":"「오래간만에」가 줄어든 말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"오랜만에","correct":true},{"t":"오랫만에","mis":"K6-1-u6-X48"},{"t":"오렌만에","mis":"K6-1-u6-X48"},{"t":"오랜마네","mis":"K6-1-u6-X48"}],"explanation":["「오래간만에」가 줄었어요.","「랜」이에요.","「오랜만에」가 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#9','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C10',2,'ox','auto','담희 글 문단 ③은 맞는 말일 수 있지만 주장을 뒷받침하지 못해요.',ARRAY['K6-1-u6-X10']::text[],false,'{"seq":9,"concept":"K6-1-u6-C10","difficulty":2,"kind":"ox","stem":"담희 글 문단 ③은 맞는 말일 수 있지만 주장을 뒷받침하지 못해요.","answer":"O","reason_options":[{"t":"닫아 두자는 쪽을 가리켜 열어 두자는 주장과 어긋나기 때문에","correct":true},{"t":"맞는 말이면 모두 이유가 되기 때문에","mis":"K6-1-u6-X10"}],"mis":"K6-1-u6-X10","explanation":["맞는 말이어도 방향을 봐요.","주장 편이어야 해요.","어긋난 이유예요 — 주장 쪽 이유로 바꿔 써요."],"asset":{"type":"passage","lines":["① 셋째 시간이 끝날 무렵이면 교실 공기가 답답해집니다.","쉬는 시간마다 창문을 열어 두면 좋겠습니다.","② 첫째, 바깥 공기가 들어와 교실 공기가 바뀝니다. 우리 반이 일주일 동안","쉬는 시간마다 창문을 열어 보니, 「답답하다」고 적은 친구가 날마다 줄었습니다.","③ 둘째, 창문을 닫아 두면 바깥 소리가 들어오지 않아 수업에 마음을 모을 수 있습니다."],"title":"담희의 글 「쉬는 시간마다 창문을 열어 둡시다」 — 앞부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#10','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C17',2,'mc','auto','「담희 글의 주장은 가치 있나요?」에 가장 좋은 답은 어느 것인가요?',ARRAY['K6-1-u6-X17','K6-1-u6-X21','K6-1-u6-X06']::text[],false,'{"seq":10,"concept":"K6-1-u6-C17","difficulty":2,"kind":"mc","stem":"「담희 글의 주장은 가치 있나요?」에 가장 좋은 답은 어느 것인가요?","options":[{"t":"가치 있다 — 답답한 공기를 바꾸어 여럿에게 도움이 되고 누구나 받아들일 만하다","correct":true},{"t":"가치 있다 — 글에 그렇게 적혀 있다","mis":"K6-1-u6-X17"},{"t":"가치 없다 — 걸린 곳이 있다","mis":"K6-1-u6-X21"},{"t":"가치 있다","mis":"K6-1-u6-X06"}],"explanation":["적혀 있는 건 까닭이 아니에요.","걸린 곳과 주장의 가치는 따로예요.","판단과 까닭이 한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#11','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C29',2,'mc','auto','「세상에서 가장 밝은 색!」을 바르게 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X26','K6-1-u6-X25']::text[],false,'{"seq":11,"concept":"K6-1-u6-C29","difficulty":2,"kind":"mc","stem":"「세상에서 가장 밝은 색!」을 바르게 판단한 것은 어느 것인가요?","options":[{"t":"부풀린 과장이면서, 무엇과 견주어 가장 밝은지 밝히지 않은 감춤이기도 하다","correct":true},{"t":"과장일 뿐이다","mis":"K6-1-u6-X28"},{"t":"알맞은 표현이다","mis":"K6-1-u6-X26"},{"t":"없는 기능을 말한 거짓이다","mis":"K6-1-u6-X25"}],"explanation":["한 기준에만 걸리지 않아요.","부풀렸어요.","두 기준에 함께 걸려요. (바로잡기: 형광펜에는 공부를 대신해 주는 기능이 없어요.)"],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#12','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C30',2,'ox','auto','부풀린 말만 없으면 그 정보는 다 믿을 수 있어요.',ARRAY['K6-1-u6-X30']::text[],false,'{"seq":12,"concept":"K6-1-u6-C30","difficulty":2,"kind":"ox","stem":"부풀린 말만 없으면 그 정보는 다 믿을 수 있어요.","answer":"X","reason_options":[{"t":"오래되어 지금과 맞지 않거나 두루뭉술해 오해하게 하는 정보도 믿기 어렵기 때문에","correct":true},{"t":"부풀리지 않은 정보는 언제나 정확하기 때문에","mis":"K6-1-u6-X30"}],"mis":"K6-1-u6-X30","explanation":["부풀림만 보지 않아요.","오래된 · 흐린 정보도 따져요.","언제 · 무엇인지 분명한지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#13','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C32',2,'mc','auto','갯벌 글을 「알려 주는 글이니까」 하고 그대로 외우면 생길 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X31','K6-1-u6-X21']::text[],false,'{"seq":13,"concept":"K6-1-u6-C32","difficulty":2,"kind":"mc","stem":"갯벌 글을 「알려 주는 글이니까」 하고 그대로 외우면 생길 일로 알맞은 것은 어느 것인가요?","options":[{"t":"바닷가는 다 갯벌이라는 잘못된 지식과, 생물이 절대 줄지 않는다는 지나친 믿음이 남는다","correct":true},{"t":"아무 일도 생기지 않는다","mis":"K6-1-u6-X31"},{"t":"갯벌을 더 정확히 알게 된다","mis":"K6-1-u6-X31"},{"t":"갯벌 글을 더는 읽지 않게 된다","mis":"K6-1-u6-X21"}],"explanation":["외운 것이 지식이 돼요.","흠까지 외우게 돼요.","거짓은 잘못된 지식, 과장은 지나친 믿음이 돼요. (바로잡기: 우리나라에는 모래 바닷가 · 바위 바닷가도 있어요.) (바로잡기: 바닷물이 들어오는 때에는 갯벌에 들어가면 위험해요.) (바로잡기: 갯벌 생물도 지나치게 잡으면 줄어들어요.)"],"asset":{"type":"passage","lines":["④ 갯벌은 언제든 걸어 들어가 놀아도 좋습니다.","⑤ 갯벌 생물은 아무리 많이 잡아도 절대 줄어들지 않습니다.","요즘 우리나라 바닷가는 모두 갯벌로 이루어져 있습니다.","⑥ 갯벌을 보면 바다와 땅이 함께 만든 살림터를 알 수 있습니다."],"title":"「바다와 땅 사이, 갯벌」 — 뒷부분 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#14','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C13',2,'ox','auto','갯벌 글처럼 설명하는 글도 내용이 타당한지 따져 읽어요.',ARRAY['K6-1-u6-X13']::text[],false,'{"seq":14,"concept":"K6-1-u6-C13","difficulty":2,"kind":"ox","stem":"갯벌 글처럼 설명하는 글도 내용이 타당한지 따져 읽어요.","answer":"O","reason_options":[{"t":"내용을 담은 글이면 같은 물음으로 살필 수 있기 때문에","correct":true},{"t":"설명하는 글은 따질 것이 없기 때문에","mis":"K6-1-u6-X13"}],"mis":"K6-1-u6-X13","explanation":["설명하는 글도 따져요.","내용을 담았으니까요.","어디에나 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#15','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C44',2,'mc','auto','도율이 광고에서 크게 쓸 한 줄로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X43','K6-1-u6-X42']::text[],false,'{"seq":15,"concept":"K6-1-u6-C44","difficulty":2,"kind":"mc","stem":"도율이 광고에서 크게 쓸 한 줄로 알맞은 것은 어느 것인가요?","options":[{"t":"잠가요, 비누칠하는 동안","correct":true},{"t":"ㄱ~ㄹ 네 줄 모두","mis":"K6-1-u6-X43"},{"t":"「무조건 벌금!」","mis":"K6-1-u6-X42"},{"t":"그림 아래 작은 설명","mis":"K6-1-u6-X43"}],"explanation":["다 크면 아무것도 크지 않아요.","거짓을 크게 하면 안 돼요.","하고 싶은 한 줄만 크게요. (바로잡기: 물을 틀어 놓아도 지구의 물이 하루 만에 마르지 않아요.) (바로잡기: 물을 틀어 두었다고 벌금을 내는 벌금 규칙은 없어요.)"],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#16','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C5',2,'ox','auto','도율이처럼 이상한 곳을 많이 찾은 것만으로 글을 잘 읽은 거예요.',ARRAY['K6-1-u6-X05']::text[],false,'{"seq":16,"concept":"K6-1-u6-C5","difficulty":2,"kind":"ox","stem":"도율이처럼 이상한 곳을 많이 찾은 것만으로 글을 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"맞는 곳은 받아들이고 걸린 곳은 까닭을 대어 짚어야 비판적으로 읽은 것이기 때문에","correct":true},{"t":"흠을 많이 찾을수록 잘 읽은 것이기 때문에","mis":"K6-1-u6-X05"}],"mis":"K6-1-u6-X05","explanation":["개수가 아니에요.","까닭이 함께 가요.","골라내는 읽기예요."],"asset":{"type":"speech","turns":[{"who":"도율","text":"담희 글에 이상한 데가 세 군데나 있어. 이 글은 다 버리는 게 낫겠다."},{"who":"담희","text":"걸린 곳만 짚어 줘. 창문을 열자는 주장과 직접 센 기록도 틀렸어?"},{"who":"도율","text":"그건 아니야. 그리고 ⑤문단은 그냥 별로야."},{"who":"담희","text":"별로라고만 하면 어디를 고칠지 모르겠어. 왜 걸리는지 까닭을 말해 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#17','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C18',3,'mc','auto','담희 글 문단 ④를 주장 편에 서도록 고친 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X26','K6-1-u6-X11','K6-1-u6-X10']::text[],false,'{"seq":17,"concept":"K6-1-u6-C18","difficulty":3,"kind":"mc","stem":"담희 글 문단 ④를 주장 편에 서도록 고친 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"셋째, 바깥 공기가 들어오면 답답함이 줄어 쉬는 시간이 더 상쾌해집니다","correct":true},{"t":"셋째, 창문을 열면 감기가 절대 안 걸립니다","mis":"K6-1-u6-X26"},{"t":"셋째, 창문을 닫으면 따뜻합니다","mis":"K6-1-u6-X11"},{"t":"셋째, 옆 반도 창문을 엽니다","mis":"K6-1-u6-X10"}],"explanation":["더 부풀렸어요.","주장과 반대예요.","사실이고 주장 편이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#18','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C29',3,'mc','auto','형광펜 광고의 「영원히 마르지 않는 잉크!」를 두 기준으로 모두 판단한 것은 어느 것인가요?',ARRAY['K6-1-u6-X28','K6-1-u6-X25','K6-1-u6-X26']::text[],false,'{"seq":18,"concept":"K6-1-u6-C29","difficulty":3,"kind":"mc","stem":"형광펜 광고의 「영원히 마르지 않는 잉크!」를 두 기준으로 모두 판단한 것은 어느 것인가요?","options":[{"t":"어떤 경우에도 마르지 않는다고 부풀린 과장이고, 마를 수 있다는 조건을 아주 작게 적어 감춤에도 가깝다","correct":true},{"t":"과장 하나에만 걸린다","mis":"K6-1-u6-X28"},{"t":"거짓 하나에만 걸린다","mis":"K6-1-u6-X25"},{"t":"어느 기준에도 걸리지 않는다","mis":"K6-1-u6-X26"}],"explanation":["작은 글씨까지 봐요.","기능은 있어요.","두 기준에 함께 걸려요."],"asset":{"type":"passage","lines":["장면 ① 형광펜을 든 아이가 웃는 큰 그림 「공부가 저절로 되는 형광펜!」","장면 ② 「다섯 가지 색이 한 묶음」 「뚜껑을 닫아 두면 잘 마르지 않아요.」","장면 ③ 금빛 딱지 「세상에서 가장 밝은 색! 가장 많이 팔린 형광펜!」","장면 ④ 「영원히 마르지 않는 잉크!」","　　(아주 작은 글씨) ※ 뚜껑을 열어 두면 금방 마를 수 있음."],"title":"형광펜 광고 「쓱쓱 형광펜」 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#19','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C38',3,'mc','auto','갯벌 글과 함께 읽으면 좋은 글로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X36']::text[],false,'{"seq":19,"concept":"K6-1-u6-C38","difficulty":3,"kind":"mc","stem":"갯벌 글과 함께 읽으면 좋은 글로 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌이 줄어든 바닷가 마을의 변화를 다룬 글","correct":true},{"t":"갯벌의 좋은 점만 한 번 더 늘어놓은 글","mis":"K6-1-u6-X36"},{"t":"갯벌과 관계없는 이야기책","mis":"K6-1-u6-X36"},{"t":"함께 읽을 글은 필요 없다","mis":"K6-1-u6-X36"}],"explanation":["같은 쪽의 글이에요.","관련 있는 글이어야 해요.","다른 관점의 관련 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#20','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C44',3,'mc','auto','도율이 광고에서 진한 색을 쓸 곳으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X43','K6-1-u6-X41']::text[],false,'{"seq":20,"concept":"K6-1-u6-C44","difficulty":3,"kind":"mc","stem":"도율이 광고에서 진한 색을 쓸 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"「잠가요, 비누칠하는 동안」 한 줄","correct":true},{"t":"광고 전체","mis":"K6-1-u6-X43"},{"t":"그림 아래 작은 설명 글","mis":"K6-1-u6-X43"},{"t":"아무 데도 쓰지 않는다","mis":"K6-1-u6-X41"}],"explanation":["온통 진하면 강조가 사라져요.","강조할 곳이 아니에요.","강조할 한 줄에만 써요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#21','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C22',3,'mc','auto','단원을 마친 뒤 둘레의 글을 읽을 때 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X22','K6-1-u6-X15','K6-1-u6-X01']::text[],false,'{"seq":21,"concept":"K6-1-u6-C22","difficulty":3,"kind":"mc","stem":"단원을 마친 뒤 둘레의 글을 읽을 때 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"게시판 글 · 포장 글 · 광고에 여섯 물음을 대고, 판단마다 까닭을 적는다","correct":true},{"t":"공부 시간 글에만 여섯 물음을 댄다","mis":"K6-1-u6-X22"},{"t":"큰 글씨만 읽는다","mis":"K6-1-u6-X15"},{"t":"붙어 있는 글은 그대로 믿는다","mis":"K6-1-u6-X01"}],"explanation":["둘레의 글에도 대어 봐요.","작은 글씨도 봐요.","판단과 까닭을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#22','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C39',3,'mc','auto','같은 문장을 두고 친구와 판단이 달랐어요. 판단을 나누는 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u6-X37','K6-1-u6-X06','K6-1-u6-X45']::text[],false,'{"seq":22,"concept":"K6-1-u6-C39","difficulty":3,"kind":"mc","stem":"같은 문장을 두고 친구와 판단이 달랐어요. 판단을 나누는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 이렇게 판단했어. 까닭은 이거야. 네 까닭도 들어 볼게.」","correct":true},{"t":"「내 말이 맞아. 더 말할 것 없어.」","mis":"K6-1-u6-X37"},{"t":"「그냥 내 느낌이 그래.」","mis":"K6-1-u6-X06"},{"t":"「네가 하는 말은 늘 틀려.」","mis":"K6-1-u6-X45"}],"explanation":["까닭을 들어 봐요.","까닭이 빠졌어요.","사람을 겨누지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#23','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C47',4,'mc','auto','도율이의 초안 전체를 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u6-X42','K6-1-u6-X21','K6-1-u6-X38']::text[],false,'{"seq":23,"concept":"K6-1-u6-C47","difficulty":4,"kind":"mc","stem":"도율이의 초안 전체를 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"주제는 가치 있고 ㄹ은 알맞지만, ㄱ · ㄷ은 사실이 아니고 ㄴ은 부풀려 고쳐 써야 한다","correct":true},{"t":"눈에 띄니 그대로 써도 된다","mis":"K6-1-u6-X42"},{"t":"걸린 문구가 있으니 주제를 바꾼다","mis":"K6-1-u6-X21"},{"t":"내 광고니 고칠 필요가 없다","mis":"K6-1-u6-X38"}],"explanation":["믿을 수 있어야 해요.","주제는 좋아요.","만들 때도 같은 자를 대요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#24','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C43',4,'essay','teacher','도율이의 초안을 고쳐 공익 광고를 완성한다고 할 때, 크게 쓸 한 줄 · 고쳐 쓸 문구 하나 · 발표 때 밝힐 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u6-C43","difficulty":4,"kind":"essay","stem":"도율이의 초안을 고쳐 공익 광고를 완성한다고 할 때, 크게 쓸 한 줄 · 고쳐 쓸 문구 하나 · 발표 때 밝힐 말을 쓰세요.","answer_guide":{"answer":"예: 크게 쓸 한 줄 — 「잠가요, 비누칠하는 동안」. 고쳐 쓸 문구 — ㄴ 「이 광고만 보면 물 낭비가 모두 사라집니다」를 「한 사람이 잠그면 한 컵만큼 물이 남습니다」로 고친다. 발표 — 「수돗가에서 물이 흐르는 것을 보고 이 주제를 골랐어요. 물줄기를 일부러 크게 그린 까닭은 낭비를 한눈에 보여 주고 싶어서예요.」","scoring_points":["크게 쓸 한 줄을 알맞게 골랐는가","걸린 문구를 알맞게 고쳤는가","발표 때 까닭을 밝혔는가"]},"explanation":["한 줄만 크게 해요.","부풀린 말을 덜어요.","손댄 곳의 까닭을 밝혀요."],"asset":{"type":"passage","lines":["장면 — 비누 거품이 묻은 손 아래로 물이 콸콸 흐르는 그림","ㄱ. 물을 틀어 두면 지구의 물이 하루 만에 말라 버립니다!","ㄴ. 이 광고만 보면 물 낭비가 모두 사라집니다.","ㄷ. 비누칠할 때 물을 틀어 두면 무조건 벌금!","ㄹ. 잠가요, 비누칠하는 동안"],"title":"도율의 공익 광고 초안 (흠을 일부러 넣은 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u6_review_d#25','kor',6,1,'u6','','g6_1_kor_u6_review_d','unit_review','K6-1-u6-C38',4,'essay','teacher','내 둘레에서 한쪽 이야기만 담은 글이나 광고를 하나 떠올려, 다른 관점의 물음 두 가지와 그 답을 찾을 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u6-C38","difficulty":4,"kind":"essay","stem":"내 둘레에서 한쪽 이야기만 담은 글이나 광고를 하나 떠올려, 다른 관점의 물음 두 가지와 그 답을 찾을 방법을 쓰세요.","answer_guide":{"answer":"예: 학교 앞 문구점의 「새로 나온 필통, 무엇이든 다 들어가요」 광고는 좋은 점만 담았다. 물음 — 「무겁지는 않을까?」, 「쉽게 망가지지는 않을까?」 써 본 친구에게 여쭈어 보거나, 물건 상자에 적힌 무게와 사용 안내를 읽어 보겠다. 한쪽 이야기만 듣고 고르면 나중에 후회할 수 있기 때문이다.","scoring_points":["한쪽 이야기만 담은 글을 떠올렸는가","다른 관점의 물음을 두 가지 썼는가","답을 찾을 방법을 썼는가"]},"explanation":["좋은 점만 말한 글을 떠올려요.","다른 쪽에서 물어요.","찾아갈 길을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
